/* LZMA1/LZMA2 shared definitions: probability model, range coder */
#ifndef LZMA_H
#define LZMA_H

#include <stddef.h>
#include <stdint.h>

#define LZMA_STATES 12
#define LZMA_POS_STATES_MAX 4
#define LZMA_POS_STATES (1 << LZMA_POS_STATES_MAX)
#define LZMA_POS_SLOTS 64
#define LZMA_END_POS_MODEL_INDEX 14
#define LZMA_FULL_DISTANCES (1 << LZMA_END_POS_MODEL_INDEX)
#define LZMA_ALIGN_BITS 4
#define LZMA_MATCH_MIN_LEN 2
#define LZMA_NUM_REPS 4
#define LZMA_LIT_STATES 7

#define LZMA_PROB_BITS 11
#define LZMA_PROB_TOTAL (1 << LZMA_PROB_BITS)
#define LZMA_MOVE_BITS 5

/* Match finder types */
#define MF_HC3 0
#define MF_HC4 1
#define MF_BT2 2
#define MF_BT3 3
#define MF_BT4 4

/* Compression modes */
#define MODE_FAST 0
#define MODE_NORMAL 1

/* Dictionary size limits for LZMA2 */
#define LZMA2_DICT_MIN 4096U
#define LZMA2_DICT_MAX 1610612736U

/* Return codes */
#define E_OK          0
#define E_STREAM_END  1
#define E_DATA        2   /* Compressed data is corrupt */
#define E_FORMAT      3   /* File format not recognized */
#define E_MEM         4
#define E_OPTIONS     5   /* unsupported options in headers */
#define E_BUF         6   /* Unexpected end of input */
#define E_MEMLIMIT    7
#define E_UNSUPPORTED 8   /* unsupported check/filter */

typedef uint16_t probability;

typedef struct {
	probability is_match[LZMA_STATES << LZMA_POS_STATES_MAX];
	probability is_rep[LZMA_STATES];
	probability is_rep0[LZMA_STATES << LZMA_POS_STATES_MAX];
	probability is_rep1[LZMA_STATES];
	probability is_rep2[LZMA_STATES];
	probability is_rep0_long[LZMA_STATES << LZMA_POS_STATES_MAX];
	probability pos_slot[LZMA_POS_SLOTS];
	probability pos_special[1 + LZMA_FULL_DISTANCES - LZMA_END_POS_MODEL_INDEX];
	probability pos_align[LZMA_ALIGN_BITS];
	probability len_choice;
	probability len_low[LZMA_POS_STATES][8];
	probability len_choice2;
	probability len_mid[LZMA_POS_STATES][8];
	probability len_high[256];
} lzma_probs;

void lzma_probs_init(lzma_probs *p);

/* Number of literal probability entries for given lc/lp */
static inline size_t
lzma_literal_probs_size(uint32_t lc, uint32_t lp)
{
	return (size_t)0x300 << (lc + lp);
}

/* LZMA1 core decoding state */
typedef struct {
	lzma_probs p;
	probability *lit;          /* literal probabilities */
	uint32_t lc, lp, pb;
	uint32_t pos_mask, lp_mask;
	uint32_t state;
	uint32_t reps[LZMA_NUM_REPS];

	/* range decoder */
	const uint8_t *in;
	size_t in_size;
	size_t in_pos;
	uint32_t range;
	uint32_t code;
	int need_init;             /* range decoder not initialized yet */

	/* dictionary / output */
	uint8_t *dict;
	size_t dict_size;          /* dictionary size in use */
	size_t buf_size;           /* allocated size of dict */
	size_t buf_pos;            /* write index */
	uint64_t dict_pos;         /* absolute position of next byte */

	/* output sink */
	void *out_ctx;
	int (*emit)(void *ctx, const uint8_t *data, size_t len);

	int initialized;
} lzma_dec;

int lzma_dec_reset(lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb,
		uint32_t dict_size, void *out_ctx,
		int (*emit)(void *, const uint8_t *, size_t));
/* Feed input; returns E_OK/E_STREAM_END/E_DATA/E_BUF */
int lzma_dec_run(lzma_dec *d, const uint8_t *in, size_t in_size,
		size_t *in_used, int finish);
uint64_t lzma_dec_total(lzma_dec *d);

/* --- shared dictionary helpers --- */
void dict_reset(lzma_dec *d);
int dict_put(lzma_dec *d, uint8_t b);
int dict_copy(lzma_dec *d, uint32_t dist, size_t len);

/* Range encoder */
typedef struct {
	uint64_t low;
	uint32_t range;
	uint8_t cache;
	uint32_t cache_size;
	uint8_t *out;
	size_t out_pos;
	size_t out_size;
	int err;
} rc_enc;

void rc_init(rc_enc *rc, uint8_t *out, size_t out_size);
void rc_flush(rc_enc *rc);
void rc_bit(rc_enc *rc, probability *prob, uint32_t bit);
void rc_direct(rc_enc *rc, uint32_t bits, uint32_t value);
void rc_bit_tree(rc_enc *rc, probability *probs, uint32_t bits, uint32_t value);
void rc_bit_tree_reverse(rc_enc *rc, probability *probs, uint32_t bits,
		uint32_t value);

/* Price helpers for the encoder */
void lzma_price_init(void);
uint32_t rc_bit_price(const probability prob, const uint32_t bit);

/* LZMA2 decoder wrapper */
typedef struct {
	lzma_dec d;
	int need_props;      /* expect props in the next chunk header */
	int dict_reset_next;
	uint32_t lc, lp, pb;
	int finished;
} lzma2_dec;

void lzma2_dec_init(lzma2_dec *s, void *out_ctx,
		int (*emit)(void *, const uint8_t *, size_t));
int lzma2_dec_run(lzma2_dec *s, const uint8_t *in, size_t in_size,
		size_t *in_used);

#endif
EOF
echo ok"}

{"command": "cat > src/lzma_dec.c <<'EOF'
/* LZMA1 core decoder + LZMA2 chunk decoder */
#include "lzma.h"
#include <stdlib.h>
#include <string.h>

#define RC_TOP (1U << 24)
#define RC_MASK (LZMA_PROB_TOTAL - 1)

static void
rc_normalize(lzma_dec *d)
{
	if (d->range < RC_TOP) {
		d->range <<= 8;
		d->code = (d->code << 8) | (d->in_pos < d->in_size
				? d->in[d->in_pos++] : 0);
		if (d->in_pos > d->in_size)
			d->in_pos = d->in_size + 1;   /* mark overrun */
	}
}

static uint32_t
rc_bit_dec(lzma_dec *d, probability *prob)
{
	const uint32_t bound = (d->range >> LZMA_PROB_BITS) * *prob;
	uint32_t bit;
	if (d->code < bound) {
		d->range = bound;
		*prob += (LZMA_PROB_TOTAL - *prob) >> LZMA_MOVE_BITS;
		bit = 0;
	} else {
		d->range -= bound;
		d->code -= bound;
		*prob -= *prob >> LZMA_MOVE_BITS;
		bit = 1;
	}
	rc_normalize(d);
	return bit;
}

static uint32_t
rc_bittree_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rc_bit_dec(d, &probs[symbol]);
	return symbol;
}

static uint32_t
rc_bittree_reverse_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 0, probe = 1;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rc_bit_dec(d, &probs[probe]);
		probe = (probe << 1) + bit;
		symbol |= bit << i;
	}
	return symbol;
}

static uint32_t
rc_direct_dec(lzma_dec *d, uint32_t bits)
{
	uint32_t result = 0;
	do {
		d->range >>= 1;
		d->code -= d->range;
		const uint32_t t = 0U - (d->code >> 31);
		d->code += d->range & t;
		if (d->range < RC_TOP) {
			d->range <<= 8;
			d->code = (d->code << 8) | (d->in_pos < d->in_size
					? d->in[d->in_pos++] : 0);
			if (d->in_pos > d->in_size)
				d->in_pos = d->in_size + 1;
		}
		result = (result << 1) + (t + 1);
	} while (--bits);
	return result;
}

void
lzma_probs_init(lzma_probs *p)
{
	const probability half = LZMA_PROB_TOTAL / 2;
	for (size_t i = 0; i < sizeof(lzma_probs) / sizeof(probability); ++i)
		((probability *)p)[i] = half;
}

void
dict_reset(lzma_dec *d)
{
	d->buf_pos = 0;
	d->dict_pos = 0;
	memset(d->dict, 0, d->buf_size);
}

static void
dict_flush(lzma_dec *d)
{
	const size_t keep = (uint64_t)d->dict_pos < d->dict_size
			? (size_t)d->dict_pos : d->dict_size;
	if (d->buf_pos > keep) {
		const size_t n = d->buf_pos - keep;
		if (d->emit)
			d->emit(d->out_ctx, d->dict, n);
		memmove(d->dict, d->dict + n, keep);
		d->buf_pos = keep;
	}
}

int
dict_put(lzma_dec *d, uint8_t b)
{
	if (d->buf_pos == d->buf_size)
		dict_flush(d);
	d->dict[d->buf_pos++] = b;
	++d->dict_pos;
	return 0;
}

int
dict_copy(lzma_dec *d, uint32_t dist, size_t len)
{
	if ((uint64_t)d->dict_pos <= dist)
		return E_DATA;
	/* Ensure the history is in the buffer */
	if (d->buf_pos <= dist) {
		/* Should not happen if the buffer is large enough */
		return E_DATA;
	}
	for (size_t i = 0; i < len; ++i) {
		const uint8_t b = d->dict[d->buf_pos - 1 - dist];
		if (d->buf_pos == d->buf_size)
			dict_flush(d);
		d->dict[d->buf_pos++] = b;
		++d->dict_pos;
	}
	return 0;
}

int
lzma_dec_reset(lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb,
		uint32_t dict_size, void *out_ctx,
		int (*emit)(void *, const uint8_t *, size_t))
{
	if (lc > 4 || lp > 4 || pb > 4 || lc + lp > 4)
		return E_OPTIONS;
	d->lc = lc;
	d->lp = lp;
	d->pb = pb;
	d->pos_mask = (1U << pb) - 1;
	d->lp_mask = (1U << lp) - 1;
	d->dict_size = dict_size ? dict_size : 1;
	d->out_ctx = out_ctx;
	d->emit = emit;
	d->state = 0;
	d->reps[0] = d->reps[1] = d->reps[2] = d->reps[3] = 0;
	d->buf_pos = 0;
	d->dict_pos = 0;
	d->range = 0;
	d->code = 0;
	d->need_init = 1;
	d->initialized = 0;
	dict_reset(d);
	lzma_probs_init(&d->p);
	return E_OK;
}

/* Set the input buffer for decoding */
static void
dec_set_input(lzma_dec *d, const uint8_t *in, size_t size)
{
	d->in = in;
	d->in_size = size;
	d->in_pos = 0;
}

static void
dec_init_range(lzma_dec *d)
{
	d->code = 0;
	d->range = 0xFFFFFFFFU;
	for (int i = 0; i < 5; ++i) {
		const uint8_t b = d->in_pos < d->in_size ? d->in[d->in_pos++] : 0;
		d->code = (d->code << 8) | b;
	}
	if (d->code == 0xFFFFFFFFU) {
		/* first byte of the stream must not be 0xFF */
	}
	d->need_init = 0;
}

/* Decode one symbol.  Returns 0 on success, E_DATA on corruption. */
static int
dec_symbol(lzma_dec *d)
{
	const uint32_t pos_state = (uint32_t)d->dict_pos & d->pos_mask;
	const uint32_t mi = (d->state << LZMA_POS_STATES_MAX) + pos_state;

	if (!rc_bit_dec(d, &d->p.is_match[mi])) {
		/* Literal */
		const uint8_t prev_byte = d->dict_pos > 0
				&& d->buf_pos > 0 ? d->dict[d->buf_pos - 1] : 0;
		probability *lprobs = d->lit + (((d->dict_pos & d->lp_mask)
				<< d->lc) << 8);
		uint32_t symbol = 1;
		if (d->state >= LZMA_LIT_STATES) {
			/* Matched literal */
			const uint32_t r0 = d->reps[0];
			if ((uint64_t)d->dict_pos <= r0)
				return E_DATA;
			uint32_t match_byte;
			{
				const size_t idx = d->buf_pos - 1 - r0;
				match_byte = idx < d->buf_pos ? d->dict[idx] : 0;
			}
			do {
				const uint32_t match_bit = (match_byte >> 7) & 1;
				match_byte <<= 1;
				const uint32_t bit = rc_bit_dec(d,
						&lprobs[0x100 + (match_bit << 8) + symbol]);
				symbol = (symbol << 1) | bit;
			} while (symbol < 0x100);
		} else {
			do {
				const uint32_t bit = rc_bit_dec(d, &lprobs[symbol]);
				symbol = (symbol << 1) | bit;
			} while (symbol < 0x100);
		}
		d->state = d->state < 4 ? 0 : (d->state < 10 ? d->state - 3
				: d->state - 6);
		dict_put(d, (uint8_t)symbol);
		return 0;
	}

	/* Match */
	if (rc_bit_dec(d, &d->p.is_rep[d->state])) {
		/* Repeated match */
		if (!rc_bit_dec(d, &d->p.is_rep0[mi])) {
			if (!rc_bit_dec(d, &d->p.is_rep0_long[mi])) {
				/* Short rep0 */
				d->state = d->state < 7 ? 9 : 11;
				if ((uint64_t)d->dict_pos <= d->reps[0])
					return E_DATA;
				if (dict_copy(d, d->reps[0], 1))
					return E_DATA;
				return 0;
			}
			/* Long rep match */
			uint32_t dist;
			if (!rc_bit_dec(d, &d->p.is_rep1[d->state])) {
				dist = d->reps[1];
			} else {
				if (!rc_bit_dec(d, &d->p.is_rep2[d->state]))
					dist = d->reps[2];
				else {
					dist = d->reps[3];
					d->reps[3] = d->reps[2];
				}
				d->reps[2] = d->reps[1];
			}
			d->reps[1] = d->reps[0];
			d->reps[0] = dist;
			d->state = d->state < 7 ? 8 : 11;
			uint32_t len = rc_bittree_dec(d,
					d->p.len_low[pos_state], 3);
			if (rc_bit_dec(d, &d->p.len_choice)) {
				len = rc_bittree_dec(d, d->p.len_mid[pos_state], 3) + 8;
				if (rc_bit_dec(d, &d->p.len_choice2))
					len = rc_bittree_dec(d, d->p.len_high, 8) + 16;
			}
			if ((uint64_t)d->dict_pos <= dist)
				return E_DATA;
			return dict_copy(d, dist, len + LZMA_MATCH_MIN_LEN);
		}
		/* New distance, length from the previous match */
		uint32_t len = rc_bittree_dec(d, d->p.len_low[pos_state], 3);
		if (rc_bit_dec(d, &d->p.len_choice)) {
			len = rc_bittree_dec(d, d->p.len_mid[pos_state], 3) + 8;
			if (rc_bit_dec(d, &d->p.len_choice2))
				len = rc_bittree_dec(d, d->p.len_high, 8) + 16;
		}
		d->state = d->state < 7 ? 7 : 10;
		uint32_t pos_slot = rc_bittree_dec(d, d->p.pos_slot, 6);
		uint32_t dist;
		if (pos_slot >= 4) {
			const uint32_t num_direct_bits = (pos_slot >> 1) - 1;
			dist = (2 | (pos_slot & 1)) << num_direct_bits;
			if (pos_slot < LZMA_END_POS_MODEL_INDEX)
				dist += rc_bittree_reverse_dec(d,
					&d->p.pos_special[dist - pos_slot],
					num_direct_bits);
			else {
				dist += rc_direct_dec(d,
					num_direct_bits - LZMA_ALIGN_BITS)
					<< LZMA_ALIGN_BITS;
				dist += rc_bittree_reverse_dec(d, d->p.pos_align,
					LZMA_ALIGN_BITS);
			}
		} else {
			dist = pos_slot;
		}
		if (dist == 0xFFFFFFFFU) {
			/* End marker: the length is ignored */
			return E_STREAM_END;
		}
		d->reps[3] = d->reps[2];
		d->reps[2] = d->reps[1];
		d->reps[1] = d->reps[0];
		d->reps[0] = dist;
		if ((uint64_t)d->dict_pos <= dist)
			return E_DATA;
		return dict_copy(d, dist, len + LZMA_MATCH_MIN_LEN);
	}

	/* Simple match */
	uint32_t len = rc_bittree_dec(d, d->p.len_low[pos_state], 3);
	if (rc_bit_dec(d, &d->p.len_choice)) {
		len = rc_bittree_dec(d, d->p.len_mid[pos_state], 3) + 8;
		if (rc_bit_dec(d, &d->p.len_choice2))
			len = rc_bittree_dec(d, d->p.len_high, 8) + 16;
	}
	uint32_t pos_slot = rc_bittree_dec(d, d->p.pos_slot, 6);
	uint32_t dist;
	if (pos_slot >= 4) {
		const uint32_t num_direct_bits = (pos_slot >> 1) - 1;
		dist = (2 | (pos_slot & 1)) << num_direct_bits;
		if (pos_slot < LZMA_END_POS_MODEL_INDEX)
			dist += rc_bittree_reverse_dec(d,
				&d->p.pos_special[dist - pos_slot],
				num_direct_bits);
		else {
			dist += rc_direct_dec(d, num_direct_bits - LZMA_ALIGN_BITS)
				<< LZMA_ALIGN_BITS;
			dist += rc_bittree_reverse_dec(d, d->p.pos_align,
				LZMA_ALIGN_BITS);
		}
	} else {
		dist = pos_slot;
	}
	if (dist == 0xFFFFFFFFU)
		return E_STREAM_END;
	d->state = d->state < 7 ? 7 : 10;
	d->reps[3] = d->reps[2];
	d->reps[2] = d->reps[1];
	d->reps[1] = d->reps[0];
	d->reps[0] = dist;
	if (dist >= d->dict_size)
		return E_DATA;
	if ((uint64_t)d->dict_pos <= dist)
		return E_DATA;
	return dict_copy(d, dist, len + LZMA_MATCH_MIN_LEN);
}

int
lzma_dec_run(lzma_dec *d, const uint8_t *in, size_t in_size,
		size_t *in_used, int finish)
{
	if (d->need_init) {
		dec_set_input(d, in, in_size);
		dec_init_range(d);
		d->need_init = 0;
		/* the first byte of the LZMA stream must not be 0xFF */
		if (d->code == 0xFFFFFFFFU)
			return E_DATA;
	} else {
		dec_set_input(d, in, in_size);
	}
	int ret = E_OK;
	while (d->in_pos <= d->in_size) {
		if (d->in_pos == d->in_size && !finish)
			break;
		ret = dec_symbol(d);
		if (ret != E_OK)
			break;
		if (d->in_pos > d->in_size) {
			if (finish) {
				ret = E_BUF;
				break;
			}
			/* rolled back: undo the byte overread */
			d->in_pos = d->in_size;
			ret = E_BUF;
			break;
		}
	}
	if (ret == E_BUF && d->in_pos <= d->in_size)
		ret = E_BUF;
	*in_used = d->in_pos > d->in_size ? d->in_size : d->in_pos;
	if (ret == E_BUF && d->in_pos < d->in_size)
		ret = E_BUF;
	return ret;
}

uint64_t
lzma_dec_total(lzma_dec *d)
{
	return d->dict_pos;
}
