/* LZMA1 core decoder + LZMA2 chunk decoder */
#include "lzma.h"
#include <stdlib.h>
#include <string.h>

#define RC_TOP (1U << 24)
#define RC_MASK (LZMA_PROB_TOTAL - 1)

static void
rc_normalize(lzma_dec *d)
{
	if (d->range < RC_TOP) {
		d->range <<= 8;
		d->code = (d->code << 8) | (d->in_pos < d->in_size
				? d->in[d->in_pos++] : 0);
		if (d->in_pos > d->in_size)
			d->in_pos = d->in_size + 1;   /* mark overrun */
	}
}

static uint32_t
rc_bit_dec(lzma_dec *d, probability *prob)
{
	const uint32_t bound = (d->range >> LZMA_PROB_BITS) * *prob;
	uint32_t bit;
	if (d->code < bound) {
		d->range = bound;
		*prob += (LZMA_PROB_TOTAL - *prob) >> LZMA_MOVE_BITS;
		bit = 0;
	} else {
		d->range -= bound;
		d->code -= bound;
		*prob -= *prob >> LZMA_MOVE_BITS;
		bit = 1;
	}
	rc_normalize(d);
	return bit;
}

static uint32_t
rc_bittree_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rc_bit_dec(d, &probs[symbol]);
	return symbol;
}

static uint32_t
rc_bittree_reverse_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 0, probe = 1;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rc_bit_dec(d, &probs[probe]);
		probe = (probe << 1) + bit;
		symbol |= bit << i;
	}
	return symbol;
}

static uint32_t
rc_direct_dec(lzma_dec *d, uint32_t bits)
{
	uint32_t result = 0;
	do {
		d->range >>= 1;
		d->code -= d->range;
		const uint32_t t = 0U - (d->code >> 31);
		d->code += d->range & t;
		if (d->range < RC_TOP) {
			d->range <<= 8;
			d->code = (d->code << 8) | (d->in_pos < d->in_size
