			dist = (2 | (pos_slot & 1)) << num_direct_bits;
			if (pos_slot < LZMA_END_POS_MODEL_INDEX)
				dist += rc_bittree_reverse_dec(d,
					&d->p.pos_special[dist - pos_slot],
					num_direct_bits);
			else {
				dist += rc_direct_dec(d,
					num_direct_bits - LZMA_ALIGN_BITS)
					<< LZMA_ALIGN_BITS;
				dist += rc_bittree_reverse_dec(d, d->p.pos_align,
					LZMA_ALIGN_BITS);
			}
		} else {
			dist = pos_slot;
		}
		if (dist == 0xFFFFFFFFU) {
			/* End marker: the length is ignored */
			return E_STREAM_END;
		}
		d->reps[3] = d->reps[2];
		d->reps[2] = d->reps[1];
		d->reps[1] = d->reps[0];
		d->reps[0] = dist;
		if ((uint64_t)d->dict_pos <= dist)
			return E_DATA;
		return dict_copy(d, dist, len + LZMA_MATCH_MIN_LEN);
	}

	/* Simple match */
	uint32_t len = rc_bittree_dec(d, d->p.len_low[pos_state], 3);
	if (rc_bit_dec(d, &d->p.len_choice)) {
		len = rc_bittree_dec(d, d->p.len_mid[pos_state], 3) + 8;
		if (rc_bit_dec(d, &d->p.len_choice2))
			len = rc_bittree_dec(d, d->p.len_high, 8) + 16;
	}
	uint32_t pos_slot = rc_bittree_dec(d, d->p.pos_slot, 6);
	uint32_t dist;
	if (pos_slot >= 4) {
		const uint32_t num_direct_bits = (pos_slot >> 1) - 1;
		dist = (2 | (pos_slot & 1)) << num_direct_bits;
		if (pos_slot < LZMA_END_POS_MODEL_INDEX)
			dist += rc_bittree_reverse_dec(d,
				&d->p.pos_special[dist - pos_slot],
				num_direct_bits);
		else {
			dist += rc_direct_dec(d, num_direct_bits - LZMA_ALIGN_BITS)
				<< LZMA_ALIGN_BITS;
			dist += rc_bittree_reverse_dec(d, d->p.pos_align,
				LZMA_ALIGN_BITS);
		}
	} else {
		dist = pos_slot;
	}
	if (dist == 0xFFFFFFFFU)
		return E_STREAM_END;
	d->state = d->state < 7 ? 7 : 10;
	d->reps[3] = d->reps[2];
	d->reps[2] = d->reps[1];
	d->reps[1] = d->reps[0];
	d->reps[0] = dist;
	if (dist >= d->dict_size)
		return E_DATA;
	if ((uint64_t)d->dict_pos <= dist)
		return E_DATA;
	return dict_copy(d, dist, len + LZMA_MATCH_MIN_LEN);
}

int
lzma_dec_run(lzma_dec *d, const uint8_t *in, size_t in_size,
		size_t *in_used, int finish)
{
	if (d->need_init) {
		dec_set_input(d, in, in_size);
		dec_init_range(d);
		d->need_init = 0;
		/* the first byte of the LZMA stream must not be 0xFF */
		if (d->code == 0xFFFFFFFFU)
			return E_DATA;
	} else {
		dec_set_input(d, in, in_size);
	}
	int ret = E_OK;
	while (d->in_pos <= d->in_size) {
		if (d->in_pos == d->in_size && !finish)
			break;
		ret = dec_symbol(d);
		if (ret != E_OK)
			break;
		if (d->in_pos > d->in_size) {
			if (finish) {
				ret = E_BUF;
				break;
			}
			/* rolled back: undo the byte overread */
			d->in_pos = d->in_size;
			ret = E_BUF;
			break;
		}
	}
	if (ret == E_BUF && d->in_pos <= d->in_size)
		ret = E_BUF;
	*in_used = d->in_pos > d->in_size ? d->in_size : d->in_pos;
	if (ret == E_BUF && d->in_pos < d->in_size)
		ret = E_BUF;
	return ret;
}

uint64_t
lzma_dec_total(lzma_dec *d)
{
	return d->dict_pos;
}
EOF
