{"command": "cat > src/lzma_dec.c <<'EOF'
/* LZMA1 core decoder + LZMA2 chunk decoder */
#include "lzma.h"
#include <stdlib.h>
#include <string.h>

#define RC_TOP (1U << 24)

/* ---------------- input source ---------------- */

void
src_init(in_src *s, void *ctx, size_t (*read)(void *, uint8_t *, size_t))
{
	s->pos = s->len = 0;
	s->eof = 0;
	s->consumed = 0;
	s->ctx = ctx;
	s->read = read;
}

int
src_get(in_src *s)
{
	if (s->pos == s->len) {
		if (s->eof)
			return -1;
		const size_t n = s->read(s->ctx, s->buf, sizeof(s->buf));
		s->pos = 0;
		s->len = n;
		if (n == 0) {
			s->eof = 1;
			return -1;
		}
	}
	++s->consumed;
	return s->buf[s->pos++];
}

/* ---------------- dictionary ---------------- */

void
dict_reset(lzma_dec *d)
{
	d->buf_pos = 0;
	d->dict_pos = 0;
	memset(d->dict, 0, d->buf_size);
}

static void
dict_flush(lzma_dec *d)
{
	const size_t keep = (uint64_t)d->dict_pos < d->dict_size
			? (size_t)d->dict_pos : d->dict_size;
	if (d->buf_pos > keep) {
		const size_t n = d->buf_pos - keep;
		if (d->emit)
			d->emit(d->out_ctx, d->dict, n);
		memmove(d->dict, d->dict + n, keep);
		d->buf_pos = keep;
	}
}

int
dict_put(lzma_dec *d, uint8_t b)
{
	if (d->buf_pos == d->buf_size)
		dict_flush(d);
	d->dict[d->buf_pos++] = b;
	++d->dict_pos;
	return 0;
}

int
dict_copy(lzma_dec *d, uint32_t dist, size_t len)
{
	if ((uint64_t)d->dict_pos <= dist)
		return E_DATA;
	if (d->buf_pos <= dist)
		return E_DATA;
	if (dist >= d->dict_size)
		return E_DATA;
	for (size_t i = 0; i < len; ++i) {
		const uint8_t b = d->dict[d->buf_pos - 1 - dist];
		if (d->buf_pos == d->buf_size)
			dict_flush(d);
		d->dict[d->buf_pos++] = b;
		++d->dict_pos;
	}
	return 0;
}

void
lzma_probs_init(lzma_probs *p)
{
	const probability half = LZMA_PROB_TOTAL / 2;
	for (size_t i = 0; i < sizeof(lzma_probs) / sizeof(probability); ++i)
		((probability *)p)[i] = half;
}

/* ---------------- range decoder ---------------- */

static void
rc_normalize(lzma_dec *d)
{
	while (d->range < RC_TOP) {
		const int b = src_get(&d->src);
		if (b < 0)
			return;
		d->range <<= 8;
		d->code = (d->code << 8) | (uint32_t)b;
	}
}

static uint32_t
rc_bit_dec(lzma_dec *d, probability *prob)
{
	const uint32_t bound = (d->range >> LZMA_PROB_BITS) * (uint32_t)*prob;
	uint32_t bit;
	if (d->code < bound) {
		d->range = bound;
		*prob += (LZMA_PROB_TOTAL - (uint32_t)*prob) >> LZMA_MOVE_BITS;
		bit = 0;
	} else {
		d->range -= bound;
		d->code -= bound;
		*prob -= (uint32_t)*prob >> LZMA_MOVE_BITS;
		bit = 1;
	}
	rc_normalize(d);
	return bit;
}

static uint32_t
rc_bittree_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rc_bit_dec(d, &probs[symbol]);
	return symbol;
}

static uint32_t
rc_bittree_reverse_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 0, probe = 1;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rc_bit_dec(d, &probs[probe]);
		probe = (probe << 1) + bit;
		symbol |= bit << i;
	}
	return symbol;
}

static uint32_t
rc_direct_dec(lzma_dec *d, uint32_t bits)
{
	uint32_t result = 0;
	do {
		d->range >>= 1;
		d->code -= d->range;
		const uint32_t t = 0U - (d->code >> 31);
		d->code += d->range & t;
		if (d->range < RC_TOP) {
			const int b = src_get(&d->src);
			if (b < 0)
				return result;
			d->range <<= 8;
			d->code = (d->code << 8) | (uint32_t)b;
		}
		result = (result << 1) + (t + 1);
	} while (--bits);
	return result;
}

/* ---------------- decoder reset ---------------- */

int
lzma_dec_reset(lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb,
		uint32_t dict_size, void *out_ctx,
		int (*emit)(void *, const uint8_t *, size_t))
{
	if (lc > 4 || lp > 4 || pb > 4 || lc + lp > 4)
		return E_OPTIONS;
	d->lc = lc;
	d->lp = lp;
	d->pb = pb;
	d->pos_mask = (1U << pb) - 1;
	d->lp_mask = (1U << lp) - 1;
	d->dict_size = dict_size;
	d->out_ctx = out_ctx;
	d->emit = emit;
	d->state = 0;
	d->reps[0] = d->reps[1] = d->reps[2] = d->reps[3] = 0;
	d->buf_pos = 0;
	d->dict_pos = 0;
	d->range = 0;
	d->code = 0;
	d->need_init = 1;
	d->out_limit = 0;
	d->expect_end_marker = 0;
	dict_reset(d);
	lzma_probs_init(&d->p);
	return E_OK;
}

void
lzma_dec_free_dict(lzma_dec *d)
{
	free(d->dict);
	d->dict = NULL;
	d->buf_size = 0;
}

/* ---------------- symbol decoding ---------------- */

static uint32_t
dec_length(lzma_dec *d, uint32_t pos_state)
{
	uint32_t len = rc_bittree_dec(d, d->p.len_low[pos_state], 3);
	if (rc_bit_dec(d, &d->p.len_choice)) {
		len = rc_bittree_dec(d, d->p.len_mid[pos_state], 3) + 8;
		if (rc_bit_dec(d, &d->p.len_choice2))
			len = rc_bittree_dec(d, d->p.len_high, 8) + 16;
	}
	return len + LZMA_MATCH_MIN_LEN;
}

static uint32_t
dec_distance(lzma_dec *d, uint32_t *state_new)
{
	uint32_t pos_slot = rc_bittree_dec(d, d->p.pos_slot, 6);
	uint32_t dist;
	(void)state_new;
	if (pos_slot >= 4) {
		const uint32_t num_direct_bits = (pos_slot >> 1) - 1;
		dist = (2 | (pos_slot & 1)) << num_direct_bits;
		if (pos_slot < LZMA_END_POS_MODEL_INDEX)
			dist += rc_bittree_reverse_dec(d,
				&d->p.pos_special[dist - pos_slot],
				num_direct_bits);
		else {
			dist += rc_direct_dec(d, num_direct_bits - LZMA_ALIGN_BITS)
				<< LZMA_ALIGN_BITS;
			dist += rc_bittree_reverse_dec(d, d->p.pos_align,
				LZMA_ALIGN_BITS);
		}
	} else {
		dist = pos_slot;
	}
	return dist;
}

static int
dec_symbol(lzma_dec *d)
{
	const uint32_t pos_state = (uint32_t)d->dict_pos & d->pos_mask;
	const uint32_t mi = (d->state << LZMA_POS_STATES_MAX) + pos_state;

	if (!rc_bit_dec(d, &d->p.is_match[mi])) {
		/* Literal */
		uint8_t prev_byte = 0;
		if (d->buf_pos > 0)
			prev_byte = d->dict[d->buf_pos - 1];
		probability *lprobs = d->lit + (((d->dict_pos & d->lp_mask)
				<< d->lc) << 8);
		uint32_t symbol = 1;
		if (d->state >= LZMA_LIT_STATES) {
			const uint32_t r0 = d->reps[0];
			if ((uint64_t)d->dict_pos <= r0)
				return E_DATA;
			if (d->buf_pos <= r0)
				return E_DATA;
			uint32_t match_byte = d->dict[d->buf_pos - 1 - r0];
			do {
				const uint32_t match_bit = (match_byte >> 7) & 1;
				match_byte <<= 1;
				const uint32_t bit = rc_bit_dec(d,
					&lprobs[0x100 + (match_bit << 8) + symbol]);
				symbol = (symbol << 1) | bit;
			} while (symbol < 0x100);
		} else {
			do {
				const uint32_t bit = rc_bit_dec(d, &lprobs[symbol]);
				symbol = (symbol << 1) | bit;
			} while (symbol < 0x100);
		}
		d->state = d->state < 4 ? 0 : (d->state < 10 ? d->state - 3
				: d->state - 6);
		dict_put(d, (uint8_t)symbol);
		return 0;
	}

	/* Match */
	if (rc_bit_dec(d, &d->p.is_rep[d->state])) {
		/* Repeated match */
		if (!rc_bit_dec(d, &d->p.is_rep0[mi])) {
			if (!rc_bit_dec(d, &d->p.is_rep0_long[mi])) {
				d->state = d->state < 7 ? 9 : 11;
				if ((uint64_t)d->dict_pos <= d->reps[0])
					return E_DATA;
				if (d->reps[0] >= d->dict_size)
					return E_DATA;
				if (d->buf_pos <= d->reps[0])
					return E_DATA;
				return dict_copy(d, d->reps[0], 1);
			}
			uint32_t dist;
			if (!rc_bit_dec(d, &d->p.is_rep1[d->state])) {
				dist = d->reps[1];
			} else {
				if (!rc_bit_dec(d, &d->p.is_rep2[d->state])) {
					dist = d->reps[2];
				} else {
					dist = d->reps[3];
					d->reps[3] = d->reps[2];
				}
				d->reps[2] = d->reps[1];
			}
			d->reps[1] = d->reps[0];
			d->reps[0] = dist;
			d->state = d->state < 7 ? 8 : 11;
			const uint32_t len = dec_length(d, pos_state);
			if (dist >= d->dict_size)
				return E_DATA;
			if ((uint64_t)d->dict_pos <= dist)
				return E_DATA;
			if (d->buf_pos <= dist)
				return E_DATA;
			return dict_copy(d, dist, len);
		}
		/* New distance, length from the previous match */
		const uint32_t len = dec_length(d, pos_state);
		d->state = d->state < 7 ? 7 : 10;
		uint32_t dist = dec_distance(d, NULL);
		if (dist == 0xFFFFFFFFU)
			return E_STREAM_END;
		d->reps[3] = d->reps[2];
		d->reps[2] = d->reps[1];
		d->reps[1] = d->reps[0];
		d->reps[0] = dist;
		if (dist >= d->dict_size)
			return E_DATA;
		if ((uint64_t)d->dict_pos <= dist)
			return E_DATA;
		if (d->buf_pos <= dist)
			return E_DATA;
		return dict_copy(d, dist, len);
	}

	/* Simple match */
	const uint32_t len = dec_length(d, pos_state);
	uint32_t dist = dec_distance(d, NULL);
	if (dist == 0xFFFFFFFFU)
		return E_STREAM_END;
	d->state = d->state < 7 ? 7 : 10;
	d->reps[3] = d->reps[2];
	d->reps[2] = d->reps[1];
	d->reps[1] = d->reps[0];
	d->reps[0] = dist;
	if (dist >= d->dict_size)
		return E_DATA;
	if ((uint64_t)d->dict_pos <= dist)
		return E_DATA;
	if (d->buf_pos <= dist)
		return E_DATA;
	return dict_copy(d, dist, len);
}

int
lzma_dec_run(lzma_dec *d)
{
	if (d->need_init) {
		d->code = 0;
		d->range = 0xFFFFFFFFU;
		for (int i = 0; i < 5; ++i) {
			const int b = src_get(&d->src);
			if (b < 0)
				return E_BUF;
			d->code = (d->code << 8) | (uint32_t)b;
		}
		if (d->code == 0xFFFFFFFFU)
			return E_DATA;
		d->need_init = 0;
	}
	for (;;) {
		if (d->out_limit && d->dict_pos >= d->out_limit)
			return E_STREAM_END;
		const int ret = dec_symbol(d);
		if (ret != E_OK)
			return ret;
	}
}

uint64_t
lzma_dec_total(lzma_dec *d)
{
	return d->dict_pos;
}

/* ---------------- LZMA2 ---------------- */

void
lzma2_dec_init(lzma2_dec *s, void *out_ctx,
		int (*emit)(void *, const uint8_t *, size_t))
{
	memset(s, 0, sizeof(*s));
	s->d.out_ctx = out_ctx;
	s->d.emit = emit;
	s->need_props = 1;
	s->have_props = 0;
}

/* A source that reads at most `limit` bytes from the underlying reader */
typedef struct {
	in_src *parent;
	size_t left;
} limit_src;

static size_t
limit_read(void *ctx, uint8_t *dst, size_t n)
{
	limit_src *l = ctx;
	if (l->left == 0)
		return 0;
	if (n > l->left)
		n = l->left;
	const size_t got = l->parent->read(l->parent->ctx, dst, n);
	l->left -= got;
	return got;
}

int
lzma2_dec_run(lzma2_dec *s)
{
	/* LZMA2 chunk loop: reads chunk headers from the input source */
	for (;;) {
		uint8_t hdr[5];
		for (int i = 0; i < 1; ++i) {
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			hdr[0] = (uint8_t)b;
		}
		const uint32_t control = hdr[0];

		if (control == 0x00)
			return E_STREAM_END;

		if (control == 0x01 || control == 0x02) {
			uint8_t sz[2];
			for (int i = 0; i < 2; ++i) {
				const int b = src_get(&s->d.src);
				if (b < 0)
					return E_BUF;
				sz[i] = (uint8_t)b;
			}
			const uint32_t size = ((uint32_t)sz[0] << 8 | sz[1]) + 1;
			if (control == 0x01) {
				dict_reset(&s->d);
				if (s->have_props)
					s->need_props = 1;
			}
			for (uint32_t i = 0; i < size; ++i) {
				const int b = src_get(&s->d.src);
				if (b < 0)
					return E_BUF;
				dict_put(&s->d, (uint8_t)b);
			}
			continue;
		}

		if (control < 0x80)
			return E_DATA;

		/* Compressed chunk */
		uint8_t sz[4];
		for (int i = 0; i < 4; ++i) {
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			sz[i] = (uint8_t)b;
		}
		const uint32_t unpacked = (((control & 0x1F) << 16)
				| ((uint32_t)sz[0] << 8 | sz[1])) + 1;
		const uint32_t packed = ((uint32_t)sz[2] << 8 | sz[3]) + 1;

		if (control & 0x40) {
			dict_reset(&s->d);
		}
		if (control & 0x20) {
			/* New LZMA properties */
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			const uint32_t props = (uint32_t)b;
			if (props >= 9 * 5 * 5)
				return E_DATA;
			const uint32_t lc = props % 9;
			const uint32_t rem = props / 9;
			const uint32_t lp = rem % 5;
			const uint32_t pb = rem / 5;
			if (lc + lp > 4)
				return E_DATA;
			if (s->have_props && (s->d.lc != lc || s->d.lp != lp
					|| s->d.pb != pb))
				return E_DATA;
			s->d.lc = lc;
			s->d.lp = lp;
			s->d.pb = pb;
			s->d.pos_mask = (1U << pb) - 1;
			s->d.lp_mask = (1U << lp) - 1;
			s->have_props = 1;
			s->d.need_init = 1;
			s->d.state = 0;
			s->d.reps[0] = s->d.reps[1] = s->d.reps[2] = s->d.reps[3] = 0;
			lzma_probs_init(&s->d.p);
		} else if (!s->have_props) {
			return E_DATA;
		}

		/* Decode the chunk */
		limit_src lim;
		lim.parent = &s->d.src;
		lim.left = packed;
		in_src saved = s->d.src;
		src_init(&s->d.src, &lim, limit_read);
		s->d.out_limit = s->d.dict_pos + unpacked;
		const int ret = lzma_dec_run(&s->d);
		const uint64_t got = s->d.src.consumed;
		s->d.src = saved;
		if (ret != E_STREAM_END)
			return ret == E_OK ? E_BUF : ret;
		if (got != packed)
			return E_DATA;
	}
}
