#include <stdlib.h>
#include <string.h>

#define RC_TOP (1U << 24)

/* ---------------- input source ---------------- */

void
src_init(in_src *s, void *ctx, size_t (*read)(void *, uint8_t *, size_t))
{
	s->pos = s->len = 0;
	s->eof = 0;
	s->consumed = 0;
	s->ctx = ctx;
