/* ---------------- range decoder ---------------- */

static void
rc_normalize(lzma_dec *d)
{
	while (d->range < RC_TOP) {
		const int b = src_get(&d->src);
		if (b < 0)
			return;
		d->range <<= 8;
		d->code = (d->code << 8) | (uint32_t)b;
	}
}

static uint32_t
rc_bit_dec(lzma_dec *d, probability *prob)
{
	const uint32_t bound = (d->range >> LZMA_PROB_BITS) * (uint32_t)*prob;
	uint32_t bit;
	if (d->code < bound) {
		d->range = bound;
		*prob += (LZMA_PROB_TOTAL - (uint32_t)*prob) >> LZMA_MOVE_BITS;
		bit = 0;
	} else {
		d->range -= bound;
		d->code -= bound;
		*prob -= (uint32_t)*prob >> LZMA_MOVE_BITS;
		bit = 1;
	}
	rc_normalize(d);
	return bit;
}

static uint32_t
rc_bittree_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rc_bit_dec(d, &probs[symbol]);
	return symbol;
}

static uint32_t
rc_bittree_reverse_dec(lzma_dec *d, probability *probs, uint32_t bits)
{
	uint32_t symbol = 0, probe = 1;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rc_bit_dec(d, &probs[probe]);
		probe = (probe << 1) + bit;
		symbol |= bit << i;
	}
	return symbol;
}

static uint32_t
rc_direct_dec(lzma_dec *d, uint32_t bits)
{
