/* A source that reads at most `limit` bytes from the underlying reader */
typedef struct {
	in_src *parent;
	size_t left;
} limit_src;

static size_t
limit_read(void *ctx, uint8_t *dst, size_t n)
{
	limit_src *l = ctx;
	if (l->left == 0)
		return 0;
	if (n > l->left)
		n = l->left;
	const size_t got = l->parent->read(l->parent->ctx, dst, n);
	l->left -= got;
	return got;
}

int
lzma2_dec_run(lzma2_dec *s)
{
	/* LZMA2 chunk loop: reads chunk headers from the input source */
	for (;;) {
		uint8_t hdr[5];
		for (int i = 0; i < 1; ++i) {
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			hdr[0] = (uint8_t)b;
		}
		const uint32_t control = hdr[0];

		if (control == 0x00)
			return E_STREAM_END;

		if (control == 0x01 || control == 0x02) {
			uint8_t sz[2];
			for (int i = 0; i < 2; ++i) {
				const int b = src_get(&s->d.src);
				if (b < 0)
					return E_BUF;
				sz[i] = (uint8_t)b;
			}
			const uint32_t size = ((uint32_t)sz[0] << 8 | sz[1]) + 1;
			if (control == 0x01) {
				dict_reset(&s->d);
				if (s->have_props)
					s->need_props = 1;
			}
			for (uint32_t i = 0; i < size; ++i) {
				const int b = src_get(&s->d.src);
				if (b < 0)
					return E_BUF;
				dict_put(&s->d, (uint8_t)b);
			}
			continue;
		}

		if (control < 0x80)
			return E_DATA;

		/* Compressed chunk */
		uint8_t sz[4];
		for (int i = 0; i < 4; ++i) {
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			sz[i] = (uint8_t)b;
		}
		const uint32_t unpacked = (((control & 0x1F) << 16)
				| ((uint32_t)sz[0] << 8 | sz[1])) + 1;
		const uint32_t packed = ((uint32_t)sz[2] << 8 | sz[3]) + 1;

		if (control & 0x40) {
			dict_reset(&s->d);
		}
		if (control & 0x20) {
			/* New LZMA properties */
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			const uint32_t props = (uint32_t)b;
			if (props >= 9 * 5 * 5)
				return E_DATA;
