		} else if (!s->have_props) {
			return E_DATA;
		}

		/* Decode the chunk */
		limit_src lim;
		lim.parent = &s->d.src;
		lim.left = packed;
		in_src saved = s->d.src;
		src_init(&s->d.src, &lim, limit_read);
		s->d.out_limit = s->d.dict_pos + unpacked;
		const int ret = lzma_dec_run(&s->d);
		const uint64_t got = s->d.src.consumed;
		s->d.src = saved;
		if (ret != E_STREAM_END)
			return ret == E_OK ? E_BUF : ret;
		if (got != packed)
			return E_DATA;
	}
}
