			}
			continue;
		}

		if (control < 0x80)
			return E_DATA;

		/* Compressed chunk */
		uint8_t sz[4];
		for (int i = 0; i < 4; ++i) {
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			sz[i] = (uint8_t)b;
		}
		const uint32_t unpacked = (((control & 0x1F) << 16)
				| ((uint32_t)sz[0] << 8 | sz[1])) + 1;
		const uint32_t packed = ((uint32_t)sz[2] << 8 | sz[3]) + 1;

		if (control & 0x40) {
			dict_reset(&s->d);
		}
		if (control & 0x20) {
			/* New LZMA properties */
			const int b = src_get(&s->d.src);
			if (b < 0)
				return E_BUF;
			const uint32_t props = (uint32_t)b;
			if (props >= 9 * 5 * 5)
				return E_DATA;
			const uint32_t lc = props % 9;
			const uint32_t rem = props / 9;
			const uint32_t lp = rem % 5;
			const uint32_t pb = rem / 5;
			if (lc + lp > 4)
				return E_DATA;
			if (s->have_props && (s->d.lc != lc || s->d.lp != lp
					|| s->d.pb != pb))
				return E_DATA;
			s->d.lc = lc;
			s->d.lp = lp;
			s->d.pb = pb;
			s->d.pos_mask = (1U << pb) - 1;
			s->d.lp_mask = (1U << lp) - 1;
			s->have_props = 1;
			s->d.need_init = 1;
			s->d.state = 0;
			s->d.reps[0] = s->d.reps[1] = s->d.reps[2] = s->d.reps[3] = 0;
			lzma_probs_init(&s->d.p);
		} else if (!s->have_props) {
			return E_DATA;
		}

		/* Decode the chunk */
		limit_src lim;
		lim.parent = &s->d.src;
		lim.left = packed;
		in_src saved = s->d.src;
		src_init(&s->d.src, &lim, limit_read);
		s->d.out_limit = s->d.dict_pos + unpacked;
		const int ret = lzma_dec_run(&s->d);
		const uint64_t got = s->d.src.consumed;
		s->d.src = saved;
		if (ret != E_STREAM_END)
			return ret == E_OK ? E_BUF : ret;
		if (got != packed)
			return E_DATA;
	}
}
