#ifndef FILTERS_H
#define FILTERS_H

#include <stddef.h>
#include <stdint.h>

/* Filter IDs */
#define FILTER_ID_DELTA   0x03
#define FILTER_ID_X86     0x04
#define FILTER_ID_POWERPC 0x05
#define FILTER_ID_IA64    0x06
#define FILTER_ID_ARM     0x07
#define FILTER_ID_ARMTHUMB 0x08
#define FILTER_ID_SPARC   0x09
#define FILTER_ID_ARM64   0x0A
#define FILTER_ID_RISCV   0x0B

#define FILTER_DELTA 3
#define FILTER_BCJ   4

typedef struct {
	uint32_t id;      /* filter id */
	uint32_t type;    /* FILTER_DELTA or FILTER_BCJ */
	uint32_t start;   /* BCJ start offset */
	uint32_t dist;    /* delta distance */
} filter_opt;

