#include "filters.h"
#include <string.h>

uint32_t
filter_props_size(uint32_t id)
{
	switch (id) {
	case FILTER_ID_DELTA:
		return 1;
	case FILTER_ID_X86:
	case FILTER_ID_POWERPC:
	case FILTER_ID_IA64:
	case FILTER_ID_ARM:
	case FILTER_ID_ARMTHUMB:
	case FILTER_ID_SPARC:
	case FILTER_ID_ARM64:
	case FILTER_ID_RISCV:
		return 4;
	default:
		return 0;
	}
}

void
filter_write_props(const filter_opt *fo, uint8_t *props)
{
	switch (fo->id) {
	case FILTER_ID_DELTA:
		props[0] = (uint8_t)(fo->dist - 1);
		break;
	default:
		props[0] = (uint8_t)(fo->start);
		props[1] = (uint8_t)(fo->start >> 8);
		props[2] = (uint8_t)(fo->start >> 16);
		props[3] = (uint8_t)(fo->start >> 24);
		break;
	}
}

int
filter_parse_props(uint32_t id, const uint8_t *props, uint32_t size,
		filter_opt *fo)
{
	fo->id = id;
	fo->type = id == FILTER_ID_DELTA ? FILTER_DELTA : FILTER_BCJ;
	fo->start = 0;
	fo->dist = 1;
	if (id == FILTER_ID_DELTA) {
		if (size != 1)
			return -1;
		fo->dist = (uint32_t)props[0] + 1;
		return 0;
	}
	switch (id) {
	case FILTER_ID_X86:
	case FILTER_ID_POWERPC:
	case FILTER_ID_IA64:
	case FILTER_ID_ARM:
	case FILTER_ID_ARMTHUMB:
	case FILTER_ID_SPARC:
	case FILTER_ID_ARM64:
	case FILTER_ID_RISCV:
		break;
	default:
		return -1;
	}
	if (size != 4)
		return -1;
	fo->start = (uint32_t)props[0] | ((uint32_t)props[1] << 8)
			| ((uint32_t)props[2] << 16) | ((uint32_t)props[3] << 24);
	return 0;
}

/* ---------------- Delta ---------------- */

static size_t
delta_coder(uint8_t *buf, size_t size, uint32_t dist, int is_encoder,
		uint32_t *hist_pos, uint8_t *hist)
{
	if (dist == 0)
		dist = 1;
	if (is_encoder) {
		for (size_t i = 0; i < size; ++i) {
			const uint32_t pos = *hist_pos;
			const uint8_t b = (uint8_t)(buf[i] - hist[pos]);
			hist[pos] = buf[i];
			buf[i] = b;
			*hist_pos = (pos + 1) % dist;
		}
	} else {
		for (size_t i = 0; i < size; ++i) {
			const uint32_t pos = *hist_pos;
			const uint8_t b = (uint8_t)(buf[i] + hist[pos]);
			hist[pos] = b;
			buf[i] = b;
			*hist_pos = (pos + 1) % dist;
		}
	}
	return size;
}

/* ---------------- BCJ helpers ---------------- */

#define TestMSByte(b) ((uint8_t)(b) == 0 || (uint8_t)(b) == 0xFF)

/* x86 BCJ filter */
static size_t
x86_code(uint8_t *buffer, size_t size, uint32_t now_pos, int is_encoder,
		uint32_t *prev_mask_p, uint32_t *prev_pos_p)
{
	static const uint32_t MASK_TO_BIT_NUM[8] = { 1, 2, 3, 4, 5, 6, 7, 8 };

	uint32_t prev_mask = *prev_mask_p;
	uint32_t prev_pos = *prev_pos_p;

	if (size < 5)
		return 0;

	if (now_pos - prev_pos > 5)
		prev_mask = 0;

	const size_t limit = size - 4;
	size_t buffer_pos = 0;

	while (buffer_pos <= limit) {
		uint32_t byte = buffer[buffer_pos];
		if (byte != 0xE8) {
			prev_mask >>= 1;
			++buffer_pos;
			continue;
		}

		const uint32_t offset = now_pos + (uint32_t)buffer_pos - prev_pos;
		prev_pos = now_pos + (uint32_t)buffer_pos;

		if (offset > 5) {
			prev_mask = 0;
		} else {
			for (uint32_t i = 0; i < offset; ++i) {
				prev_mask >>= 1;
				if (buffer[buffer_pos - offset + i] != 0xE8)
					prev_mask |= 0x100;
			}
		}

		byte = buffer[buffer_pos + 4];
		const uint32_t current = ((uint32_t)buffer[buffer_pos + 1] << 16)
				| ((uint32_t)buffer[buffer_pos + 2] << 8) | byte;

		const uint32_t low_bit = prev_mask & 0x80;
		uint32_t test = low_bit + 1;

		if (TestMSByte(byte) && (test & 0x100) == 0) {
			test = ((byte & 0x3F) == 0) ? 0xFFFFFFFFU : 0;
			if (test || (low_bit == 0
					&& (current & 0x80000000U) == 0)) {
				uint32_t dest = current;
				dest |= (uint32_t)buffer[buffer_pos + 4] << 24;
				dest = is_encoder ? dest - (now_pos
					+ (uint32_t)buffer_pos + 5)
					: dest + (now_pos
					+ (uint32_t)buffer_pos + 5);
				buffer[buffer_pos + 1] = (uint8_t)(dest >> 16);
				buffer[buffer_pos + 2] = (uint8_t)(dest >> 8);
				buffer[buffer_pos + 3] = (uint8_t)dest;
				buffer[buffer_pos + 4] = 0;
				prev_mask = 0;
				buffer_pos += 5;
				continue;
			}
		}
		prev_mask = ((prev_mask << 1) | (TestMSByte(byte) ? 0 : 1)) & 0xFF;
		++buffer_pos;
	}

	*prev_mask_p = prev_mask;
	*prev_pos_p = prev_pos;
	return 0;
	(void)MASK_TO_BIT_NUM;
}

/* Generic simple branch converter for ARM/ARMThumb/PowerPC/SPARC */
static size_t
bcj_generic(uint8_t *buffer, size_t size, uint32_t now_pos, int is_encoder,
		uint32_t mask, uint32_t shift, uint32_t bits, uint32_t start)
{
	size_t i = 0;
	/* aligned processing */
	while (i + 4 <= size) {
		uint32_t v = ((uint32_t)buffer[i] << 24)
			| ((uint32_t)buffer[i + 1] << 16)
			| ((uint32_t)buffer[i + 2] << 8)
			| (uint32_t)buffer[i + 3];
		if ((v & mask) == 0) {
			uint32_t t = (v >> shift) & bits;
			if (is_encoder)
				t += now_pos + (uint32_t)i + 4;
			else
				t -= now_pos + (uint32_t)i + 4;
			v = (v & ~(bits << shift)) | ((t & bits) << shift);
			buffer[i] = (uint8_t)(v >> 24);
			buffer[i + 1] = (uint8_t)(v >> 16);
			buffer[i + 2] = (uint8_t)(v >> 8);
			buffer[i + 3] = (uint8_t)v;
		}
		i += 4;
	}
	return i;
	(void)start;
}

size_t
filter_coder(const filter_opt *fo, uint8_t *buf, size_t size,
		uint64_t now_pos, int is_encoder, int skip)
{
	static uint8_t delta_hist[256];
	static uint32_t delta_pos;
	static uint32_t x86_prev_mask, x86_prev_pos;

	if (skip)
		return size;

	switch (fo->id) {
	case FILTER_ID_DELTA:
		return delta_coder(buf, size, fo->dist, is_encoder,
				&delta_pos, delta_hist);
	case FILTER_ID_X86:
		return x86_code(buf, size, (uint32_t)now_pos + fo->start,
				is_encoder, &x86_prev_mask, &x86_prev_pos);
	default:
		break;
	}
	return size;
}
