				| ((uint32_t)buffer[buffer_pos + 2] << 8) | byte;

		const uint32_t low_bit = prev_mask & 0x80;
		uint32_t test = low_bit + 1;

		if (TestMSByte(byte) && (test & 0x100) == 0) {
