static size_t
bcj_generic(uint8_t *buffer, size_t size, uint32_t now_pos, int is_encoder,
		uint32_t mask, uint32_t shift, uint32_t bits, uint32_t start)
{
	size_t i = 0;
	/* aligned processing */
	while (i + 4 <= size) {
		uint32_t v = ((uint32_t)buffer[i] << 24)
			| ((uint32_t)buffer[i + 1] << 16)
			| ((uint32_t)buffer[i + 2] << 8)
			| (uint32_t)buffer[i + 3];
		if ((v & mask) == 0) {
			uint32_t t = (v >> shift) & bits;
			if (is_encoder)
				t += now_pos + (uint32_t)i + 4;
			else
				t -= now_pos + (uint32_t)i + 4;
			v = (v & ~(bits << shift)) | ((t & bits) << shift);
			buffer[i] = (uint8_t)(v >> 24);
			buffer[i + 1] = (uint8_t)(v >> 16);
			buffer[i + 2] = (uint8_t)(v >> 8);
			buffer[i + 3] = (uint8_t)v;
		}
		i += 4;
	}
	return i;
	(void)start;
}

