# --- patch lzma.h: replace in_src with reader ---
h=open('src/lzma.h').read()
h=h.replace('''/* Input source for the range decoder */
typedef struct in_src {
	uint8_t buf[65536];
	size_t pos, len;
	int eof;
	uint64_t consumed;
	void *ctx;
	size_t (*read)(void *ctx, uint8_t *dst, size_t n);
} in_src;

void src_init(in_src *s, void *ctx, size_t (*read)(void *, uint8_t *, size_t));
int src_get(in_src *s);''','''/* Buffered input reader abstraction */
typedef struct reader {
	uint8_t buf[65536];
	size_t pos, len;
	uint64_t consumed;
	int eof;
	int (*fill)(struct reader *r);
	void *ctx;
} reader;

int rd_get(reader *r);
void rd_init(reader *r, int (*fill)(reader *), void *ctx);
size_t rd_read(reader *r, uint8_t *dst, size_t n);''')
h=h.replace('''	/* range decoder */
	in_src src;''','''	/* range decoder */
	reader src;''')
open('src/lzma.h','w').write(h)

# --- patch lzma_dec.c ---
s=open('src/lzma_dec.c').read()
s=s.replace('''/* ---------------- input source ---------------- */

void
src_init(in_src *s, void *ctx, size_t (*read)(void *, uint8_t *, size_t))
{
	s->pos = s->len = 0;
	s->eof = 0;
	s->consumed = 0;
	s->ctx = ctx;
	s->read = read;
}

int
src_get(in_src *s)
{
	if (s->pos == s->len) {
		if (s->eof)
			return -1;
		const size_t n = s->read(s->ctx, s->buf, sizeof(s->buf));
		s->pos = 0;
		s->len = n;
		if (n == 0) {
			s->eof = 1;
			return -1;
		}
	}
	++s->consumed;
	return s->buf[s->pos++];
}''','''/* ---------------- input reader ---------------- */

int
rd_get(reader *r)
{
	if (r->pos == r->len) {
		if (r->eof)
			return -1;
		if (!r->fill(r)) {
			r->eof = 1;
			return -1;
		}
		if (r->pos == r->len) {
			r->eof = 1;
			return -1;
		}
	}
	++r->consumed;
	return r->buf[r->pos++];
}

size_t
rd_read(reader *r, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		const int b = rd_get(r);
		if (b < 0)
			break;
		dst[done++] = (uint8_t)b;
	}
	return done;
}''')
s=s.replace('src_get(&s->d.src)','rd_get(&d->src)')
s=s.replace('src_get(&s->d.src)','rd_get(&s->d.src)')
# fix the limit_src wrapper
s=s.replace('''/* A source that reads at most `limit` bytes from the underlying reader */
typedef struct {
	in_src *parent;
	size_t left;
} limit_src;

static size_t
limit_read(void *ctx, uint8_t *dst, size_t n)
{
	limit_src *l = ctx;
	if (l->left == 0)
		return 0;
	if (n > l->left)
		n = l->left;
	const size_t got = l->parent->read(l->parent->ctx, dst, n);
	l->left -= got;
	return got;
}''','''/* A reader that yields at most `left` bytes from the parent reader */
typedef struct {
	reader *parent;
	size_t left;
} limit_ctx;

static int
limit_fill(reader *r)
{
	limit_ctx *l = r->ctx;
	reader *p = l->parent;
	size_t n = 0;
	while (l->left > 0 && p->pos < p->len && r->pos + n < sizeof(r->buf)) {
		size_t k = p->len - p->pos;
		if (k > l->left)
			k = l->left;
		if (k > sizeof(r->buf) - r->pos - n)
			k = sizeof(r->buf) - r->pos - n;
		memcpy(r->buf + r->pos + n, p->buf + p->pos, k);
		p->pos += k;
		l->left -= k;
		n += k;
	}
	r->len = r->pos + n;
	return n > 0;
}''')
s=s.replace('''		limit_src lim;
		lim.parent = &s->d.src;
		lim.left = packed;
		in_src saved = s->d.src;
		src_init(&s->d.src, &lim, limit_read);''','''		limit_ctx lim;
		lim.parent = &s->d.src;
		lim.left = packed;
		reader saved = s->d.src;
		rd_init(&s->d.src, limit_fill, &lim);''')
open('src/lzma_dec.c','w').write(s)
PY
grep -n "rd_init" src/lzma.h; gcc -c -O2 -Wall -o /tmp/l.o src/lzma_dec.c 2>&1|head -5"}

