	uint8_t buf[65536];
	size_t pos, len;
	uint64_t consumed;
	int eof;
	int (*fill)(struct reader *r);
	void *ctx;
} reader;

int rd_get(reader *r);
```

And the lzma_dec uses `reader src;`.

Let me rewrite.

