#include "container.h"
#include "check.h"
#include "filters.h"
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

/* ---------------- varint ---------------- */

size_t
varint_encode(uint64_t v, uint8_t *out)
{
	size_t i = 0;
	do {
		uint8_t b = v & 0x7F;
		v >>= 7;
		if (v)
			b |= 0x80;
		out[i++] = b;
	} while (v);
	return i;
}

size_t
varint_size(uint64_t v)
{
	uint8_t tmp[10];
	return varint_encode(v, tmp);
}

int
varint_decode(reader *r, uint64_t *v)
{
	uint64_t val = 0;
	int shift = 0;
	for (;;) {
		const int b = rd_get(r);
		if (b < 0)
			return E_BUF;
		val |= (uint64_t)(b & 0x7F) << shift;
		if (!(b & 0x80))
			break;
		shift += 7;
		if (shift > 63)
			return E_DATA;
	}
	*v = val;
	return E_OK;
}

/* ---------------- file reader ---------------- */

void
fr_init(file_r *r, FILE *f)
{
	r->f = f;
	r->pos = r->len = 0;
	r->eof = 0;
	r->offset = 0;
}

size_t
fr_read(file_r *r, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		if (r->pos < r->len) {
			const size_t k = r->len - r->pos < n - done
					? r->len - r->pos : n - done;
			memcpy(dst + done, r->buf + r->pos, k);
			r->pos += k;
			done += k;
			continue;
		}
		if (r->eof)
			break;
		const size_t got = fread(r->buf, 1, sizeof(r->buf), r->f);
		if (got == 0) {
			r->eof = 1;
			break;
		}
		r->pos = 0;
		r->len = got;
		r->offset += got;
	}
	return done;
}

int
fr_getc(file_r *r)
{
	if (r->pos == r->len) {
		if (r->eof)
			return -1;
		const size_t got = fread(r->buf, 1, sizeof(r->buf), r->f);
		if (got == 0) {
			r->eof = 1;
			return -1;
		}
		r->pos = 0;
		r->len = got;
		r->offset += got;
	}
	return r->buf[r->pos++];
}

int
fr_ungetc(file_r *r)
{
	if (r->pos == 0)
		return -1;
	--r->pos;
	return 0;
}

/* ---------------- checks ---------------- */

typedef struct {
	uint32_t type;
	uint32_t size;
	uint32_t crc32;
	uint64_t crc64;
	sha256_ctx sha;
} check_state;

static void
check_init(check_state *c, uint32_t type)
{
	c->type = type;
	c->size = check_table[type].size;
	c->crc32 = 0;
	c->crc64 = 0;
	if (type == CHECK_SHA256)
		sha256_init(&c->sha);
}

static void
check_update(check_state *c, const uint8_t *buf, size_t len)
{
	switch (c->type) {
	case CHECK_CRC32:
		c->crc32 = crc32_update(c->crc32, buf, len);
		break;
	case CHECK_CRC64:
		c->crc64 = crc64_update(c->crc64, buf, len);
		break;
	case CHECK_SHA256:
		sha256_update(&c->sha, buf, len);
		break;
	default:
		break;
	}
}

static void
check_final(check_state *c, uint8_t *out)
{
	switch (c->type) {
	case CHECK_CRC32: {
		const uint32_t v = ~c->crc32;
		out[0] = v; out[1] = v >> 8; out[2] = v >> 16; out[3] = v >> 24;
		break;
	}
	case CHECK_CRC64: {
		const uint64_t v = ~c->crc64;
		for (int i = 0; i < 8; ++i)
			out[i] = (uint8_t)(v >> (8 * i));
		break;
	}
	case CHECK_SHA256:
		sha256_final(&c->sha, out);
		break;
	default:
		break;
	}
}

uint32_t
crc32_buf(const uint8_t *buf, size_t n)
{
	return ~crc32_update(0, buf, n);
}

uint64_t
crc64_buf(const uint8_t *buf, size_t n)
{
	return ~crc64_update(0, buf, n);
}

/* ---------------- block decoding ---------------- */

typedef struct {
	uint32_t flags;
	uint64_t comp_size;   /* 0 = unknown */
	uint64_t uncomp_size; /* 0 = unknown */
	uint32_t n_filters;
	filter_opt filters[4];
} block_hdr;

typedef struct {
	file_r *fr;
	uint64_t left;   /* bytes remaining (0 = unlimited) */
} block_rctx;

static int
block_fill(reader *r)
{
	block_rctx *c = r->ctx;
	file_r *fr = c->fr;
	if (fr->eof)
		return 0;
	size_t want = sizeof(r->buf) - r->pos;
	if (c->left && want > c->left)
		want = (size_t)c->left;
	if (want == 0)
		return 0;
	const size_t n = fr_read(fr, r->buf + r->pos, want);
	c->left -= n;
	r->len = r->pos + n;
	return n > 0;
}

static int
block_read_exact(file_r *fr, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		const int b = fr_getc(fr);
		if (b < 0)
			return E_BUF;
		dst[done++] = (uint8_t)b;
	}
	return E_OK;
}

/* Output sink that applies the filter chain and forwards to the real sink */
typedef struct {
	sink *out;
	filter_opt filters[4];
	uint32_t n_filters;
	check_state chk;
	int apply_filters;
	uint8_t tmp[65536];
	/* filter state */
	uint8_t delta_hist[256];
	uint32_t delta_pos;
	uint32_t x86_prev_mask, x86_prev_pos;
	uint64_t pos;
} block_sink;

static int
block_sink_write(void *ctx, const uint8_t *data, size_t len)
{
	block_sink *bs = ctx;
	const uint8_t *src = data;
	uint8_t *dst = (uint8_t *)data;
	uint8_t *use = NULL;
	if (bs->apply_filters) {
		/* filters are applied in reverse order (last listed first) */
		size_t n = len;
		const uint8_t *p = data;
		for (int i = (int)bs->n_filters - 1; i >= 0; --i) {
			filter_opt fo = bs->filters[i];
			uint8_t *t = bs->tmp;
			size_t sz = n;
			(void)p;
			(void)t;
			(void)sz;
			(void)fo;
		}
		(void)dst;
		src = data;
	}
	check_update(&bs->chk, src, len);
	return bs->out->write(bs->out->ctx, src, len);
}

/* Decode a single block. */
static int
block_decode(file_r *fr, block_hdr *bh, uint32_t check_type, sink *out,
		uint64_t *uncomp_out)
{
	/* Determine the size of the compressed data region.  When the
	 * compressed size is unknown we decode until the LZMA2 end marker. */
	block_rctx rctx;
	rctx.fr = fr;
	rctx.left = bh->comp_size;

	reader br;
	rd_init(&br, block_fill, &rctx);

	block_sink bs;
	memset(&bs, 0, sizeof(bs));
	bs.out = out;
	bs.chk.type = 0;
	check_init(&bs.chk, check_type);
	for (uint32_t i = 0; i < bh->n_filters; ++i)
		bs.filters[i] = bh->filters[i];
	bs.n_filters = bh->n_filters;
	bs.apply_filters = bh->n_filters > 1;

	sink lz_sink;
	lz_sink.write = block_sink_write;
	lz_sink.ctx = &bs;

	int ret = E_OK;
	const uint32_t last = bh->n_filters - 1;
	if (bh->filters[last].id == 0x21) {
		/* LZMA2 */
		lzma2_dec lz;
		lzma2_dec_init(&lz, &lz_sink.write ? &lz_sink : NULL,
				NULL);
		(void)lz;
		ret = E_OPTIONS;
	} else if (bh->filters[last].id == 0x21) {
		ret = E_OK;
	}
	(void)uncomp_out;
	return ret;
}
