block_flush(block_out *bo)
{
	size_t len = bo->len;
	/* Apply the filters in reverse order (skip the last, which is the
	 * compression filter). */
	for (uint32_t i = bo->n_filters - 1; i > 0; --i) {
		filter_opt fo = bo->filters[i - 1];
		fo.start += (uint32_t)bo->block_pos;
		size_t used;
		if (fo.id == FILTER_ID_DELTA) {
			if (!bo->nofilter)
