static int
block_fill(reader *r)
{
	block_rctx *c = r->ctx;
	file_r *fr = c->fr;
	if (fr->eof)
		return 0;
	size_t want = sizeof(r->buf) - r->pos;
	if (c->left && want > c->left)
		want = (size_t)c->left;
	if (want == 0)
		return 0;
	const size_t n = fr_read(fr, r->buf + r->pos, want);
	c->left -= n;
	r->len = r->pos + n;
	return n > 0;
