		if (sink_write(bo->out, bo->buf, len))
			return E_MEM;
		bo->block_pos += len;
		bo->uncomp += len;
	}
	/* move the unprocessed tail to the front */
	const size_t tail = bo->len - len;
	if (tail > 0)
		memmove(bo->buf, bo->buf + len, tail);
	bo->len = tail;
	bo->pend = 0;
	return E_OK;
