	/* still too large: write in pieces */
	while (len > sizeof(bo->buf) - bo->len) {
		const size_t k = sizeof(bo->buf) - bo->len;
		memcpy(bo->buf + bo->len, data, k);
		bo->len += k;
		data += k;
		len -= k;
		if (block_flush(bo))
