	uint32_t flags;
	uint64_t comp_size;
	uint64_t uncomp_size;
	uint32_t n_filters;
	filter_opt filters[4];
} block_hdr;

typedef struct {
	file_r *fr;
	uint64_t left;
} block_rctx;

static int
block_fill(reader *r)
{
	block_rctx *c = r->ctx;
	file_r *fr = c->fr;
	if (fr->eof)
		return 0;
	size_t want = sizeof(r->buf) - r->pos;
	if (c->left && want > c->left)
		want = (size_t)c->left;
	if (want == 0)
		return 0;
	const size_t n = fr_read(fr, r->buf + r->pos, want);
	c->left -= n;
	r->len = r->pos + n;
	return n > 0;
}

int
block_read_exact(file_r *fr, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		const int b = fr_getc(fr);
		if (b < 0)
			return E_BUF;
		dst[done++] = (uint8_t)b;
	}
	return E_OK;
}

/* LZMA2 dictionary size from the property byte */
uint32_t
lzma2_dict_size(uint8_t props)
{
	if (props > 40)
		return 0;
	uint32_t size = 0;
	if (props == 40)
		size = 0xFFFFFFFFU;
	else
		size = (2 | (props & 1)) << (props / 2 + 11);
	return size;
}

/* ---------------- block output with filters ---------------- */

typedef struct {
	sink *out;
	filter_opt filters[4];
	uint32_t n_filters;
	check_state chk;
	uint8_t buf[65536 + 64];
	size_t pend;
	size_t len;
	uint64_t uncomp;
	uint64_t block_pos;
	uint8_t delta_hist[256];
	uint32_t delta_pos;
	uint32_t x86_prev_mask, x86_prev_pos;
	int nofilter;
} block_out;

static int
block_flush(block_out *bo)
{
	size_t len = bo->len;
	for (uint32_t i = bo->n_filters - 1; i > 0; --i) {
		filter_opt fo = bo->filters[i - 1];
		fo.start += (uint32_t)bo->block_pos;
		size_t used;
		if (fo.id == FILTER_ID_DELTA) {
			if (!bo->nofilter)
				delta_coder(bo->buf, len, fo.dist, 0,
					&bo->delta_pos, bo->delta_hist);
			used = len;
		} else {
			used = bcj_coder(&fo, bo->buf, len, bo->block_pos, 0,
				&bo->x86_prev_mask, &bo->x86_prev_pos,
				bo->nofilter);
		}
		len = used;
		if (len == 0)
			break;
	}
	if (len > bo->pend) {
		const size_t n = len - bo->pend;
		check_upd(&bo->chk, bo->buf, n);
		if (sink_write(bo->out, bo->buf, n))
			return E_MEM;
		bo->block_pos += n;
		bo->uncomp += n;
	}
	const size_t tail = bo->len - len;
	if (tail > 0)
		memmove(bo->buf, bo->buf + len, tail);
	bo->len = tail;
	bo->pend = 0;
	return E_OK;
}

static int
block_put(void *ctx, const uint8_t *data, size_t len)
{
	block_out *bo = ctx;
	while (len > 0) {
		const size_t k = sizeof(bo->buf) - bo->len < len
				? sizeof(bo->buf) - bo->len : len;
		memcpy(bo->buf + bo->len, data, k);
		bo->len += k;
		data += k;
		len -= k;
		if (bo->len >= sizeof(bo->buf) - 64) {
			if (block_flush(bo))
				return E_MEM;
		}
	}
	return E_OK;
}

/* ---------------- block decoding ---------------- */

static int
block_decode(file_r *fr, block_hdr *bh, uint32_t check_type, sink *out,
		uint64_t *uncomp_out, int nofilter)
{
	block_rctx rctx;
	rctx.fr = fr;
	rctx.left = bh->comp_size;

	reader br;
	rd_init(&br, block_fill, &rctx);

	block_out bo;
	memset(&bo, 0, sizeof(bo));
	bo.out = out;
	bo.nofilter = nofilter;
	for (uint32_t i = 0; i < bh->n_filters; ++i)
		bo.filters[i] = bh->filters[i];
	bo.n_filters = bh->n_filters;
	check_init_state(&bo.chk, check_type);

	sink lz_sink;
	lz_sink.write = block_put;
	lz_sink.ctx = &bo;

	const uint32_t nf = bh->n_filters;
	if (nf == 0 || bh->filters[nf - 1].id != 0x21)
		return E_OPTIONS;

	const uint32_t dict_size = lzma2_dict_size(bh->filters[nf - 1].props[0]);
	if (dict_size == 0)
		return E_OPTIONS;

	lzma2_dec lz;
	lzma2_dec_init(&lz, &bo, block_put);
	if (lzma_dec_alloc_dict(&lz.d, dict_size))
		return E_MEM;
	lz.d.src = br;

	int ret = lzma2_dec_run(&lz);
	if (ret == E_OK)
		ret = E_DATA;
	lzma_dec_free_dict(&lz.d);
	if (ret != E_STREAM_END)
		return ret;

	if (block_flush(&bo))
		return E_MEM;

	/* Block padding + check */
	uint8_t pad[4];
	const uint32_t npad = (uint32_t)((4 - (bo.uncomp % 4)) % 4);
	(void)npad;
	return E_OK;
}
