		if (fo.id == FILTER_ID_DELTA) {
			if (!bo->nofilter)
				delta_coder(bo->buf, len, fo.dist, 0,
					&bo->delta_pos, bo->delta_hist);
			used = len;
		} else {
			used = bcj_coder(&fo, bo->buf, len, bo->block_pos, 0,
				&bo->x86_prev_mask, &bo->x86_prev_pos,
				bo->nofilter);
		}
		len = used;
		if (len == 0)
			break;
	}
	if (len > bo->pend) {
		const size_t n = len - bo->pend;
		check_upd(&bo->chk, bo->buf, n);
		if (sink_write(bo->out, bo->buf, n))
			return E_MEM;
		bo->block_pos += n;
		bo->uncomp += n;
	}
	const size_t tail = bo->len - len;
	if (tail > 0)
		memmove(bo->buf, bo->buf + len, tail);
	bo->len = tail;
	bo->pend = 0;
	return E_OK;
}

static int
block_put(void *ctx, const uint8_t *data, size_t len)
{
	block_out *bo = ctx;
	while (len > 0) {
		const size_t k = sizeof(bo->buf) - bo->len < len
				? sizeof(bo->buf) - bo->len : len;
		memcpy(bo->buf + bo->len, data, k);
		bo->len += k;
		data += k;
		len -= k;
		if (bo->len >= sizeof(bo->buf) - 64) {
			if (block_flush(bo))
				return E_MEM;
		}
	}
	return E_OK;
}

/* ---------------- block decoding ---------------- */

static int
block_decode(file_r *fr, block_hdr *bh, uint32_t check_type, sink *out,
		uint64_t *uncomp_out, int nofilter)
{
	block_rctx rctx;
	rctx.fr = fr;
	rctx.left = bh->comp_size;

	reader br;
	rd_init(&br, block_fill, &rctx);

	block_out bo;
	memset(&bo, 0, sizeof(bo));
	bo.out = out;
	bo.nofilter = nofilter;
	for (uint32_t i = 0; i < bh->n_filters; ++i)
		bo.filters[i] = bh->filters[i];
	bo.n_filters = bh->n_filters;
	check_init_state(&bo.chk, check_type);

	sink lz_sink;
	lz_sink.write = block_put;
	lz_sink.ctx = &bo;

	const uint32_t nf = bh->n_filters;
	if (nf == 0 || bh->filters[nf - 1].id != 0x21)
		return E_OPTIONS;

	const uint32_t dict_size = lzma2_dict_size(bh->filters[nf - 1].props[0]);
	if (dict_size == 0)
		return E_OPTIONS;

	lzma2_dec lz;
	lzma2_dec_init(&lz, &bo, block_put);
	if (lzma_dec_alloc_dict(&lz.d, dict_size))
		return E_MEM;
	lz.d.src = br;

	int ret = lzma2_dec_run(&lz);
	if (ret == E_OK)
		ret = E_DATA;
	lzma_dec_free_dict(&lz.d);
	if (ret != E_STREAM_END)
		return ret;

	if (block_flush(&bo))
		return E_MEM;

	/* Block padding + check */
	uint8_t pad[4];
	const uint32_t npad = (uint32_t)((4 - (bo.uncomp % 4)) % 4);
	(void)npad;
	return E_OK;
}
