#include "container.h"
#include "check.h"
#include "filters.h"
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

/* ---------------- varint ---------------- */

size_t
varint_encode(uint64_t v, uint8_t *out)
{
	size_t i = 0;
	do {
		uint8_t b = (uint8_t)(v & 0x7F);
		v >>= 7;
		if (v)
			b |= 0x80;
		out[i++] = b;
	} while (v);
	return i;
}

size_t
varint_size(uint64_t v)
{
	uint8_t tmp[10];
	return varint_encode(v, tmp);
}

/* ---------------- file reader ---------------- */

void
fr_init(file_r *r, FILE *f)
{
	r->f = f;
	r->pos = r->len = 0;
	r->eof = 0;
	r->offset = 0;
	r->pb_pos = sizeof(r->pb);
	r->pb_len = 0;
}

int
fr_push(file_r *r, const uint8_t *data, size_t n)
{
	if (r->pb_pos >= n) {
		r->pb_pos -= n;
		memcpy(r->pb + r->pb_pos, data, n);
		r->pb_len += n;
		return 0;
	}
	memmove(r->pb + sizeof(r->pb) - r->pb_len, r->pb + r->pb_pos, r->pb_len);
	r->pb_pos = sizeof(r->pb) - r->pb_len;
	if (r->pb_pos < n)
		return -1;
	r->pb_pos -= n;
	memcpy(r->pb + r->pb_pos, data, n);
	r->pb_len += n;
	return 0;
}

size_t
fr_read(file_r *r, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		if (r->pb_len > 0) {
			dst[done++] = r->pb[r->pb_pos++];
			--r->pb_len;
			continue;
		}
		if (r->pos < r->len) {
			size_t k = r->len - r->pos;
			if (k > n - done)
				k = n - done;
			memcpy(dst + done, r->buf + r->pos, k);
			r->pos += k;
			done += k;
			continue;
		}
		if (r->eof)
			break;
		const size_t got = fread(r->buf, 1, sizeof(r->buf), r->f);
		if (got == 0) {
			r->eof = 1;
			break;
		}
		r->pos = 0;
		r->len = got;
		r->offset += got;
	}
	return done;
}

int
fr_getc(file_r *r)
{
	if (r->pb_len > 0) {
		--r->pb_len;
		return r->pb[r->pb_pos++];
	}
	if (r->pos == r->len) {
		if (r->eof)
			return -1;
		const size_t got = fread(r->buf, 1, sizeof(r->buf), r->f);
		if (got == 0) {
			r->eof = 1;
			return -1;
		}
		r->pos = 0;
		r->len = got;
		r->offset += got;
	}
	return r->buf[r->pos++];
}

int
fr_ungetc(file_r *r)
{
	if (r->pos == 0)
		return -1;
	--r->pos;
	return 0;
}

int
fr_varint(file_r *r, uint64_t *v)
{
	uint64_t val = 0;
	int shift = 0;
	for (;;) {
		const int b = fr_getc(r);
		if (b < 0)
			return E_BUF;
		val |= (uint64_t)(b & 0x7F) << shift;
		if (!(b & 0x80))
			break;
		shift += 7;
		if (shift > 63)
			return E_DATA;
	}
	*v = val;
	return E_OK;
}

int
fr_read_exact(file_r *r, uint8_t *dst, size_t n)
{
	size_t done = 0;
	while (done < n) {
		const int b = fr_getc(r);
		if (b < 0)
			return E_BUF;
		dst[done++] = (uint8_t)b;
	}
	return E_OK;
}

uint32_t
crc32_buf(const uint8_t *buf, size_t n)
{
	return ~crc32_update(0, buf, n);
}

uint64_t
crc64_buf(const uint8_t *buf, size_t n)
{
	return ~crc64_update(0, buf, n);
}

/* ---------------- checks ---------------- */

void
check_init_state(check_state *c, uint32_t type)
{
	c->type = type;
	c->size = check_table[type].size;
	c->crc32 = 0;
	c->crc64 = 0;
	if (type == CHECK_SHA256)
		sha256_init(&c->sha);
}

void
check_upd(check_state *c, const uint8_t *buf, size_t len)
{
	switch (c->type) {
	case CHECK_CRC32:
		c->crc32 = crc32_update(c->crc32, buf, len);
		break;
	case CHECK_CRC64:
		c->crc64 = crc64_update(c->crc64, buf, len);
		break;
	case CHECK_SHA256:
		sha256_update(&c->sha, buf, len);
		break;
	default:
		break;
	}
}

void
check_fin(check_state *c, uint8_t *out)
{
	switch (c->type) {
	case CHECK_CRC32: {
		const uint32_t v = ~c->crc32;
		out[0] = (uint8_t)v; out[1] = (uint8_t)(v >> 8);
		out[2] = (uint8_t)(v >> 16); out[3] = (uint8_t)(v >> 24);
		break;
	}
	case CHECK_CRC64: {
		const uint64_t v = ~c->crc64;
		for (int i = 0; i < 8; ++i)
			out[i] = (uint8_t)(v >> (8 * i));
		break;
	}
	case CHECK_SHA256:
		sha256_final(&c->sha, out);
		break;
	default:
		break;
	}
}

/* ---------------- block header ---------------- */

typedef struct {
	uint32_t flags;
	uint64_t comp_size;
	uint64_t uncomp_size;
	uint32_t n_filters;
	filter_opt filters[4];
} block_hdr;

typedef struct {
	file_r *fr;
	uint64_t left;
} block_rctx;

static int
block_fill(reader *r)
{
	block_rctx *c = r->ctx;
	file_r *fr = c->fr;
	if (fr->eof)
		return 0;
	size_t want = sizeof(r->buf) - r->pos;
	if (want > 8192)
		want = 8192;
	if (c->left && want > c->left)
		want = (size_t)c->left;
	if (want == 0)
		return 0;
	const size_t n = fr_read(fr, r->buf + r->pos, want);
	c->left -= n;
	r->len = r->pos + n;
	return n > 0;
}

uint32_t
lzma2_dict_size(uint8_t props)
{
	if (props > 40)
		return 0;
	if (props == 40)
		return 0xFFFFFFFFU;
	return (2 | (props & 1)) << (props / 2 + 11);
}

/* ---------------- block output with filters ---------------- */

typedef struct {
	sink *out;
	filter_opt filters[4];
	uint32_t n_filters;
	check_state chk;
	uint8_t buf[65536 + 64];
	size_t len;
	uint64_t uncomp;
	uint64_t block_pos;
	uint8_t delta_hist[256];
	uint32_t delta_pos;
	uint32_t x86_prev_mask, x86_prev_pos;
	int nofilter;
} block_out;

int
block_flush(block_out *bo)
{
	size_t len = bo->len;
	for (uint32_t i = bo->n_filters - 1; i > 0; --i) {
		filter_opt fo = bo->filters[i - 1];
		fo.start += (uint32_t)bo->block_pos;
		size_t used;
		if (fo.id == FILTER_ID_DELTA) {
			if (!bo->nofilter)
				delta_coder(bo->buf, len, fo.dist, 0,
					&bo->delta_pos, bo->delta_hist);
			used = len;
		} else {
			used = bcj_coder(&fo, bo->buf, len, bo->block_pos, 0,
				&bo->x86_prev_mask, &bo->x86_prev_pos,
				bo->nofilter);
		}
		len = used;
		if (len == 0)
			break;
	}
	if (len > 0) {
		check_upd(&bo->chk, bo->buf, len);
		if (bo->out->write(bo->out->ctx, bo->buf, len))
			return E_MEM;
		bo->block_pos += len;
		bo->uncomp += len;
	}
	bo.len_unused_placeholder:
	;
	bo->len = 0;
	return E_OK;
}

static int
block_put(void *ctx, const uint8_t *data, size_t len)
{
	block_out *bo = ctx;
	while (len > 0) {
		const size_t k = sizeof(bo->buf) - bo->len < len
				? sizeof(bo->buf) - bo->len : len;
		memcpy(bo->buf + bo->len, data, k);
		bo->len += k;
		data += k;
		len -= k;
		if (bo->len >= sizeof(bo->buf) - 64) {
			if (block_flush(bo))
				return E_MEM;
		}
	}
	return E_OK;
}

/* ---------------- block decoding ---------------- */

static int
block_decode(file_r *fr, block_hdr *bh, uint32_t check_type, sink *out,
		uint64_t *uncomp_out, int nofilter)
{
	block_rctx rctx;
	rctx.fr = fr;
	rctx.left = bh->comp_size;

	reader br;
	rd_init(&br, block_fill, &rctx);

	block_out bo;
	memset(&bo, 0, sizeof(bo));
	bo.out = out;
	bo.nofilter = nofilter;
	for (uint32_t i = 0; i < bh->n_filters; ++i)
		bo.filters[i] = bh->filters[i];
	bo.n_filters = bh->n_filters;
	check_init_state(&bo.chk, check_type);

	sink lz_sink;
	lz_sink.write = block_put;
	lz_sink.ctx = &bo;

	const uint32_t nf = bh->n_filters;
	if (nf == 0 || bh->filters[nf - 1].id != 0x21)
		return E_OPTIONS;

	const uint32_t dict_size = lzma2_dict_size(bh->filters[nf - 1].props[0]);
	if (dict_size == 0)
		return E_OPTIONS;

	lzma2_dec lz;
	lzma2_dec_init(&lz, &bo, block_put);
	if (lzma_dec_alloc_dict(&lz.d, dict_size))
		return E_MEM;
	lz.d.src = br;

	int ret = lzma2_dec_run(&lz);
	if (ret == E_OK)
		ret = E_DATA;
	lzma_dec_free_dict(&lz.d);
	if (ret != E_STREAM_END)
		return ret;

	if (block_flush(&bo))
		return E_MEM;

	*uncomp_out = bo.uncomp;

	/* push back the buffered-but-unconsumed bytes */
	{
		const size_t left = br.len - br.pos;
		if (left > 0) {
			uint8_t tmp[8192];
			memcpy(tmp, br.buf + br.pos, left);
			if (fr_push(fr, tmp, left))
				return E_DATA;
		}
	}

	/* Block padding */
	const uint64_t comp = bh->comp_size ? bh->comp_size
			: (uint64_t)br.consumed;
	const uint32_t npad = (uint32_t)((4 - (comp % 4)) % 4);
	uint8_t pad[4];
	if (npad) {
		if (fr_read_exact(fr, pad, npad))
			return E_BUF;
		for (uint32_t i = 0; i < npad; ++i)
			if (pad[i] != 0)
				return E_DATA;
	}

	/* Check */
	uint8_t stored[64];
	if (check_table[check_type].size) {
		if (fr_read_exact(fr, stored, check_table[check_type].size))
			return E_BUF;
	}
	uint8_t computed[64];
	check_fin(&bo.chk, computed);
	if (check_table[check_type].size
			&& memcmp(computed, stored, check_table[check_type].size))
		return E_DATA;

	return E_OK;
}
