{"command": "cat >> src/container.c <<'EOF'

/* ---------------- xz stream decoding ---------------- */

typedef struct {
	uint32_t crc;
	uint64_t size;
} idx_acc;

static int
fr_varint_acc(file_r *fr, uint64_t *v, uint8_t *byte, uint32_t *crc,
		uint64_t *size)
{
	uint64_t val = 0;
	int shift = 0;
	for (;;) {
		const int b = fr_getc(fr);
		if (b < 0)
			return E_BUF;
		*byte = (uint8_t)b;
		*crc = crc32_update(*crc, byte, 1);
		++*size;
		val |= (uint64_t)(b & 0x7F) << shift;
		if (!(b & 0x80))
			break;
		shift += 7;
		if (shift > 63)
			return E_DATA;
	}
	*v = val;
	return E_OK;
}

static int
fr_byte_acc(file_r *fr, uint8_t *byte, uint32_t *crc, uint64_t *size)
{
	const int b = fr_getc(fr);
	if (b < 0)
		return E_BUF;
	*byte = (uint8_t)b;
	*crc = crc32_update(*crc, byte, 1);
	++*size;
	return E_OK;
}

int
xz_stream_decode(file_r *fr, sink *out, stream_info *info, int nofilter)
{
	uint8_t hdr[12];
	int ret = fr_read_exact(fr, hdr, 12);
	if (ret)
		return ret;
	if (memcmp(hdr, "\xfd7zXZ\x00", 6))
		return E_FORMAT;
	if (hdr[6] != 0)
		return E_DATA;
	const uint32_t check = hdr[7];
	if (check & 0xF0)
		return E_DATA;
	if (check > 15)
		return E_DATA;
	uint32_t stored_crc = (uint32_t)hdr[8] | ((uint32_t)hdr[9] << 8)
			| ((uint32_t)hdr[10] << 16) | ((uint32_t)hdr[11] << 24);
	if (crc32_buf(hdr + 6, 2) != stored_crc)
		return E_DATA;
	if (info)
		info->check = check;

	uint64_t n_blocks = 0, uncomp_total = 0;
	uint64_t rec_idx = 0;
	uint32_t idx_crc = crc32_buf((const uint8_t *)"\x00", 1);
	uint64_t idx_size = 1;
	int index_started = 0;
	uint64_t idx_nrec = 0;
	uint64_t block_unpadded = 0, block_uncomp = 0;

	for (;;) {
		uint8_t first;
		if (fr_read_exact(fr, &first, 1))
			return E_BUF;

		if (first == 0 && index_started) {
			/* index indicator already consumed */
		}

		if (first != 0) {
			/* Block */
			uint8_t hbuf[1024];
			hbuf[0] = first;
			const uint32_t hsize = ((uint32_t)first + 1) * 4;
			if (hsize > 1024)
				return E_DATA;
			if (hsize - 1 > 0 && fr_read_exact(fr, hbuf + 1, hsize - 1))
				return E_BUF;
			const uint32_t stored = (uint32_t)hbuf[hsize - 4]
				| ((uint32_t)hbuf[hsize - 3] << 8)
				| ((uint32_t)hbuf[hsize - 2] << 16)
				| ((uint32_t)hbuf[hsize - 1] << 24);
			if (crc32_buf(hbuf, hsize - 4) != stored)
				return E_DATA;
			const uint32_t flags = hbuf[1];
			if (flags & 0x3C)
				return E_DATA;
			const uint32_t nf = (flags & 3) + 1;
			size_t p = 2;
			uint64_t comp_size = 0, uncomp_size = 0;
			uint8_t varb[10];
			if (flags & 0x40) {
				size_t n = 0;
				while (hbuf[p] & 0x80) {
					varb[n++] = hbuf[p++];
					if (n > 9)
						return E_DATA;
				}
				varb[n++] = hbuf[p++];
				size_t sh = 0;
				for (size_t i = 0; i < n; ++i) {
					comp_size |= (uint64_t)(varb[i] & 0x7F) << sh;
					sh += 7;
				}
				if (comp_size == 0)
					return E_DATA;
			}
			if (flags & 0x80) {
				size_t n = 0;
				while (hbuf[p] & 0x80) {
					varb[n++] = hbuf[p++];
					if (n > 9)
						return E_DATA;
				}
				varb[n++] = hbuf[p++];
				size_t sh = 0;
				for (size_t i = 0; i < n; ++i) {
					uncomp_size |= (uint64_t)(varb[i] & 0x7F) << sh;
					sh += 7;
				}
			}
			if (nf > 4)
				return E_DATA;
			block_hdr bh;
			memset(&bh, 0, sizeof(bh));
			bh.flags = flags;
			bh.comp_size = comp_size;
			bh.uncomp_size = uncomp_size;
			bh.n_filters = nf;
			for (uint32_t i = 0; i < nf; ++i) {
				uint64_t fid, psz;
				if (p >= hsize - 4)
					return E_DATA;
				/* decode varints from the header buffer */
				size_t n = 0, sh = 0;
				fid = 0;
				while (1) {
					if (p >= hsize - 4)
						return E_DATA;
					const uint8_t c = hbuf[p++];
					fid |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
					if (sh > 63)
						return E_DATA;
				}
				n = 0; sh = 0; psz = 0;
				while (1) {
