					const uint8_t c = hbuf[p++];
					psz |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
					if (sh > 63)
						return E_DATA;
				}
				if (psz > sizeof(bh.filters[i].props)
						|| p + psz > hsize - 4)
					return E_DATA;
				filter_opt fo;
