{"command": "cd /tmp/t/al && python3 - <<'PY'
import sys; sys.path.insert(0,'/tmp/t')
import lzdec, subprocess
from lzdec import *
data=b'a'*100
open('d2.bin','wb').write(data)
subprocess.run(['/workspace/executable','-F','lzma','-k','-c','d2.bin'],stdout=open('d2.lzma','wb'))
d=open('d2.lzma','rb').read()
lc,lp,pb=3,0,2
rd=RD(d[13:])
probs=[1024]*(OFF_LITERAL+(0x300<<(lc+lp)))
pos_mask=(1<<pb)-1; lp_mask=(1<<lp)-1
state=0; reps=[0,0,0,0]
out=bytearray()
for i in range(10):
    pos=len(out); ps=pos&pos_mask; mi=(state<<4)+ps
    if rd.bit(probs,OFF_IS_MATCH+mi)==0:
        prev=out[pos-1] if pos>0 else 0
        lit_state=((pos&lp_mask)<<lc)+(prev>>(8-lc))
        base=OFF_LITERAL+lit_state*0x300
        sym=1
        if state>=7:
            mb=out[pos-1-reps[0]]
            for _ in range(8):
                b7=(mb>>7)&1; mb=(mb<<1)&0xFF
                sym=(sym<<1)|rd.bit(probs,base+0x100+(b7<<8)+sym)
        else:
            for _ in range(8):
                sym=(sym<<1)|rd.bit(probs,base+sym)
        state=[0,0,0,0,1,2,3,4,5,6,4,5][state]
        out.append(sym&0xFF); print(i,'lit',repr(chr(sym&0xFF)),'state',state)
    elif rd.bit(probs,OFF_IS_REP+state)==1:
        if rd.bit(probs,OFF_IS_REP0+mi)==0:
            if rd.bit(probs,OFF_IS_REP0_LONG+mi)==0:
                state=9 if state<7 else 11
                out.append(out[pos-1-reps[0]]); print(i,'shortrep0')
            else:
                if rd.bit(probs,OFF_IS_REP1+state)==0: dist=reps[1]
                else:
                    if rd.bit(probs,OFF_IS_REP2+state)==0: dist=reps[2]
                    else: dist=reps[3]; reps[3]=reps[2]
                    reps[2]=reps[1]
                reps[1]=reps[0]; reps[0]=dist
                state=8 if state<7 else 11
                ln=decode_len(rd,probs,ps)
                for _ in range(ln): out.append(out[len(out)-1-reps[0]])
                print(i,'rep0 long len=%d dist=%d'%(ln,dist))
        else:
            ln=decode_len(rd,probs,ps)
            state=7 if state<7 else 10
            slot=rd.tree(probs,OFF_POS_SLOT,6)
            dist=0
            if slot>=4:
                ndb=(slot>>1)-1
                dist=(2|(slot&1))<<ndb
                if slot<14: dist+=rd.tree_rev(probs,OFF_POS_SPECIAL+dist-slot,ndb)
                else:
                    dist+=rd.direct(ndb-4)<<4
                    dist+=rd.tree_rev(probs,OFF_POS_ALIGN,4)
            else: dist=slot
            if dist==0xFFFFFFFF:
                print(i,'EOPM'); break
            print(i,'rep-newdist len=%d dist=%d'%(ln,dist))
            reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
            for _ in range(ln): out.append(out[len(out)-1-dist])
    else:
        ln=decode_len(rd,probs,ps)
        state=7 if state<7 else 10
        slot=rd.tree(probs,OFF_POS_SLOT,6)
        dist=0
        if slot>=4:
            ndb=(slot>>1)-1
            dist=(2|(slot&1))<<ndb
            if slot<14: dist+=rd.tree_rev(probs,OFF_POS_SPECIAL+dist-slot,ndb)
            else:
                dist+=rd.direct(ndb-4)<<4
                dist+=rd.tree_rev(probs,OFF_POS_ALIGN,4)
        else: dist=slot
        if dist==0xFFFFFFFF:
            print(i,'EOPM'); break
        print(i,'match len=%d dist=%d slot=%d used=%d'%(ln,dist,slot,rd.p))
        reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
        for _ in range(ln): out.append(out[len(out)-1-dist])
print(bytes(out[:40]))
PY"}

