pos_mask=(1<<pb)-1; lp_mask=(1<<lp)-1
state=0; reps=[0,0,0,0]
out=bytearray()
for i in range(8):
    pos=len(out); ps=pos&pos_mask; mi=(state<<4)+ps
    if rd.bit(probs,OFF_IS_MATCH+mi)==0:
        prev=out[pos-1] if pos>0 else 0
        lit_state=((pos&lp_mask)<<lc)+(prev>>(8-lc))
        base=OFF_LITERAL+lit_state*0x300
        sym=1
        for _ in range(8):
            sym=(sym<<1)|rd.bit(probs,base+sym)
        state=[0,0,0,0,1,2,3,4,5,6,4,5][state]
        out.append(sym&0xFF); print(i,'lit',repr(chr(sym&0xFF)),'state',state)
    else:
        rep=rd.bit(probs,OFF_IS_REP+state)
        if rep==0:
            ln=decode_len(rd,probs,ps)
            state=7 if state<7 else 10
            slot=rd.tree(probs,OFF_POS_SLOT,6)
            dist=slot if slot<4 else 0
            if slot>=4:
                ndb=(slot>>1)-1
                dist=(2|(slot&1))<<ndb
                if slot<14: dist+=rd.tree_rev(probs,OFF_POS_SPECIAL+dist-slot,ndb)
                else:
                    dist+=rd.direct(ndb-4)<<4
                    dist+=rd.tree_rev(probs,OFF_POS_ALIGN,4)
            if dist==0xFFFFFFFF:
                print(i,'EOPM'); break
            print(i,'match len=%d dist=%d slot=%d used=%d'%(ln,dist,slot,rd.p))
            reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
            for _ in range(ln): out.append(out[len(out)-1-dist])
