cd /tmp/t/al && python3 - <<'PY'
import sys; sys.path.insert(0,'/tmp/t')
from lzdec import RD
import subprocess
d=open('h.lzma','rb').read()[13:]
lc,lp,pb=3,0,2
for variant in ['nobreak','break']:
    rd=RD(d)
    probs=[1024]*(17565+(0x300<<(lc+lp)))
    pos_mask=(1<<pb)-1; lp_mask=(1<<lp)-1
    state=0; reps=[0,0,0,0]
    out=bytearray()
    try:
        for i in range(14):
            pos=len(out); ps=pos&pos_mask; mi=(state<<4)+ps
            if rd.bit(probs,OFF_IS_MATCH+mi)==0:
                prev=out[pos-1] if pos>0 else 0
                lit_state=((pos&lp_mask)<<lc)+(prev>>(8-lc))
                base=17565+lit_state*0x300
                sym=1
                if state>=7:
                    mb=out[pos-1-reps[0]]
                    n=0
                    for _ in range(8):
                        mb_bit=(mb>>7)&1; mb=(mb<<1)&0xFF
                        b=rd.bit(probs,base+0x100+(mb_bit<<8)+sym)
                        sym=(sym<<1)|b
                        n+=1
                        if variant=='break' and mb_bit!=b: break
                    while sym<0x100:
                        b=rd.bit(probs,base+sym)
                        sym=(sym<<1)|b
                        n+=1
                else:
                    for _ in range(8): sym=(sym<<1)|rd.bit(probs,base+sym)
                state=[0,0,0,0,1,2,3,4,5,6,4,5][state]
                out.append(sym&0xFF)
                print(variant,i,'lit',repr(chr(sym&0xFF)),'state',state,'nbits',n)
            else:
                rep=rd.bit(probs,OFF_IS_REP+state)
                if rep==0:
                    # length
                    if rd.bit(probs,17051)==0:
                        sym=1
                        for _ in range(3): sym=(sym<<1)|rd.bit(probs,17052+ps*8+sym)
                        ln=(sym-256 if sym>=256 else sym)+2
                    elif rd.bit(probs,17180)==0:
                        sym=1
                        for _ in range(3): sym=(sym<<1)|rd.bit(probs,17181+ps*8+sym)
                        ln=(sym-256 if sym>=256 else sym)+10
                    else:
                        sym=1
                        for _ in range(8): sym=(sym<<1)|rd.bit(probs,17309+sym)
                        ln=(sym-256 if sym>=256 else sym)+18
                    state=7 if state<7 else 10
                    slot=rd.tree(probs,OFF_POS_SLOT,6)
                    dist=slot if slot<4 else 0
                    if slot>=4:
                        ndb=(slot>>1)-1
                        dist=(2|(slot&1))<<ndb
                        if slot<14: dist+=rd.tree_rev(probs,OFF_POS_SPECIAL+dist-slot,ndb)
                        else:
                            dist+=rd.direct(ndb-4)<<4
                            dist+=rd.tree_rev(probs,OFF_POS_ALIGN,4)
                    if dist==0xFFFFFFFF:
                        print(variant,i,'EOPM'); break
                    reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
                    for _ in range(ln): out.append(out[len(out)-1-dist])
                    print(variant,i,'match len=%d dist=%d'%(ln,dist))
                else:
                    r0=rd.bit(probs,OFF_IS_REP0+mi)
                    if r0==0:
                        if rd.bit(probs,OFF_IS_REP0_LONG+mi)==0:
                            state=9 if state<7 else 11
                            out.append(out[pos-1-reps[0]])
                            print(variant,i,'shortrep0')
                        else:
                            if rd.bit(probs,17151)==0:
                                sym=1
                                for _ in range(3): sym=(sym<<1)|rd.bit(probs,17052+ps*8+sym)
                                ln=(sym-256 if sym>=256 else sym)+2
                            else:
                                sym=1
                                for _ in range(3): sym=(sym<<1)|rd.bit(probs,17181+ps*8+sym)
                                ln=(sym-256 if sym>=256 else sym)+10
                            state=8 if state<7 else 11
                            for _ in range(ln): out.append(out[len(out)-1-reps[0]])
                            print(variant,i,'rep0len=%d'%ln)
                    else:
                        print(variant,i,'rep12/3'); break
    except Exception as e:
        print(variant,'EXC',e)
    print(variant,'result',bytes(out))
