		printf("  Compression:                      %s (%llu B)\n", a,
				(unsigned long long)memlimit_compress);
	} else {
		printf("  Compression:                      Disabled\n");
	}
	if (memlimit_decompress) {
		format_bytes(a, sizeof(a), memlimit_decompress);
		printf("  Decompression:                    %s (%llu B)\n", a,
				(unsigned long long)memlimit_decompress);
	} else {
		printf("  Decompression:                    Disabled\n");
	}
	if (memlimit_mt) {
		format_bytes(a, sizeof(a), memlimit_mt);
		printf("  Multi-threaded decompression:     %s (%llu B)\n", a,
				(unsigned long long)memlimit_mt);
	} else {
		printf("  Multi-threaded decompression:     Disabled\n");
	}
	if (default_mt_memlimit) {
		format_bytes(a, sizeof(a), default_mt_memlimit);
		printf("  Default for -T0:                  %s (%llu B)\n", a,
				(unsigned long long)default_mt_memlimit);
	} else {
		printf("  Default for -T0:                  Disabled\n");
	}
}

/* ------------------------------------------------------------------ */
/* output file handling                                                */
/* ------------------------------------------------------------------ */

typedef struct {
	int fd;
	int is_stdout;
	int sparse;
	int sparse_ok;
	uint64_t pos;
	char *name;
} out_file;

static int
out_write(void *ctx, const uint8_t *data, size_t len)
{
	out_file *of = ctx;
	size_t done = 0;
	while (done < len) {
		if (of->sparse && of->sparse_ok) {
			if (data[done] == 0) {
				size_t z = 1;
				while (z < len - done && data[done + z] == 0)
					++z;
				if (z >= 4096) {
					if (lseek(of->fd, (off_t)z, SEEK_CUR) < 0)
						return -1;
					of->pos += z;
					done += z;
					continue;
				}
			}
		}
		const size_t k = len - done;
		ssize_t n = write(of->fd, data + done, k);
		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		done += (size_t)n;
		of->pos += (size_t)n;
	}
	return 0;
}

static void
out_init(out_file *of, int fd, const char *name, int is_stdout, int sparse)
{
	of->fd = fd;
	of->is_stdout = is_stdout;
	of->sparse = sparse;
	of->sparse_ok = 0;
	of->pos = 0;
	of->name = name ? strdup(name) : NULL;
}

static void
out_close(out_file *of, const struct stat *src_st, int keep_src)
{
	if (of->fd < 0)
		return;
	if (!of->is_stdout) {
		/* copy the file mode */
		if (src_st)
			fchmod(of->fd, src_st->st_mode & 07777);
		if (src_st) {
			struct timespec ts[2];
			ts[0].tv_sec = src_st->st_atim.tv_sec;
			ts[0].tv_nsec = src_st->st_atim.tv_nsec;
			ts[1].tv_sec = src_st->st_mtim.tv_sec;
			ts[1].tv_nsec = src_st->st_mtim.tv_nsec;
			futimens(of->fd, ts);
		}
		fsync(of->fd);
	}
	close(of->fd);
	of->fd = -1;
}
