/* ------------------------------------------------------------------ */

static uint64_t total_ram;
static uint64_t memlimit_compress, memlimit_decompress, memlimit_mt;
static uint64_t default_mt_memlimit;

static uint64_t
get_total_ram(void)
{
	if (total_ram)
		return total_ram;
	long pages = sysconf(_SC_PHYS_PAGES);
	long psize = sysconf(_SC_PAGE_SIZE);
	if (pages > 0 && psize > 0)
		total_ram = (uint64_t)pages * (uint64_t)psize;
	return total_ram;
}

static int
parse_size(const char *s, uint64_t *out)
{
	/* xz: value is a non-negative decimal integer with optional KiB/MiB/GiB */
	if (!s || !*s)
		return -1;
	uint64_t v = 0;
	const char *p = s;
	while (*p >= '0' && *p <= '9') {
		v = v * 10 + (uint64_t)(*p - '0');
		++p;
	}
	if (p == s)
		return -1;
	if (*p) {
		if (!strcmp(p, "KiB")) v *= 1024ULL;
		else if (!strcmp(p, "MiB")) v *= 1024ULL * 1024;
		else if (!strcmp(p, "GiB")) v *= 1024ULL * 1024 * 1024;
		else if (!strcmp(p, "kB")) v *= 1000ULL;
		else if (!strcmp(p, "MB")) v *= 1000000ULL;
		else if (!strcmp(p, "GB")) v *= 1000000000ULL;
		else return -1;
	}
	*out = v;
	return 0;
}

/* ------------------------------------------------------------------ */

static void
print_help(int long_help)
{
	printf(long_help ? long_help : short_help, msg_progname());
}

static void
print_version(void)
{
	if (o.robot) {
		printf("XZ_VERSION=%llu\n", (unsigned long long)XZ_VERSION_NUM);
		printf("LIBLZMA_VERSION=%llu\n", (unsigned long long)LIBLZMA_VERSION_NUM);
	} else {
		printf("xz (XZ Utils) %s\nliblzma %s\n", XZ_VERSION, XZ_VERSION);
	}
}

static void
format_bytes(char *buf, size_t n, uint64_t v)
{
	/* 1521630 MiB (1595544154112 B) */
	if (v % (1024ULL * 1024 * 1024) == 0 && v >= 1024ULL * 1024 * 1024)
		snprintf(buf, n, "%llu GiB", (unsigned long long)(v / (1024ULL * 1024 * 1024)));
	else if (v % (1024ULL * 1024) == 0 && v >= 1024ULL * 1024)
		snprintf(buf, n, "%llu MiB", (unsigned long long)(v / (1024ULL * 1024)));
	else if (v % 1024ULL == 0 && v >= 1024ULL)
		snprintf(buf, n, "%llu KiB", (unsigned long long)(v / 1024ULL));
	else
		snprintf(buf, n, "%llu B", (unsigned long long)v);
}

