	out_file *of = ctx;
	size_t done = 0;
	while (done < len) {
		if (of->sparse && of->sparse_ok) {
			if (data[done] == 0) {
				size_t z = 1;
				while (z < len - done && data[done + z] == 0)
					++z;
				if (z >= 4096) {
					if (lseek(of->fd, (off_t)z, SEEK_CUR) < 0)
						return -1;
					of->pos += z;
					done += z;
					continue;
				}
			}
		}
		const size_t k = len - done;
		ssize_t n = write(of->fd, data + done, k);
		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		done += (size_t)n;
		of->pos += (size_t)n;
	}
