			ts[0].tv_nsec = src_st->st_atim.tv_nsec;
			ts[1].tv_sec = src_st->st_mtim.tv_sec;
			ts[1].tv_nsec = src_st->st_mtim.tv_nsec;
			futimens(of->fd, ts);
		}
		fsync(of->fd);
	}
	close(of->fd);
	of->fd = -1;
