/* Command line option parsing (xz compatible) */
#include "opts.h"
#include "msg.h"
#include "lzma.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <unistd.h>

options o;

static uint64_t total_ram_cache;

static uint64_t
total_ram(void)
{
	if (total_ram_cache)
		return total_ram_cache;
	long pages = sysconf(_SC_PHYS_PAGES);
	long psize = sysconf(_SC_PAGE_SIZE);
	if (pages > 0 && psize > 0)
		total_ram_cache = (uint64_t)pages * (uint64_t)psize;
	return total_ram_cache;
}

/* ------------ presets ------------- */

void
preset_to_lzma(lzma_opts *dst, int preset, int extreme)
{
	memset(dst, 0, sizeof(*dst));
	dst->lc = 3;
	dst->lp = 0;
	dst->pb = 2;
	switch (preset) {
	case 0: dst->dict_size = 256 << 10; dst->mode = COMP_MODE_FAST;
		dst->nice_len = 128; dst->mf = MF_HC3; dst->depth = 4; break;
	case 1: dst->dict_size = 1 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice_len = 128; dst->mf = MF_HC4; dst->depth = 8; break;
	case 2: dst->dict_size = 2 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice_len = 273; dst->mf = MF_HC4; dst->depth = 24; break;
	case 3: dst->dict_size = 4 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice_len = 273; dst->mf = MF_HC4; dst->depth = 48; break;
	case 4: dst->dict_size = 4 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 16; dst->mf = MF_BT4; dst->depth = 0; break;
	case 5: dst->dict_size = 8 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 32; dst->mf = MF_BT4; dst->depth = 0; break;
	case 6: dst->dict_size = 8 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	case 7: dst->dict_size = 16 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	case 8: dst->dict_size = 32 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	default: dst->dict_size = 64 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice_len = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	}
	if (extreme) {
		dst->mode = COMP_MODE_NORMAL;
		dst->mf = MF_BT4;
		switch (preset) {
		case 0: case 1: case 2: case 4: case 6: case 7: case 8:
		case 9:
			dst->nice_len = 273; dst->depth = 512; break;
		case 3: dst->nice_len = 192; dst->depth = 0; break;
		case 5: dst->nice_len = 192; dst->depth = 0; break;
		}
	}
}

/* ------------ value parsing ------------- */

static int
parse_uint(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	uint64_t v = 0;
	const char *p = s;
	while (*p >= '0' && *p <= '9') {
		v = v * 10 + (uint64_t)(*p - '0');
		if (v > 0xFFFFFFFFFFFFFFFFULL / 2)
			return -1;
		++p;
	}
	if (p == s)
		return -1;
	if (*p) {
		if (!strcmp(p, "KiB")) v *= 1024ULL;
		else if (!strcmp(p, "MiB")) v *= 1024ULL * 1024;
		else if (!strcmp(p, "GiB")) v *= 1024ULL * 1024 * 1024;
		else if (!strcmp(p, "kB")) v *= 1000ULL;
		else if (!strcmp(p, "MB")) v *= 1000000ULL;
		else if (!strcmp(p, "GB")) v *= 1000000000ULL;
		else return -1;
	}
	*out = v;
	return 0;
}

/* Parse a memory limit: bytes, % of RAM, or 0 */
static int
parse_memlimit(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	if (*s == '%') {
		const uint64_t ram = total_ram();
		uint64_t pct;
		if (parse_uint(s + 1, &pct))
			return -1;
		*out = ram / 100 * pct;
		return 0;
	}
	size_t len = strlen(s);
	char buf[64];
	if (len > 0 && s[len - 1] == '%') {
		uint64_t pct;
		if (len - 1 >= sizeof(buf))
			return -1;
		memcpy(buf, s, len - 1);
		buf[len - 1] = '\0';
		if (parse_uint(buf, &pct))
			return -1;
		const uint64_t ram = total_ram();
		*out = ram / 100 * pct;
		return 0;
	}
	return parse_uint(s, out);
}

/* ------------ filter string parsing ------------- */

static const struct { const char *name; uint32_t id; } filter_names[] = {
	{ "lzma1", 0x4000000000000001ULL },
	{ "lzma2", 0x21 },
	{ "delta", FILTER_ID_DELTA },
	{ "x86", FILTER_ID_X86 },
	{ "powerpc", FILTER_ID_POWERPC },
	{ "ia64", FILTER_ID_IA64 },
	{ "arm", FILTER_ID_ARM },
	{ "armthumb", FILTER_ID_ARMTHUMB },
	{ "sparc", FILTER_ID_SPARC },
	{ "arm64", FILTER_ID_ARM64 },
	{ "riscv", FILTER_ID_RISCV },
	{ NULL, 0 }
};

/* Error reporting with the caret */
static void
filter_error(const char *str, size_t pos, const char *msg)
{
	msg_error("Error in --filters=FILTERS option:");
	fprintf(stderr, "%s: %s\n", msg_progname(), str);
	fprintf(stderr, "%s: ", msg_progname());
	for (size_t i = 0; i < pos; ++i)
		fputc(' ', stderr);
	fprintf(stderr, "^\n");
	msg_error("%s", msg);
}

static void
opt_range_error(const char *name, uint64_t lo, uint64_t hi)
{
	msg_error("Value of the option '%s' must be in the range [%llu, %llu]",
			name, (unsigned long long)lo, (unsigned long long)hi);
	exit(1);
}

/* Parse options for a filter ("name:opt=1,opt=2").  Returns 0 on success. */
static int
parse_filter_opts(const char *str, size_t start, size_t end, filter_opt *fo)
{
	/* options are separated by ',' */
	size_t i = start;
	while (i < end) {
		size_t nstart = i;
		while (i < end && str[i] != '=')
			++i;
		size_t nlen = i - nstart;
		uint64_t val = 0;
		int have_val = 0;
		if (i < end) {
			++i;
			size_t vstart = i;
			while (i < end && str[i] != ',')
				++i;
			char buf[64];
			size_t vl = i - vstart;
			if (vl >= sizeof(buf))
				vl = sizeof(buf) - 1;
			memcpy(buf, str + vstart, vl);
			buf[vl] = '\0';
			if (parse_uint(buf, &val))
				return -2;
			have_val = 1;
		}
		char name[32];
		size_t nl = nlen < sizeof(name) - 1 ? nlen : sizeof(name) - 1;
		memcpy(name, str + nstart, nl);
		name[nl] = '\0';
		if (!strcmp(name, "preset")) {
			/* only for lzma1/lzma2 */
			if (fo->id == 0x21 || fo->id == 0x4000000000000001ULL) {
				int p = (int)val;
				if (p > 9)
					return -2;
				lzma_opts t;
				preset_to_lzma(&t, p, fo->start /* extreme flag */);
				fo->dist = t.dict_size;   /* store dict */
				return 0;
			}
			return -1;
		}
		if (fo->id == FILTER_ID_DELTA) {
			if (!strcmp(name, "dist")) {
				if (!have_val || val < 1 || val > 256) {
					opt_range_error("dist", 1, 256);
					return -1;
				}
				fo->dist = (uint32_t)val;
				continue;
			}
			return -1;
		}
		if (fo->id == FILTER_ID_X86 || fo->id == FILTER_ID_POWERPC
				|| fo->id == FILTER_ID_IA64
				|| fo->id == FILTER_ID_ARM
				|| fo->id == FILTER_ID_ARMTHUMB
				|| fo->id == FILTER_ID_SPARC
				|| fo->id == FILTER_ID_ARM64
				|| fo->id == FILTER_ID_RISCV) {
			if (!strcmp(name, "start")) {
				if (!have_val || val > 0xFFFFFFFFULL) {
					opt_range_error("start", 0, 4294967295ULL);
					return -1;
				}
				fo->start = (uint32_t)val;
				continue;
			}
			return -1;
		}
		/* lzma1/lzma2 */
		if (!strcmp(name, "dict")) {
			if (!have_val || val < 4096 || val > 1610612736ULL) {
				opt_range_error("dict", 4096, 1610612736ULL);
				return -1;
			}
			fo->dist = (uint32_t)val;
			continue;
		}
		if (!strcmp(name, "lc")) {
			if (!have_val || val > 4) {
				opt_range_error("lc", 0, 4);
				return -1;
			}
			fo->props[1] = (uint8_t)val;
			continue;
		}
		if (!strcmp(name, "lp")) {
			if (!have_val || val > 4) {
				opt_range_error("lp", 0, 4);
				return -1;
			}
			fo->props[2] = (uint8_t)val;
			continue;
		}
		if (!strcmp(name, "pb")) {
			if (!have_val || val > 4) {
				opt_range_error("pb", 0, 4);
				return -1;
			}
			fo->props[3] = (uint8_t)val;
			continue;
		}
		if (!strcmp(name, "nice")) {
			if (!have_val || val < 2 || val > 273) {
				opt_range_error("nice", 2, 273);
				return -1;
			}
			fo->props[4] = (uint8_t)val;
			fo->props[5] = (uint8_t)(val >> 8);
			continue;
		}
		if (!strcmp(name, "mode")) {
			/* value is fast or normal */
			return -1;
		}
		if (!strcmp(name, "mf")) {
			return -1;
