/* ------------ value parsing ------------- */

int
parse_uint_str(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	uint64_t v = 0;
	const char *p = s;
	while (*p >= '0' && *p <= '9') {
		const uint64_t d = (uint64_t)(*p - '0');
		if (v > (0xFFFFFFFFFFFFFFFFULL - d) / 10)
			return -1;
		v = v * 10 + d;
		++p;
	}
	if (p == s)
		return -1;
	if (*p) {
		if (!strcmp(p, "KiB")) v *= 1024ULL;
		else if (!strcmp(p, "MiB")) v *= 1024ULL * 1024;
		else if (!strcmp(p, "GiB")) v *= 1024ULL * 1024 * 1024;
		else if (!strcmp(p, "kB")) v *= 1000ULL;
		else if (!strcmp(p, "MB")) v *= 1000000ULL;
		else if (!strcmp(p, "GB")) v *= 1000000000ULL;
		else return -1;
	}
	*out = v;
	return 0;
}

static int
parse_memlimit_str(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	size_t len = strlen(s);
	if (s[len - 1] == '%') {
		char buf[64];
		if (len - 1 == 0 || len - 1 >= sizeof(buf))
			return -1;
		memcpy(buf, s, len - 1);
		buf[len - 1] = '\0';
		uint64_t pct;
		if (parse_uint_str(buf, &pct))
			return -1;
