options o;

static uint64_t total_ram_cache;

uint64_t
sys_total_ram(void)
{
	if (total_ram_cache)
		return total_ram_cache;
	long pages = sysconf(_SC_PHYS_PAGES);
	long psize = sysconf(_SC_PAGE_SIZE);
	if (pages > 0 && psize > 0)
		total_ram_cache = (uint64_t)pages * (uint64_t)psize;
	return total_ram_cache;
}

/* ------------ presets ------------- */

void
preset_to_lzma(filter_spec *dst, int preset, int extreme)
{
	memset(dst, 0, sizeof(*dst));
	dst->id = FID_LZMA2;
	dst->preset = -1;
	dst->lc = 3;
	dst->lp = 0;
	dst->pb = 2;
	switch (preset) {
	case 0: dst->dict = 256 << 10; dst->mode = COMP_MODE_FAST;
		dst->nice = 128; dst->mf = MF_HC3; dst->depth = 4; break;
	case 1: dst->dict = 1 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice = 128; dst->mf = MF_HC4; dst->depth = 8; break;
	case 2: dst->dict = 2 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice = 273; dst->mf = MF_HC4; dst->depth = 24; break;
	case 3: dst->dict = 4 << 20; dst->mode = COMP_MODE_FAST;
		dst->nice = 273; dst->mf = MF_HC4; dst->depth = 48; break;
	case 4: dst->dict = 4 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 16; dst->mf = MF_BT4; dst->depth = 0; break;
	case 5: dst->dict = 8 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 32; dst->mf = MF_BT4; dst->depth = 0; break;
	case 6: dst->dict = 8 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	case 7: dst->dict = 16 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	case 8: dst->dict = 32 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	default: dst->dict = 64 << 20; dst->mode = COMP_MODE_NORMAL;
		dst->nice = 64; dst->mf = MF_BT4; dst->depth = 0; break;
	}
	if (extreme) {
		dst->mode = COMP_MODE_NORMAL;
		dst->mf = MF_BT4;
		switch (preset) {
		case 0: case 1: case 2: case 4: case 6: case 7: case 8:
		case 9:
			dst->nice = 273; dst->depth = 512; break;
		default:
			dst->nice = 192; dst->depth = 0; break;
		}
	}
}

/* ------------ value parsing ------------- */

int
parse_uint_str(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	uint64_t v = 0;
	const char *p = s;
	while (*p >= '0' && *p <= '9') {
		const uint64_t d = (uint64_t)(*p - '0');
		if (v > (0xFFFFFFFFFFFFFFFFULL - d) / 10)
			return -1;
		v = v * 10 + d;
		++p;
	}
	if (p == s)
		return -1;
	if (*p) {
		if (!strcmp(p, "KiB")) v *= 1024ULL;
		else if (!strcmp(p, "MiB")) v *= 1024ULL * 1024;
		else if (!strcmp(p, "GiB")) v *= 1024ULL * 1024 * 1024;
		else if (!strcmp(p, "kB")) v *= 1000ULL;
		else if (!strcmp(p, "MB")) v *= 1000000ULL;
		else if (!strcmp(p, "GB")) v *= 1000000000ULL;
		else return -1;
	}
	*out = v;
	return 0;
}

int
parse_memlimit_str(const char *s, uint64_t *out)
{
	if (!s || !*s)
		return -1;
	const size_t len = strlen(s);
	if (s[len - 1] == '%') {
		char buf[64];
		if (len - 1 == 0 || len - 1 >= sizeof(buf))
			return -1;
		memcpy(buf, s, len - 1);
		buf[len - 1] = '\0';
		uint64_t pct;
		if (parse_uint_str(buf, &pct))
			return -1;
		*out = total_ram() / 100 * pct;
		return 0;
	}
	return parse_uint_str(s, out);
}

/* ------------ filter string parsing ------------- */

static void
filter_error(const char *str, size_t pos, const char *msg)
{
	msg_error("Error in --filters=FILTERS option:");
	fprintf(stderr, "%s: %s\n", msg_progname(), str);
	fprintf(stderr, "%s: ", msg_progname());
	for (size_t i = 0; i < pos; ++i)
		fputc(' ', stderr);
	fprintf(stderr, "^\n");
	msg_error("%s", msg);
}

static void
opt_range_error(const char *name, uint64_t lo, uint64_t hi)
{
	msg_error("Value of the option '%s' must be in the range [%llu, %llu]",
			name, (unsigned long long)lo, (unsigned long long)hi);
	exit(1);
}

static int
filter_id_from_name(const char *name, size_t len, uint64_t *id)
{
	static const struct { const char *n; uint64_t id; } t[] = {
		{ "lzma1", FID_LZMA1 },
		{ "lzma2", FID_LZMA2 },
		{ "delta", FILTER_ID_DELTA },
		{ "x86", FILTER_ID_X86 },
		{ "powerpc", FILTER_ID_POWERPC },
		{ "ia64", FILTER_ID_IA64 },
		{ "arm", FILTER_ID_ARM },
		{ "armthumb", FILTER_ID_ARMTHUMB },
		{ "sparc", FILTER_ID_SPARC },
		{ "arm64", FILTER_ID_ARM64 },
		{ "riscv", FILTER_ID_RISCV },
		{ NULL, 0 }
	};
	for (int i = 0; t[i].n; ++i)
		if (strlen(t[i].n) == len && !memcmp(t[i].n, name, len)) {
			*id = t[i].id;
			return 0;
		}
	return -1;
}

/* Parse the options of one filter; s points after ':'.
 * Returns the number of chars consumed or -1 on error. */
static int
parse_filter_opts(const char *str, size_t opt_start, size_t str_len,
		filter_spec *fo)
{
	size_t i = opt_start;
	for (;;) {
		if (i >= str_len)
			return (int)(i - opt_start);
		const size_t nstart = i;
		while (i < str_len && str[i] != '=' && str[i] != ',')
			++i;
		if (i == nstart)
			return (int)(i - opt_start);
		const size_t nlen = i - nstart;
		char vbuf[32];
		int have_val = 0;
		size_t vstart = 0, vlen = 0;
		if (i < str_len && str[i] == '=') {
			++i;
			vstart = i;
			while (i < str_len && str[i] != ',')
				++i;
			vlen = i - vstart;
			if (vlen >= sizeof(vbuf))
				vlen = sizeof(vbuf) - 1;
			memcpy(vbuf, str + vstart, vlen);
			vbuf[vlen] = '\0';
			have_val = 1;
		}
		const int last = i;
		if (i < str_len && str[i] == ',')
			++i;
		char name[32];
		const size_t nl = nlen < sizeof(name) - 1 ? nlen : sizeof(name) - 1;
		memcpy(name, str + nstart, nl);
		name[nl] = '\0';
#define RANGE(name_, lo_, hi_) do { \
		if (!have_val || val_ < (lo_) || val_ > (hi_)) \
			opt_range_error(name_, lo_, hi_); \
	} while (0)
		uint64_t val_ = 0;
		if (have_val)
			parse_uint_str(vbuf, &val_);
		if (fo->id == FILTER_ID_DELTA) {
			if (!strcmp(name, "dist")) {
				RANGE("dist", 1, 256);
				fo->dist = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			filter_error(str, nstart, "Unknown option name");
			return -1;
		}
		if (fo->id == FID_LZMA1 || fo->id == FID_LZMA2) {
			if (!strcmp(name, "preset")) {
				if (!have_val || val_ > 9) {
					filter_error(str, vstart,
							"Unsupported preset");
					return -1;
				}
				fo->preset = (int)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "dict")) {
				RANGE("dict", 4096, 1610612736ULL);
				fo->dict = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "lc")) {
				RANGE("lc", 0, 4);
				fo->lc = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "lp")) {
				RANGE("lp", 0, 4);
				fo->lp = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "pb")) {
				RANGE("pb", 0, 4);
				fo->pb = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "nice")) {
				RANGE("nice", 2, 273);
				fo->nice = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "depth")) {
				RANGE("depth", 0, 4294967295ULL);
				fo->depth = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "mode")) {
				if (vlen == 4 && !memcmp(vbuf, "fast", 4))
					fo->mode = COMP_MODE_FAST;
				else if (vlen == 6 && !memcmp(vbuf, "normal", 6))
					fo->mode = COMP_MODE_NORMAL;
				else {
					filter_error(str, vstart,
							"Unsupported option value");
					return -1;
				}
				fo->mode_set = 1;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "mf")) {
				int found = -1;
				static const struct { const char *n; uint32_t v; } mfs[] = {
					{ "hc3", MF_HC3 }, { "hc4", MF_HC4 },
					{ "bt2", MF_BT2 }, { "bt3", MF_BT3 },
					{ "bt4", MF_BT4 }, { NULL, 0 }
				};
				for (int j = 0; mfs[j].n; ++j)
					if (!strcmp(vbuf, mfs[j].n))
						found = (int)j;
				if (found < 0) {
					filter_error(str, vstart,
							"Unsupported option value");
					return -1;
				}
				fo->mf = mfs[found].v;
				fo->mf_set = 1;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			filter_error(str, nstart, "Unknown option name");
			return -1;
		}
		/* BCJ filters */
		if (!strcmp(name, "start")) {
			RANGE("start", 0, 4294967295ULL);
			fo->start = (uint32_t)val_;
			if (last >= (int)str_len)
				return (int)(last - opt_start);
			continue;
		}
		filter_error(str, nstart, "Unknown option name");
		return -1;
#undef RANGE
	}
}

int
parse_filter_string(const char *str, filter_chain *fc)
{
	memset(fc, 0, sizeof(*fc));
	fc->preset = -1;
	const size_t len = strlen(str);
	size_t i = 0;
	for (;;) {
		while (i < len && (str[i] == ' ' || str[i] == '\t'))
			++i;
		if (i >= len)
			break;
		if (fc->n == 4) {
			filter_error(str, i, "The maximum number of filters is four");
			return -1;
		}
		filter_spec *fo = &fc->f[fc->n];
		memset(fo, 0, sizeof(*fo));
		fo->preset = -1;
		/* preset? */
		if (str[i] >= '0' && str[i] <= '9') {
			size_t j = i;
			while (j < len && str[j] >= '0' && str[j] <= '9')
				++j;
			if (j < len && str[j] == 'e')
				++j;
			if (j >= len || str[j] == ' ' || str[j] == '\t') {
				const size_t dl = j - i;
				char buf[8];
				if (dl >= sizeof(buf)) {
					filter_error(str, i, "Unsupported preset");
					return -1;
				}
				memcpy(buf, str + i, dl);
				buf[dl] = '\0';
				int extreme = 0;
				if (buf[dl - 1] == 'e') {
					extreme = 1;
					buf[dl - 1] = '\0';
				}
				if (strlen(buf) != 1) {
					filter_error(str, i + 1,
						"Unsupported flag in the preset");
					return -1;
				}
				const int p = buf[0] - '0';
				preset_to_lzma(fo, p, extreme);
				fo->preset = p;
				fo->extreme = extreme;
				fc->n++;
				fc->preset = p;
				fc->preset_extreme = extreme;
				i = j;
				continue;
			}
			filter_error(str, i + 1, "Unsupported flag in the preset");
			return -1;
		}
		const size_t nstart = i;
		while (i < len && str[i] != ':' && str[i] != ' ' && str[i] != '\t'
				&& str[i] != '-')
			++i;
		uint64_t id;
		if (filter_id_from_name(str + nstart, i - nstart, &id)) {
			filter_error(str, nstart, "Unknown filter name");
			return -1;
		}
		fo->id = id;
		fo->dist = 1;
		if (i < len && str[i] == ':') {
			++i;
			const int used = parse_filter_opts(str, i, len, fo);
			if (used < 0)
				return -1;
			i += (size_t)used;
		}
		fc->n++;
		/* separator */
		while (i < len && (str[i] == ' ' || str[i] == '\t'))
			++i;
		if (i >= len)
			break;
		if (i + 1 < len && str[i] == '-' && str[i + 1] == '-') {
			i += 2;
			if (i >= len || str[i] == ' ' || str[i] == '\t') {
				filter_error(str, i, "Filter name is missing");
				return -1;
			}
			continue;
		}
	}
	/* the chain must end with a compression filter */
	if (fc->n == 0) {
		filter_error(str, 0,
			"Empty string is not allowed, try '6' if a default value is needed");
		return -1;
	}
