				continue;
			}
			if (!strcmp(name, "lp")) {
				RANGE("lp", 0, 4);
				fo->lp = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
			}
			if (!strcmp(name, "pb")) {
				RANGE("pb", 0, 4);
				fo->pb = (uint32_t)val_;
				if (last >= (int)str_len)
					return (int)(last - opt_start);
				continue;
