int
parse_filter_string(const char *str, filter_chain *fc)
{
	memset(fc, 0, sizeof(*fc));
	const size_t len = strlen(str);
	size_t i = 0;
	for (;;) {
		while (i < len && (str[i] == ' ' || str[i] == '\t'))
			++i;
		if (i >= len)
			break;
		if (fc->n == 4) {
			filter_error(str, i,
				"The maximum number of filters is four");
			return -1;
		}
		filter_spec *fo = &fc->f[fc->n];
		memset(fo, 0, sizeof(*fo));
		fo->preset = -1;
		if (str[i] >= '0' && str[i] <= '9') {
			size_t j = i;
			while (j < len && str[j] >= '0' && str[j] <= '9')
				++j;
			int extreme = 0;
			size_t dend = j;
			if (j < len && str[j] == 'e') {
				extreme = 1;
				++j;
				dend = j;
			}
			if (j < len && str[j] != ' ' && str[j] != '\t') {
				filter_error(str, dend,
					"Unsupported flag in the preset");
				return -1;
			}
			const size_t dl = dend - i;
			if (dl != 1 && dl != 2) {
				filter_error(str, i + 1,
					"Unsupported flag in the preset");
				return -1;
			}
			const char c = str[i];
			if (c < '0' || c > '9') {
				filter_error(str, i, "Unsupported preset");
				return -1;
			}
			const int p = c - '0';
			preset_to_spec(fo, p, extreme);
			fc->n++;
			i = j;
			continue;
		}
		const size_t nstart = i;
		while (i < len && str[i] != ':' && str[i] != ' ' && str[i] != '\t'
				&& str[i] != '-')
			++i;
		uint64_t id;
		if (filter_id_from_name(str + nstart, i - nstart, &id)) {
			filter_error(str, nstart, "Unknown filter name");
			return -1;
		}
		fo->id = id;
		fo->dist = 1;
		if (i < len && str[i] == ':') {
			++i;
			const int used = parse_filter_opts(str, i, len, fo);
			if (used < 0)
				return -1;
			i += (size_t)used;
		}
		fc->n++;
		while (i < len && (str[i] == ' ' || str[i] == '\t'))
			++i;
		if (i >= len)
			break;
		if (i + 1 < len && str[i] == '-' && str[i + 1] == '-') {
			i += 2;
			if (i >= len || str[i] == ' ' || str[i] == '\t') {
				filter_error(str, i, "Filter name is missing");
				return -1;
			}
			continue;
		}
	}
	if (fc->n == 0) {
		filter_error(str, 0,
			"Empty string is not allowed, try '6' if a default value is needed");
		return -1;
	}
	const uint64_t last_id = fc->f[fc->n - 1].id;
	if (last_id != FID_LZMA2 && last_id != FID_LZMA1) {
		filter_error(str, len,
			"Invalid filter chain ('lzma2' missing at the end?)");
		return -1;
	}
	return 0;
}
