/* ------------ chain building ------------ */

static filter_chain chain_from_filters;
static filter_chain chain_individual;
static int chain_source = 0;   /* 0 = none, 1 = preset, 2 = --filters */
static int preset_num = 6;

static void
add_individual(const filter_spec *fo)
{
	if (chain_individual.n >= 4) {
		msg_error("The maximum number of filters is four");
		exit(1);
	}
	chain_individual.f[chain_individual.n++] = *fo;
}

static void
set_preset(int p)
{
	chain_source = 1;
	preset_num = p;
}

/* ------------ long/short option parsing ------------- */

static void __attribute__((noreturn))
bad_option_long(const char *name)
{
	msg_error("unrecognized option '--%s'", name);
	msg_try_help();
	exit(1);
}

static void __attribute__((noreturn))
bad_option_short(char c)
{
	msg_error("invalid option -- '%c'", c);
	msg_try_help();
	exit(1);
}

static void __attribute__((noreturn))
need_arg_long(const char *name)
{
	msg_error("option '--%s' requires an argument", name);
	msg_try_help();
	exit(1);
}

static void __attribute__((noreturn))
need_arg_short(char c)
{
	msg_error("option requires an argument -- '%c'", c);
	msg_try_help();
	exit(1);
}

static const char *
get_value(const char *inline_val, int argc, char **argv, int *i,
		const char *longname, char shortname)
{
	if (inline_val)
		return inline_val;
	if (*i + 1 < argc)
		return argv[++*i];
	if (longname)
		need_arg_long(longname);
	need_arg_short(shortname);
}

