static void
print_help(int is_long)
{
	printf(is_long ? help_text_long : help_text_short, msg_progname());
}

static void
print_version(void)
{
	if (o.robot) {
		printf("XZ_VERSION=%llu\n", 50080022ULL);
		printf("LIBLZMA_VERSION=%llu\n", 50080022ULL);
	} else {
		printf("xz (XZ Utils) 5.8.2\nliblzma 5.8.2\n");
	}
}

static uint64_t default_mt_memlimit;

static void
print_info_memory(void)
{
	const uint64_t ram = sys_total_ram();
	printf("Hardware information:\n");
	printf("  Amount of physical memory (RAM):  %llu MiB (%llu B)\n",
			(unsigned long long)(ram >> 20), (unsigned long long)ram);
	long n = sysconf(_SC_NPROCESSORS_ONLN);
	if (n < 1)
		n = 1;
	printf("  Number of processor threads:      %ld\n", n);
	printf("\nMemory usage limits:\n");
	if (o.memlimit_compress_set && o.memlimit_compress)
		printf("  Compression:                      %llu MiB (%llu B)\n",
				(unsigned long long)(o.memlimit_compress >> 20),
				(unsigned long long)o.memlimit_compress);
	else
		printf("  Compression:                      Disabled\n");
	if (o.memlimit_decompress_set && o.memlimit_decompress)
		printf("  Decompression:                    %llu MiB (%llu B)\n",
				(unsigned long long)(o.memlimit_decompress >> 20),
				(unsigned long long)o.memlimit_decompress);
	else
		printf("  Decompression:                    Disabled\n");
	uint64_t mt = o.memlimit_mt_set ? o.memlimit_mt : default_mt_memlimit;
	if (mt)
		printf("  Multi-threaded decompression:     %llu MiB (%llu B)\n",
				(unsigned long long)(mt >> 20),
				(unsigned long long)mt);
	else
		printf("  Multi-threaded decompression:     Disabled\n");
	uint64_t d0 = default_mt_memlimit;
	if (d0)
		printf("  Default for -T0:                  %llu MiB (%llu B)\n",
				(unsigned long long)(d0 >> 20),
				(unsigned long long)d0);
	else
		printf("  Default for -T0:                  Disabled\n");
}

static const char filters_help_text[] =
"Filter chains are set using the --filters=FILTERS or --filters1=FILTERS ...\n"
"--filters9=FILTERS options. Each filter in the chain can be separated by\n"
"spaces or '--'. Alternatively a preset <0-9>[e] can be specified instead of\n"
"a filter chain.\n"
"\n"
"The supported filters and their options are:\n"
"lzma2:preset=<0-9[e]>,dict=<4KiB-1536MiB>,lc=<0-4>,lp=<0-4>,pb=<0-4>,"
"mode=<fast|normal>,nice=<2-273>,mf=<hc3|hc4|bt2|bt3|bt4>,depth=<0-4294967295>\n"
"x86:start=<0-4294967295>\n"
"arm:start=<0-4294967295>\n"
"armthumb:start=<0-4294967295>\n"
"arm64:start=<0-4294967295>\n"
"riscv:start=<0-4294967295>\n"
"powerpc:start=<0-4294967295>\n"
"ia64:start=<0-4294967295>\n"
"sparc:start=<0-4294967295>\n"
"delta:dist=<1-256>\n";

static void
set_format(const char *v)
{
	if (!strcmp(v, "auto"))
		o.format = FORMAT_AUTO;
	else if (!strcmp(v, "xz"))
		o.format = FORMAT_XZ;
	else if (!strcmp(v, "lzma") || !strcmp(v, "alone"))
		o.format = FORMAT_LZMA;
	else if (!strcmp(v, "lzip") || !strcmp(v, "lz"))
		o.format = FORMAT_LZIP;
	else if (!strcmp(v, "raw"))
		o.format = FORMAT_RAW;
	else {
		msg_error("%s: Unknown file format type", v);
		msg_try_help();
		exit(1);
	}
}

static void
set_check(const char *v)
{
	if (!strcmp(v, "none") || !strcmp(v, "no"))
		o.check = CHECK_NONE;
	else if (!strcmp(v, "crc32"))
		o.check = CHECK_CRC32;
	else if (!strcmp(v, "crc64"))
		o.check = CHECK_CRC64;
	else if (!strcmp(v, "sha256"))
		o.check = CHECK_SHA256;
	else {
		msg_error("%s: Unsupported integrity check type", v);
		msg_try_help();
		exit(1);
	}
}

static void
bad_uint(const char *v)
{
	msg_error("%s: Value is not a non-negative decimal integer", v);
	msg_try_help();
	exit(1);
}

/* Handle one long option.  Returns 1 if handled. */
static int
handle_long(const char *name, const char *val, int argc, char **argv, int *i)
{
	if (!strcmp(name, "compress")) { o.mode = MODE_COMPRESS; return 1; }
	if (!strcmp(name, "decompress") || !strcmp(name, "uncompress")) {
		o.mode = MODE_DECOMPRESS; return 1;
	}
	if (!strcmp(name, "test")) { o.mode = MODE_TEST; return 1; }
	if (!strcmp(name, "list")) { o.mode = MODE_LIST; return 1; }
	if (!strcmp(name, "keep")) { o.keep = 1; return 1; }
	if (!strcmp(name, "force")) { o.force = 1; return 1; }
	if (!strcmp(name, "stdout") || !strcmp(name, "to-stdout")) {
		o.stdout_mode = 1; o.keep = 1; return 1;
	}
	if (!strcmp(name, "no-sync")) { o.no_sync = 1; return 1; }
	if (!strcmp(name, "single-stream")) { o.single_stream = 1; return 1; }
	if (!strcmp(name, "no-sparse")) { o.no_sparse = 1; return 1; }
	if (!strcmp(name, "ignore-check")) { o.ignore_check = 1; return 1; }
	if (!strcmp(name, "no-adjust")) { o.no_adjust = 1; return 1; }
	if (!strcmp(name, "robot")) { o.robot = 1; return 1; }
	if (!strcmp(name, "no-warn")) { o.no_warn = 1; return 1; }
	if (!strcmp(name, "quiet")) { ++opt_quiet; return 1; }
	if (!strcmp(name, "verbose")) { ++opt_verbosity; return 1; }
	if (!strcmp(name, "info-memory")) { print_info_memory(); exit(0); }
	if (!strcmp(name, "help")) { print_help(0); exit(0); }
	if (!strcmp(name, "long-help")) { print_help(1); exit(0); }
	if (!strcmp(name, "version")) { print_version(); exit(0); }
	if (!strcmp(name, "filters-help")) {
		fputs(filters_help_text, stdout);
		exit(0);
	}
	if (!strcmp(name, "suffix")) {
		o.suffix = get_value(val, argc, argv, i, name, 0);
		return 1;
	}
	if (!strcmp(name, "format")) {
		set_format(get_value(val, argc, argv, i, name, 0));
		return 1;
	}
	if (!strcmp(name, "check")) {
		set_check(get_value(val, argc, argv, i, name, 0));
		return 1;
	}
	if (!strcmp(name, "threads")) {
		const char *v = get_value(val, argc, argv, i, name, 0);
		uint64_t t;
		if (parse_uint_str(v, &t) || t > 0x7FFFFFFF)
			bad_uint(v);
		o.threads = (int)t;
		return 1;
	}
	if (!strcmp(name, "block-size")) {
		const char *v = get_value(val, argc, argv, i, name, 0);
		uint64_t t;
		if (parse_uint_str(v, &t))
			bad_uint(v);
		o.block_size = t;
		return 1;
	}
	if (!strcmp(name, "block-list")) {
		o.block_list = get_value(val, argc, argv, i, name, 0);
		return 1;
	}
	if (!strcmp(name, "flush-timeout")) {
		const char *v = get_value(val, argc, argv, i, name, 0);
		uint64_t t;
		if (parse_uint_str(v, &t))
			bad_uint(v);
		o.flush_timeout = (int)t;
		return 1;
	}
	if (!strcmp(name, "memlimit-compress")
			|| !strcmp(name, "memlimit-decompress")
			|| !strcmp(name, "memlimit-mt-decompress")
			|| !strcmp(name, "memlimit")) {
		const char *v = get_value(val, argc, argv, i, name, 0);
		uint64_t t;
		if (parse_memlimit_str(v, &t))
			bad_uint(v);
		if (!strcmp(name, "memlimit-compress")) {
			o.memlimit_compress = t; o.memlimit_compress_set = 1;
		} else if (!strcmp(name, "memlimit-decompress")) {
			o.memlimit_decompress = t; o.memlimit_decompress_set = 1;
		} else if (!strcmp(name, "memlimit-mt-decompress")) {
			o.memlimit_mt = t; o.memlimit_mt_set = 1;
		} else {
			o.memlimit_compress = o.memlimit_decompress = t;
			o.memlimit_mt = t;
			o.memlimit_compress_set = o.memlimit_decompress_set = 1;
			o.memlimit_mt_set = 1;
		}
		return 1;
	}
	if (!strcmp(name, "files") || !strcmp(name, "files0")) {
		o.files0 = !strcmp(name, "files0");
		o.files_name = (char *)val;
		return 1;
	}
	if (!strcmp(name, "extreme")) { o.extreme = 1; return 1; }
	for (int k = 1; k <= 9; ++k) {
		char buf[16];
		snprintf(buf, sizeof(buf), "filters%d", k);
		if (!strcmp(name, buf)) {
			o.filters_str[k] = strdup(get_value(val, argc, argv, i, name, 0));
			if (k + 1 > o.n_filters_str)
				o.n_filters_str = k + 1;
			return 1;
		}
	}
	if (!strcmp(name, "filters")) {
		o.filters_str[0] = strdup(get_value(val, argc, argv, i, name, 0));
		if (o.n_filters_str < 1)
			o.n_filters_str = 1;
		return 1;
	}
	if (!strcmp(name, "lzma1") || !strcmp(name, "lzma2")
			|| !strcmp(name, "x86") || !strcmp(name, "arm")
			|| !strcmp(name, "armthumb") || !strcmp(name, "arm64")
			|| !strcmp(name, "powerpc") || !strcmp(name, "ia64")
			|| !strcmp(name, "sparc") || !strcmp(name, "riscv")
			|| !strcmp(name, "delta")) {
		const char *v = get_value(val, argc, argv, i, name, 0);
		char buf[512];
		if (!strcmp(name, "lzma1") || !strcmp(name, "lzma2"))
			snprintf(buf, sizeof(buf), "%s%s%s", name,
					v && *v ? ":" : "", v ? v : "");
		else
			snprintf(buf, sizeof(buf), "%s%s%s", name,
					v && *v ? ":" : "", v ? v : "");
		filter_chain fc;
		if (parse_filter_string(buf, &fc))
			exit(1);
		add_individual(&fc.f[0]);
		if (!strcmp(name, "lzma1") || !strcmp(name, "lzma2"))
			o.lzma_explicit = 1;
		return 1;
	}
	return 0;
}
