			size_t l = (size_t)(colon - p);
			if (l >= sizeof(buf))
				return -1;
			memcpy(buf, p, l);
			buf[l] = '\0';
			uint64_t c;
			if (parse_uint_str(buf, &c) || c > 9)
				return -1;
			chain = (int)c;
			num_start = colon + 1;
		}
		char buf[64];
		size_t l = (size_t)(end - num_start);
		if (l >= sizeof(buf))
			return -1;
		memcpy(buf, num_start, l);
		buf[l] = '\0';
		uint64_t sz;
		if (parse_uint_str(buf, &sz))
			return -1;
		if (sz == 0)
			return -1;
		if (n_block_list >= (int)(sizeof(block_list) / sizeof(block_list[0])))
			return -1;
		block_list[n_block_list].size = sz;
		block_list[n_block_list].chain = chain;
		++n_block_list;
		if (!comma)
			break;
		p = comma + 1;
	}
	return 0;
}

static void
finish_chains(void)
{
	o.n_chains = 1;
	if (chain_individual.n > 0) {
		o.chains[0] = chain_individual;
		return;
	}
	if (chain_source == 2) {
		o.chains[0] = chain_from_filters;
		return;
	}
	filter_spec fo;
	preset_to_spec(&fo, preset_num, o.extreme);
	o.chains[0].n = 1;
	o.chains[0].f[0] = fo;
	o.preset_set = 1;
	o.preset = preset_num;
}

void
opts_init(void)
{
	memset(&o, 0, sizeof(o));
	o.mode = MODE_COMPRESS;
	o.format = FORMAT_AUTO;
	o.check = CHECK_CRC64;
	o.threads = 0;
	o.suffix = ".xz";
}

void
opts_finish(void)
{
	/* parse the --filters= strings */
	for (int i = 0; i < 10; ++i) {
		if (!o.filters_str[i])
			continue;
		filter_chain fc;
		if (parse_filter_string(o.filters_str[i], &fc))
			exit(1);
		o.chains[i] = fc;
	}
	finish_chains();
	if (o.n_chains < 1)
		o.n_chains = 1;
	if (o.block_list) {
		if (parse_block_list(o.block_list)) {
			const char *p = o.block_list;
			msg_error("%s: Value is not a non-negative decimal integer", p);
			msg_try_help();
			exit(1);
		}
		for (int i = 0; i < n_block_list; ++i) {
			const int c = block_list[i].chain;
			if (c > 0 && !o.filters_str[c]) {
				msg_error("filter chain %d used by --block-list "
						"but not specified with --filters%d=", c, c);
				exit(1);
			}
		}
	}
	/* memory limits */
	if (!o.memlimit_mt_set && o.memlimit_decompress_set) {
		/* -M sets all three */
	}
	const uint64_t ram = sys_total_ram();
