	for (int i = 0; i < o.n_chains; ++i) {
		const filter_chain *fc = &o.chains[i];
		if (fc->n == 0)
			continue;
		const uint64_t last_id = fc->f[fc->n - 1].id;
		if (o.format == FORMAT_XZ && last_id != FID_LZMA2) {
			msg_error("Unsupported options in filter chain %d", i);
			exit(1);
		}
		if (o.format == FORMAT_LZMA) {
			if (last_id != FID_LZMA1) {
				msg_error("The .lzma format supports only the LZMA1 filter");
				exit(1);
			}
			if (fc->n > 1) {
				msg_error("The .lzma format supports only the LZMA1 filter");
				exit(1);
			}
		}
