void
args_parse(int argc, char **argv)
{
	opts_init();
	int i = 1;
	int no_more_opts = 0;
	for (; i < argc; ++i) {
		const char *arg = argv[i];
		if (no_more_opts || arg[0] != '-' || arg[1] == '\0') {
			/* file name - handled by the caller */
			break;
		}
		if (arg[1] == '-') {
			if (arg[2] == '\0') {
				++i;
				no_more_opts = 1;
				break;
			}
			const char *name = arg + 2;
			const char *eq = strchr(name, '=');
			size_t nl = eq ? (size_t)(eq - name) : strlen(name);
			char buf[64];
			if (nl >= sizeof(buf))
				bad_option_long(name);
			memcpy(buf, name, nl);
			buf[nl] = '\0';
			const char *val = eq ? eq + 1 : NULL;
			if (!handle_long(buf, val, argc, argv, &i))
				bad_option_long(buf);
			continue;
		}
		/* short options */
		for (const char *p = arg + 1; *p; ++p) {
			const char c = *p;
			switch (c) {
			case 'z': o.mode = MODE_COMPRESS; break;
			case 'd': o.mode = MODE_DECOMPRESS; break;
			case 't': o.mode = MODE_TEST; break;
			case 'l': o.mode = MODE_LIST; break;
			case 'k': o.keep = 1; break;
			case 'f': o.force = 1; break;
			case 'c': o.stdout_mode = 1; o.keep = 1; break;
			case 'e': o.extreme = 1; break;
			case 'q': ++opt_quiet; break;
			case 'v': ++opt_verbosity; break;
			case 'Q': o.no_warn = 1; break;
			case 'h': print_help(0); exit(0);
			case 'H': print_help(1); exit(0);
			case 'V': print_version(); exit(0);
			case 'M':
			case 'T':
			case 'S':
			case 'F':
			case 'C': {
				const char *val = NULL;
				if (p[1]) {
					val = p + 1;
					p += strlen(p) - 1;
				} else {
					if (i + 1 >= argc)
						need_arg_short(c);
					val = argv[++i];
				}
				switch (c) {
				case 'M': {
					uint64_t t;
					if (parse_memlimit_str(val, &t))
						bad_uint(val);
					o.memlimit_compress = o.memlimit_decompress = t;
					o.memlimit_mt = t;
					o.memlimit_compress_set = o.memlimit_decompress_set = 1;
					o.memlimit_mt_set = 1;
					break;
				}
				case 'T': {
					uint64_t t;
					if (parse_uint_str(val, &t) || t > 0x7FFFFFFF)
						bad_uint(val);
					o.threads = (int)t;
					break;
				}
				case 'S': o.suffix = val; break;
				case 'F': set_format(val); break;
				case 'C': set_check(val); break;
				}
				break;
			}
			default:
				if (c >= '0' && c <= '9') {
					set_preset(c - '0');
					break;
				}
				bad_option_short(c);
			}
		}
	}
	/* the remaining args are file names */
	o.first_file = i;
	o.argc = argc;
	o.argv = argv;
}
