{"command": "cat > src/main.c <<'EOF'
/* xz command line tool */
#include "opts.h"
#include "msg.h"
#include "container.h"
#include "check.h"
#include "lzma.h"
#include "filters.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define XZ_VERSION_STR "5.8.2"

extern const char help_text_short[];
extern const char help_text_long[];
extern const char filters_help_text[];
void print_help(int is_long);
void print_version(void);
void print_info_memory(void);

/* ------------------------------------------------------------------ */
/* output                                                              */
/* ------------------------------------------------------------------ */

typedef struct {
	int fd;
	int is_stdout;
	int sparse;
	uint64_t pos;
	char *name;
} out_file;

static int
out_write(void *ctx, const uint8_t *data, size_t len)
{
	out_file *of = ctx;
	size_t done = 0;
	while (done < len) {
		if (of->sparse) {
			if (data[done] == 0) {
				size_t z = 1;
				while (z < len - done && data[done + z] == 0)
					++z;
				if (z >= 4096) {
					if (lseek(of->fd, (off_t)z, SEEK_CUR) < 0)
						return -1;
					of->pos += z;
					done += z;
					continue;
				}
			}
		}
		ssize_t n = write(of->fd, data + done, len - done);
		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		done += (size_t)n;
		of->pos += (size_t)n;
	}
	return 0;
}

/* ------------------------------------------------------------------ */
/* coder                                                               */
/* ------------------------------------------------------------------ */

typedef struct {
	FILE *src;
	int src_is_stdin;
	const char *src_name;
	out_file out;
	struct stat src_st;
	int have_src_st;
	uint64_t in_pos;
	uint64_t out_pos;
	int test_mode;
} coder;

/* progress reporting */
static uint64_t prog_in, prog_out;
static const char *prog_name;

static int
sink_count(void *ctx, const uint8_t *data, size_t len)
{
	(void)ctx; (void)data;
	return 0;
}

static int
sink_out(void *ctx, const uint8_t *data, size_t len)
{
	out_file *of = ctx;
	if (of->fd < 0)
		return 0;
	if (out_write(of, data, len))
		return E_MEM;
	prog_out += len;
	return 0;
}

static int
sink_discard(void *ctx, const uint8_t *data, size_t len)
{
	(void)ctx; (void)data; (void)len;
	prog_out += len;
	return 0;
}

static size_t
stdin_read(void *ctx, uint8_t *dst, size_t n)
{
	FILE *f = ctx;
	const size_t got = fread(dst, 1, n, f);
	prog_in += got;
	return got;
}

/* Decompress from `fr` into `s`.  Returns E_* . */
static int
decode_stream(file_r *fr, sink *s, int format, int *used_format)
{
	if (format == FORMAT_AUTO) {
		/* Detect the format */
		uint8_t hdr[13];
		size_t n = 0;
		while (n < 13) {
			const int b = fr_getc(fr);
			if (b < 0)
				break;
			hdr[n++] = (uint8_t)b;
		}
		/* push back what was read */
		for (size_t i = n; i > 0; --i)
			fr_push(fr, &hdr[i - 1], 1);
		if (n >= 6 && !memcmp(hdr, "\xfd7zXZ\x00", 6)) {
			*used_format = FORMAT_XZ;
			return xz_stream_decode(fr, s, NULL, 0);
		}
		if (n >= 4 && !memcmp(hdr, "LZIP", 4)) {
			*used_format = FORMAT_LZIP;
			return lzma1_file_decode(fr, s, 1, 0);
		}
		*used_format = FORMAT_LZMA;
		if (!lzma1_header_valid(hdr, n))
			return E_FORMAT;
		return lzma1_file_decode(fr, s, 0, 0);
	}
	if (format == FORMAT_XZ)
		return xz_stream_decode(fr, s, NULL, 0);
	if (format == FORMAT_LZMA)
		return lzma1_file_decode(fr, s, 0, 0);
	if (format == FORMAT_LZIP)
		return lzma1_file_decode(fr, s, 1, 0);
	/* raw */
	return E_OPTIONS;
}

/* ------------------------------------------------------------------ */
/* file processing                                                     */
/* ------------------------------------------------------------------ */

static const char *const suffixes[] = { ".xz", ".txz", ".lzma", ".tlz",
		".lz", NULL };

/* Return the name with the suffix removed (or NULL if no known suffix). */
static char *
strip_suffix(const char *name)
{
	const size_t len = strlen(name);
	for (int i = 0; suffixes[i]; ++i) {
		const size_t sl = strlen(suffixes[i]);
		if (len > sl && !strcmp(name + len - sl, suffixes[i])) {
			char *r = malloc(len - sl + 1);
			memcpy(r, name, len - sl);
			r[len - sl] = '\0';
			return r;
		}
	}
	return NULL;
}

static int
has_suffix(const char *name, const char *suf)
{
	const size_t nl = strlen(name), sl = strlen(suf);
	return nl > sl && !strcmp(name + nl - sl, suf);
}

static char *
make_name(const char *src, const char *suffix)
{
	const size_t n = strlen(src) + strlen(suffix) + 1;
	char *r = malloc(n);
	snprintf(r, n, "%s%s", src, suffix);
	return r;
}

static void
unlink_src(const char *name)
{
	if (unlink(name) && errno != ENOENT)
		msg_warning("%s: Cannot remove: %s", name, strerror(errno));
}

static void
process_file(const char *name, int from_stdin)
{
	coder c;
	memset(&c, 0, sizeof(c));
	c.src_name = name;
	c.test_mode = o.mode == MODE_TEST;
	prog_in = prog_out = 0;
	prog_name = from_stdin ? "(stdin)" : name;

	/* Open the source */
	if (from_stdin) {
		c.src = stdin;
		c.src_is_stdin = 1;
	} else {
		c.src = fopen(name, "rb");
		if (!c.src) {
			msg_error("%s: %s", name, strerror(errno));
			return;
		}
		struct stat st;
		if (fstat(fileno(c.src), &st) == 0) {
			c.src_st = st;
			c.have_src_st = 1;
		}
	}

	/* Determine the destination */
	char *dst_name = NULL;
	if (o.stdout_mode || c.test_mode || o.mode == MODE_LIST) {
		/* write to stdout / nowhere */
	} else if (o.mode == MODE_DECOMPRESS) {
		if (from_stdin) {
			msg_error("--decompress cannot write to standard output");
			fclose(c.src);
			return;
		}
		dst_name = strip_suffix(name);
		if (!dst_name) {
			msg_warning("%s: Filename has an unknown suffix, skipping",
					name);
			fclose(c.src);
			return;
		}
	} else {
		/* compress */
		if (from_stdin) {
			/* compressed data goes to stdout */
		} else {
			if (has_suffix(name, o.suffix)) {
				msg_warning("%s: File already has '%s' suffix, skipping",
						name, o.suffix);
				fclose(c.src);
				return;
			}
			dst_name = make_name(name, o.suffix);
		}
	}

	/* Open the destination */
	if (c.test_mode || o.mode == MODE_LIST) {
		c.out.fd = -1;
		c.out.is_stdout = 0;
		c.out.sparse = 0;
		c.out.name = NULL;
	} else if (o.stdout_mode || !dst_name) {
		c.out.fd = fileno(stdout);
		c.out.is_stdout = 1;
		c.out.sparse = 0;
		c.out.name = NULL;
	} else {
		struct stat st;
		if (stat(dst_name, &st) == 0 && !o.force) {
			msg_error("%s: File exists", dst_name);
			free(dst_name);
			fclose(c.src);
			return;
		}
		const int fd = open(dst_name, O_WRONLY | O_CREAT | O_TRUNC, 0666);
		if (fd < 0) {
			msg_error("%s: %s", dst_name, strerror(errno));
			free(dst_name);
			fclose(c.src);
			return;
		}
		c.out.fd = fd;
		c.out.is_stdout = 0;
		c.out.sparse = (o.mode == MODE_DECOMPRESS && !o.no_sparse);
