		if (from_stdin) {
			msg_error("--decompress cannot write to standard output");
			fclose(c.src);
			return;
		}
		dst_name = strip_suffix(name);
		if (!dst_name) {
			msg_warning("%s: Filename has an unknown suffix, skipping",
					name);
			fclose(c.src);
			return;
		}
	} else {
		/* compress */
		if (from_stdin) {
			/* compressed data goes to stdout */
		} else {
			if (has_suffix(name, o.suffix)) {
				msg_warning("%s: File already has '%s' suffix, skipping",
						name, o.suffix);
				fclose(c.src);
				return;
			}
			dst_name = make_name(name, o.suffix);
		}
	}

	/* Open the destination */
	if (c.test_mode || o.mode == MODE_LIST) {
		c.out.fd = -1;
		c.out.is_stdout = 0;
		c.out.sparse = 0;
		c.out.name = NULL;
	} else if (o.stdout_mode || !dst_name) {
		c.out.fd = fileno(stdout);
		c.out.is_stdout = 1;
		c.out.sparse = 0;
		c.out.name = NULL;
	} else {
		struct stat st;
		if (stat(dst_name, &st) == 0 && !o.force) {
			msg_error("%s: File exists", dst_name);
			free(dst_name);
			fclose(c.src);
			return;
		}
		const int fd = open(dst_name, O_WRONLY | O_CREAT | O_TRUNC, 0666);
		if (fd < 0) {
			msg_error("%s: %s", dst_name, strerror(errno));
			free(dst_name);
			fclose(c.src);
			return;
		}
		c.out.fd = fd;
		c.out.is_stdout = 0;
		c.out.sparse = (o.mode == MODE_DECOMPRESS && !o.no_sparse);
		c.out.name = dst_name;
	}

	/* Run the coder */
	sink s;
	s.write = c.out.fd >= 0 ? sink_out : sink_discard;
	s.ctx = &c.out;

	file_r fr;
	fr_init(&fr, c.src);

	int ret = E_OK;
	if (o.mode == MODE_DECOMPRESS || o.mode == MODE_TEST) {
		int used = FORMAT_AUTO;
		ret = decode_stream(&fr, &s, o.format, &used);
		if (o.single_stream)
			ret = E_OK;
	} else if (o.mode == MODE_COMPRESS) {
		ret = compress_stream(&fr, &s);
	} else {
		ret = list_stream(&fr, name);
	}

	/* Finish */
	if (c.out.fd >= 0) {
		if (c.have_src_st) {
			fchmod(c.out.fd, c.src_st.st_mode & 07777);
			struct timespec ts[2];
			ts[0].tv_sec = c.src_st.st_atim.tv_sec;
			ts[0].tv_nsec = c.src_st.st_atim.tv_nsec;
			ts[1].tv_sec = c.src_st.st_mtim.tv_sec;
			ts[1].tv_nsec = c.src_st.st_mtim.tv_nsec;
			futimens(c.out.fd, ts);
		}
		fsync(c.out.fd);
		close(c.out.fd);
		c.out.fd = -1;
	}
	if (ret != E_OK) {
		switch (ret) {
		case E_BUF:
			msg_error("%s: Unexpected end of input", prog_name);
			break;
		case E_FORMAT:
			msg_error("%s: File format not recognized", prog_name);
			break;
		case E_DATA:
			msg_error("%s: Compressed data is corrupt", prog_name);
			break;
		case E_MEM:
			msg_error("%s: Cannot allocate memory", prog_name);
			break;
		case E_MEMLIMIT:
			msg_error("%s: Memory usage limit reached", prog_name);
			break;
		case E_UNSUPPORTED:
			msg_warning("%s: Unsupported check; not verifying "
					"file integrity", prog_name);
			break;
		default:
			msg_error("%s: Compressed data is corrupt", prog_name);
			break;
		}
		/* remove the partially written output */
		if (c.out.name && !o.keep)
			unlink(c.out.name);
	} else {
		if (o.verbosity >= 1)
			print_progress(prog_name, prog_in, prog_out);
		if (!c.test_mode && o.mode != MODE_LIST && !o.keep
				&& !c.src_is_stdin)
			unlink_src(name);
	}
	fclose(c.src);
	free(c.out.name);
}

static void
print_progress(const char *name, uint64_t in, uint64_t out)
{
	char a[32], b[32];
	format_size(a, sizeof(a), out);
	format_size(b, sizeof(b), in);
	fprintf(stderr, "%s: %s / %s = %.3f\n", name, a, b,
			in ? (double)out / (double)in : 1.0);
}

int
main(int argc, char **argv)
{
	msg_set_progname(argc > 0 ? argv[0] : "xz");
	setup_aliases();
	args_parse(argc, argv);
	opts_finish();
	/* file list */
	const int first = o.first_file;
	if (first >= argc && o.files_name == NULL && !o.files0 && !o.file_list)
		process_file(NULL, 1);
	else if (first >= argc && (o.files_name || o.files0)) {
		read_file_list();
	} else {
		for (int i = first; i < argc; ++i)
			process_file(argv[i], !strcmp(argv[i], "-"));
	}
	return exit_status;
}
