{"command": "cat > src/main.c <<'EOF'
/* xz command line tool */
#include "opts.h"
#include "msg.h"
#include "container.h"
#include "check.h"
#include "lzma.h"
#include "filters.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

extern void print_help(int is_long);
extern void print_version(void);
extern void print_info_memory(void);
extern void format_size(char *buf, size_t n, uint64_t v);
extern uint64_t default_mt_memlimit(void);
extern const char help_text_short[];
extern const char help_text_long[];
extern const char filters_help_text[];

uint64_t prog_in, prog_out;
const char *prog_name;

/* ------------------------------------------------------------------ */
/* output file                                                         */
/* ------------------------------------------------------------------ */

typedef struct {
	int fd;
	int is_stdout;
	int sparse;
	uint64_t pos;
	char *name;
	int opened;
} out_file;

static int
out_write(void *ctx, const uint8_t *data, size_t len)
{
	out_file *of = ctx;
	if (of->fd < 0)
		return 0;
	size_t done = 0;
	while (done < len) {
		if (of->sparse && data[done] == 0) {
			size_t z = 1;
			while (z < len - done && data[done + z] == 0)
				++z;
			if (z >= 4096) {
				if (lseek(of->fd, (off_t)z, SEEK_CUR) < 0)
					return -1;
				of->pos += z;
				done += z;
				continue;
			}
		}
		ssize_t n = write(of->fd, data + done, len - done);
		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		done += (size_t)n;
		of->pos += (size_t)n;
	}
	return 0;
}

static int
sink_out(void *ctx, const uint8_t *data, size_t len)
{
	out_file *of = ctx;
	if (out_write(of, data, len))
		return E_MEM;
	prog_out += len;
	return 0;
}

static int
sink_discard(void *ctx, const uint8_t *data, size_t len)
{
	(void)ctx; (void)data;
	prog_out += len;
	return 0;
}

/* ------------------------------------------------------------------ */
/* decompression                                                       */
/* ------------------------------------------------------------------ */

int
lzma1_header_valid(const uint8_t *hdr, size_t n)
{
	if (n < 13)
		return 0;
	const uint32_t props = hdr[0];
	if (props > (4 * 5 + 4) * 9 + 8)
		return 0;
	const uint32_t lc = props % 9;
	const uint32_t rem = props / 9;
	const uint32_t lp = rem % 5;
	if (lc + lp > 4)
		return 0;
	const uint32_t dict = (uint32_t)hdr[1] | ((uint32_t)hdr[2] << 8)
			| ((uint32_t)hdr[3] << 16) | ((uint32_t)hdr[4] << 24);
	if (dict != 0xFFFFFFFFU) {
		if (dict == 0)
			return 0;
		if (dict & (dict - 1)) {
			/* must be 3 * 2^n */
			uint32_t v = dict;
			int ok = 0;
			for (int i = 0; i < 31; ++i)
				if (v == 3U << i)
					ok = 1;
			if (!ok)
				return 0;
		}
	}
	const uint64_t size = (uint64_t)hdr[5] | ((uint64_t)hdr[6] << 8)
			| ((uint64_t)hdr[7] << 16) | ((uint64_t)hdr[8] << 24)
			| ((uint64_t)hdr[9] << 32) | ((uint64_t)hdr[10] << 40)
			| ((uint64_t)hdr[11] << 48) | ((uint64_t)hdr[12] << 56);
	if (size != 0xFFFFFFFFFFFFFFFFULL && size > (1ULL << 38))
		return 0;
	return 1;
}

static int
decode_stream(file_r *fr, sink *s, int format)
{
	if (format == FORMAT_AUTO) {
		uint8_t hdr[13];
		size_t n = 0;
		while (n < 13) {
			const int b = fr_getc(fr);
			if (b < 0)
				break;
			hdr[n++] = (uint8_t)b;
		}
		for (size_t i = n; i > 0; --i)
			fr_push(fr, &hdr[i - 1], 1);
		if (n >= 6 && !memcmp(hdr, "\xfd7zXZ\x00", 6))
			return xz_stream_decode(fr, s, NULL, 0);
		if (n >= 4 && !memcmp(hdr, "LZIP", 4))
			return lzma1_file_decode(fr, s, 1, 0);
		if (!lzma1_header_valid(hdr, n))
			return E_FORMAT;
		return lzma1_file_decode(fr, s, 0, 0);
	}
	if (format == FORMAT_XZ)
		return xz_stream_decode(fr, s, NULL, 0);
	if (format == FORMAT_LZMA)
		return lzma1_file_decode(fr, s, 0, 0);
	if (format == FORMAT_LZIP)
		return lzma1_file_decode(fr, s, 1, 0);
	return E_OPTIONS;
}

/* ------------------------------------------------------------------ */
/* names                                                               */
/* ------------------------------------------------------------------ */

static const char *const known_suffixes[] = { ".xz", ".txz", ".lzma",
		".tlz", ".lz", NULL };

static char *
strip_suffix(const char *name)
{
	const size_t len = strlen(name);
	for (int i = 0; known_suffixes[i]; ++i) {
		const size_t sl = strlen(known_suffixes[i]);
		if (len > sl && !strcmp(name + len - sl, known_suffixes[i])) {
			char *r = malloc(len - sl + 1);
			if (!r)
				return NULL;
			memcpy(r, name, len - sl);
			r[len - sl] = '\0';
			return r;
		}
	}
	return NULL;
}

static int
has_suffix(const char *name, const char *suf)
{
	const size_t nl = strlen(name), sl = strlen(suf);
	return nl > sl && !strcmp(name + nl - sl, suf);
}

static char *
make_name(const char *src, const char *suffix)
{
	const size_t n = strlen(src) + strlen(suffix) + 1;
	char *r = malloc(n);
	if (!r)
		return NULL;
	snprintf(r, n, "%s%s", src, suffix);
	return r;
}

/* ------------------------------------------------------------------ */
/* file list                                                           */
/* ------------------------------------------------------------------ */

static char **file_list;
static int n_file_list;

static void
add_to_file_list(const char *name)
{
	if (name[0] == '\0')
		return;
	file_list = realloc(file_list, (n_file_list + 1) * sizeof(char *));
	file_list[n_file_list++] = strdup(name);
}

static void
read_file_list(void)
{
	FILE *f = stdin;
	if (o.files_name) {
		f = fopen(o.files_name, o.files0 ? "rb" : "rb");
		if (!f) {
			msg_error("%s: %s", o.files_name, strerror(errno));
			exit(1);
		}
	}
	char buf[65536];
	size_t len = 0;
	int c;
	while ((c = fgetc(f)) != EOF) {
		if (o.files0 ? c == '\0' : c == '\n') {
			buf[len] = '\0';
			add_to_file_list(buf);
			len = 0;
		} else if (len < sizeof(buf) - 1) {
			buf[len++] = (char)c;
		}
	}
	if (len > 0) {
		buf[len] = '\0';
		add_to_file_list(buf);
	}
	if (o.files_name)
		fclose(f);
}

/* ------------------------------------------------------------------ */
/* progress                                                            */
/* ------------------------------------------------------------------ */

static void
print_progress(void)
{
	char a[32], b[32];
	format_size(a, sizeof(a), prog_out);
	format_size(b, sizeof(b), prog_in);
	fprintf(stderr, "%s: %s / %s = %.3f\n", prog_name, a, b,
			prog_in ? (double)prog_out / (double)prog_in : 1.0);
}

/* ------------------------------------------------------------------ */
/* file processing                                                     */
/* ------------------------------------------------------------------ */

static void
report_error(int ret)
{
	switch (ret) {
	case E_BUF:
		msg_error("%s: Unexpected end of input", prog_name);
		break;
	case E_FORMAT:
		msg_error("%s: File format not recognized", prog_name);
		break;
	case E_DATA:
		msg_error("%s: Compressed data is corrupt", prog_name);
		break;
	case E_MEM:
		msg_error("%s: Cannot allocate memory", prog_name);
		break;
	case E_MEMLIMIT:
		msg_error("%s: Memory usage limit reached", prog_name);
		break;
	case E_UNSUPPORTED:
		msg_warning("%s: Unsupported check; not verifying file "
				"integrity", prog_name);
		break;
	case E_OPTIONS:
		msg_error("%s: Unsupported options", prog_name);
		break;
	default:
		msg_error("%s: Compressed data is corrupt", prog_name);
		break;
	}
}

static void
process_file(const char *name, int from_stdin)
{
	prog_in = prog_out = 0;
	prog_name = from_stdin ? "(stdin)" : name;
	const int test = o.mode == MODE_TEST;
	const int to_stdout = o.stdout_mode || from_stdin;
	const int write_out = !test && o.mode != MODE_LIST;

	FILE *src = stdin;
	struct stat src_st;
	int have_st = 0;
	if (!from_stdin) {
		src = fopen(name, "rb");
		if (!src) {
			msg_error("%s: %s", name, strerror(errno));
			return;
		}
		if (fstat(fileno(src), &src_st) == 0) {
			if (S_ISDIR(src_st.st_mode)) {
				msg_warning("%s: Is a directory, skipping", name);
				fclose(src);
				return;
			}
			have_st = 1;
		}
	}

	char *dst_name = NULL;
	if (write_out && !to_stdout) {
		if (o.mode == MODE_DECOMPRESS) {
			dst_name = strip_suffix(name);
			if (!dst_name) {
				msg_warning("%s: Filename has an unknown suffix, "
						"skipping", name);
				fclose(src);
				return;
			}
		} else {
			if (has_suffix(name, o.suffix)) {
				msg_warning("%s: File already has '%s' suffix, "
						"skipping", name, o.suffix);
				fclose(src);
				return;
			}
			dst_name = make_name(name, o.suffix);
		}
	}

	out_file of;
	memset(&of, 0, sizeof(of));
	of.fd = -1;
	if (write_out && to_stdout) {
		of.fd = fileno(stdout);
		of.is_stdout = 1;
	} else if (write_out && dst_name) {
		struct stat st;
		if (stat(dst_name, &st) == 0 && !o.force) {
			msg_error("%s: File exists", dst_name);
			free(dst_name);
			fclose(src);
			return;
		}
		of.fd = open(dst_name, O_WRONLY | O_CREAT | O_TRUNC, 0666);
		if (of.fd < 0) {
			msg_error("%s: %s", dst_name, strerror(errno));
			free(dst_name);
			fclose(src);
			return;
		}
		of.opened = 1;
		of.sparse = o.mode == MODE_DECOMPRESS && !o.no_sparse;
		of.name = dst_name;
	} else {
		free(dst_name);
		dst_name = NULL;
	}

	sink s;
	s.write = of.fd >= 0 ? sink_out : sink_discard;
	s.ctx = &of;

	file_r fr;
	fr_init(&fr, src);

	int ret = E_OK;
	if (o.mode == MODE_DECOMPRESS || test) {
		ret = decode_stream(&fr, &s, o.format);
	} else if (o.mode == MODE_COMPRESS) {
		ret = compress_stream(&fr, &s, name);
	} else {
		ret = list_file(&fr, name);
	}

	if (of.fd >= 0) {
		if (have_st) {
			fchmod(of.fd, src_st.st_mode & 07777);
			struct timespec ts[2];
			ts[0].tv_sec = src_st.st_atim.tv_sec;
			ts[0].tv_nsec = src_st.st_atim.tv_nsec;
			ts[1].tv_sec = src_st.st_mtim.tv_sec;
			ts[1].tv_nsec = src_st.st_mtim.tv_nsec;
			futimens(of.fd, ts);
		}
		fsync(of.fd);
		close(of.fd);
		of.fd = -1;
	}
	if (ret != E_OK) {
		report_error(ret);
		if (of.opened && !o.keep)
			unlink(of.name);
	} else {
		if (o.verbosity >= 1 && (o.mode == MODE_COMPRESS
					|| o.mode == MODE_DECOMPRESS))
			print_progress();
		if (!test && o.mode != MODE_LIST && !o.keep && !from_stdin)
			if (unlink(name) && errno != ENOENT)
				msg_warning("%s: Cannot remove", name);
	}
	fclose(src);
	free(of.name);
}

/* ------------------------------------------------------------------ */

static void
setup_aliases(void)
{
	const char *p = msg_progname();
	const char *base = strrchr(p, '/');
	if (base)
		base = base + 1;
	else
		base = p;
	if (!strcmp(base, "unxz")) {
		o.mode = MODE_DECOMPRESS;
	} else if (!strcmp(base, "xzcat")) {
		o.mode = MODE_DECOMPRESS;
		o.stdout_mode = 1;
		o.keep = 1;
	} else if (!strcmp(base, "lzma")) {
		o.format = FORMAT_LZMA;
		o.suffix = ".lzma";
	} else if (!strcmp(base, "unlzma")) {
		o.mode = MODE_DECOMPRESS;
		o.format = FORMAT_LZMA;
	} else if (!strcmp(base, "lzcat")) {
		o.mode = MODE_DECOMPRESS;
		o.format = FORMAT_LZIP;
		o.stdout_mode = 1;
		o.keep = 1;
	}
}

int
main(int argc, char **argv)
{
	msg_set_progname(argc > 0 && argv[0] ? argv[0] : "xz");
	opts_init();
	setup_aliases();
	args_parse(argc, argv);
	opts_finish();

	if (o.files_name || o.files0)
		read_file_list();

	if (n_file_list > 0) {
		for (int i = 0; i < n_file_list; ++i)
			process_file(file_list[i], !strcmp(file_list[i], "-"));
	} else if (o.first_file >= argc) {
		process_file(NULL, 1);
	} else {
		for (int i = o.first_file; i < argc; ++i)
			process_file(argv[i], !strcmp(argv[i], "-"));
	}
	return exit_status;
}
