/* LZMA1/LZMA2 encoder */
#include "lzma.h"
#include "opts.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ---------------- range encoder ---------------- */

void
rc_init(rc_enc *rc, uint8_t *out, size_t out_size)
{
	rc->low = 0;
	rc->range = 0xFFFFFFFFU;
	rc->cache = 0;
	rc->cache_size = 1;
	rc->out = out;
	rc->out_pos = 0;
	rc->out_size = out_size;
	rc->err = 0;
}

static void
rc_write(rc_enc *rc, uint8_t b)
{
	if (rc->out_pos < rc->out_size)
		rc->out[rc->out_pos++] = b;
	else
		rc->err = 1;
}

static void
rc_shift_low(rc_enc *rc)
{
	if ((uint32_t)rc->low < 0xFF000000U || (uint32_t)(rc->low >> 32) != 0) {
		do {
			rc_write(rc, (uint8_t)(rc->cache + (rc->low >> 32)));
			rc->cache = 0xFF;
		} while (--rc->cache_size != 0);
		rc->cache = (uint8_t)(rc->low >> 24);
	}
	++rc->cache_size;
	rc->low = (rc->low << 8) & 0xFFFFFFFFU;
}

void
rc_flush(rc_enc *rc)
{
	for (int i = 0; i < 5; ++i)
		rc_shift_low(rc);
}

void
rc_bit(rc_enc *rc, probability *prob, uint32_t bit)
{
	const uint32_t bound = (rc->range >> LZMA_PROB_BITS) * (uint32_t)*prob;
	if (bit == 0) {
		rc->range = bound;
		*prob = (probability)(*prob + ((LZMA_PROB_TOTAL
				- (uint32_t)*prob) >> LZMA_MOVE_BITS));
	} else {
		rc->low += bound;
		rc->range -= bound;
		*prob = (probability)(*prob - (*prob >> LZMA_MOVE_BITS));
	}
	while (rc->range < (1U << 24)) {
		rc->range <<= 8;
		rc_shift_low(rc);
	}
}

void
rc_direct(rc_enc *rc, uint32_t bits, uint32_t value)
{
	for (int i = (int)bits - 1; i >= 0; --i) {
		rc->range >>= 1;
		if ((value >> i) & 1)
			rc->low += rc->range;
		while (rc->range < (1U << 24)) {
			rc->range <<= 8;
			rc_shift_low(rc);
		}
	}
}

void
rc_bit_tree(rc_enc *rc, probability *probs, uint32_t bits, uint32_t value)
{
	uint32_t symbol = 1;
	for (uint32_t i = bits; i > 0; --i) {
		const uint32_t bit = (value >> (i - 1)) & 1;
		rc_bit(rc, &probs[symbol], bit);
		symbol = (symbol << 1) | bit;
	}
}

void
rc_bit_tree_reverse(rc_enc *rc, probability *probs, uint32_t bits,
		uint32_t value)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = (value >> i) & 1;
		rc_bit(rc, &probs[symbol], bit);
		symbol = (symbol << 1) | bit;
	}
}

/* ---------------- price helpers ---------------- */

#define RC_PRICE_SHIFT 7
static uint32_t price_table[LZMA_PROB_TOTAL >> LZMA_MOVE_BITS];

void
lzma_price_init(void)
{
	static int done;
	if (done)
		return;
	done = 1;
	const uint32_t n = LZMA_PROB_TOTAL >> LZMA_MOVE_BITS;
	for (uint32_t i = 0; i < n; ++i) {
		const double p = (double)(i + 0.5) / (double)LZMA_PROB_TOTAL;
		const double bits = -log2(p);
		price_table[i] = (uint32_t)(bits * (1 << RC_PRICE_SHIFT) + 0.5);
	}
}

uint32_t
rc_bit_price(const probability prob, const uint32_t bit)
{
	const uint32_t m = (uint32_t)prob ^ ((0U - bit) & (LZMA_PROB_TOTAL - 1));
	return price_table[m >> LZMA_MOVE_BITS];
}

/* ---------------- match finder ---------------- */

#define MF_MAX_DIST 0x100000000ULL

typedef struct {
	uint8_t *buf;
	size_t buf_size;
	size_t size;        /* valid bytes in buf */
	size_t pos;         /* current position */
	uint32_t dict_size;
	uint32_t nice_len;
	uint32_t depth;
	int mf;
	/* hash chains */
	uint32_t *head;     /* hash_size entries */
	uint32_t *prev;     /* dict_size entries */
	uint32_t hash_size;
	int inited;
} match_finder;

#define HASH_BITS 18
#define HASH_SIZE (1 << HASH_BITS)

static void
mf_init(match_finder *mf, uint32_t dict_size, uint32_t nice_len,
		uint32_t depth, int mf_type)
{
	memset(mf, 0, sizeof(*mf));
	mf->dict_size = dict_size;
	mf->nice_len = nice_len;
	mf->depth = depth;
	mf->mf = mf_type;
	mf->hash_size = HASH_SIZE;
	mf->head = malloc(HASH_SIZE * sizeof(uint32_t));
	mf->prev = malloc(dict_size * sizeof(uint32_t));
	memset(mf->head, 0xFF, HASH_SIZE * sizeof(uint32_t));
	memset(mf->prev, 0xFF, dict_size * sizeof(uint32_t));
	mf->inited = 1;
}

static void
mf_free(match_finder *mf)
{
	free(mf->head);
	free(mf->prev);
	mf->head = NULL;
	mf->prev = NULL;
}

static inline uint32_t
mf_hash4(const uint8_t *p)
{
	return ((uint32_t)p[0] | ((uint32_t)p[1] << 8)
			| ((uint32_t)p[2] << 16)) * 2654435761U >> (32 - HASH_BITS)
			| 0;
}

/* Find the longest match at the current position.  Returns the length and
 * sets *dist to the distance (dist = actual offset - 1). */
static uint32_t
mf_find(match_finder *mf, uint32_t *dist, uint32_t max_len)
{
	const size_t pos = mf->pos;
	const uint8_t *buf = mf->buf;
	const size_t size = mf->size;
	if (pos + 2 >= size)
		return 0;
	const uint32_t h = mf_hash4(buf + pos);
	uint32_t best_len = 1;
	uint32_t best_dist = 0;
	uint32_t cur = mf->head[h];
	uint32_t tries = mf->depth ? mf->depth : 1024;
	uint32_t min_pos = pos > mf->dict_size ? pos - mf->dict_size : 0;
	const uint32_t max = max_len ? max_len : mf->nice_len;
