/* ---------------- LZMA1 core encoder ---------------- */

typedef struct {
	lzma_probs p;
	probability *lit;
	uint32_t lc, lp, pb;
	uint32_t pos_mask, lp_mask;
	uint32_t state;
	uint32_t reps[4];
	rc_enc rc;
	/* dictionary */
	uint8_t *dict;
	size_t dict_size;
	size_t buf_size;
	size_t buf_pos;      /* number of bytes in dict buffer */
	uint64_t dict_pos;
} lzma_enc_state;

static void
enc_reset(lzma_enc_state *e, uint32_t lc, uint32_t lp, uint32_t pb,
		uint32_t dict_size)
{
	e->lc = lc;
	e->lp = lp;
	e->pb = pb;
	e->pos_mask = (1U << pb) - 1;
	e->lp_mask = (1U << lp) - 1;
	e->state = 0;
	e->reps[0] = e->reps[1] = e->reps[2] = e->reps[3] = 0;
	e->buf_pos = 0;
	e->dict_pos = 0;
	e->dict_size = dict_size;
	lzma_probs_init(&e->p);
	const size_t n = lzma_literal_probs_size(lc, lp);
	e->lit = malloc(n * sizeof(probability));
	for (size_t i = 0; i < n; ++i)
		e->lit[i] = LZMA_PROB_TOTAL / 2;
	rc_init(&e->rc, NULL, 0);
}

static void
enc_free(lzma_enc_state *e)
{
	free(e->lit);
	free(e->dict);
	e->lit = NULL;
	e->dict = NULL;
}

static void
enc_put(lzma_enc_state *e, uint8_t b)
{
	e->dict[e->buf_pos++] = b;
	++e->dict_pos;
}

/* Encode a literal */
static void
enc_literal(lzma_enc_state *e, uint8_t byte, uint8_t prev_byte)
{
	const uint32_t pos_state = (uint32_t)e->dict_pos & e->pos_mask;
	rc_bit(&e->rc, &e->p.is_match[(e->state << LZMA_POS_STATES_MAX)
			+ pos_state], 0);
	const uint32_t lit_state = ((uint32_t)(e->dict_pos & e->lp_mask)
			<< e->lc) + (prev_byte >> (8 - e->lc));
	probability *lprobs = e->lit + ((size_t)lit_state << 8) + lit_state;
	uint32_t symbol = 1;
	if (e->state >= LZMA_LIT_STATES) {
		const uint32_t r0 = e->reps[0];
		uint32_t match_byte = 0;
		if (e->buf_pos > r0)
			match_byte = e->dict[e->buf_pos - 1 - r0];
		for (int i = 7; i >= 0; --i) {
			const uint32_t match_bit = (match_byte >> 7) & 1;
			match_byte <<= 1;
			const uint32_t bit = (byte >> i) & 1;
			rc_bit(&e->rc, &lprobs[0x100 + (match_bit << 8) + symbol],
					bit);
			symbol = (symbol << 1) | bit;
			if (match_bit != bit) {
				/* rest uses the plain literal tree */
				for (--i; i >= 0; --i) {
					const uint32_t b2 = (byte >> i) & 1;
					rc_bit(&e->rc, &lprobs[symbol], b2);
					symbol = (symbol << 1) | b2;
				}
				break;
			}
		}
	} else {
		for (int i = 7; i >= 0; --i) {
			const uint32_t bit = (byte >> i) & 1;
			rc_bit(&e->rc, &lprobs[symbol], bit);
			symbol = (symbol << 1) | bit;
		}
	}
	e->state = e->state < 4 ? 0 : (e->state < 10 ? e->state - 3
			: e->state - 6);
	enc_put(e, byte);
}

static void
enc_len(lzma_enc_state *e, uint32_t len, uint32_t pos_state)
{
	/* len is the real length (>= 2); we encode len - 2 */
	uint32_t v = len - LZMA_MATCH_MIN_LEN;
	if (v < 8) {
		rc_bit(&e->rc, &e->p.len_choice, 0);
		rc_bit_tree(&e->rc, e->p.len_low[pos_state], 3, v);
	} else if (v < 16) {
		rc_bit(&e->rc, &e->p.len_choice, 1);
		rc_bit(&e->rc, &e->p.len_choice2, 0);
		rc_bit_tree(&e->rc, e->p.len_mid[pos_state], 3, v - 8);
	} else {
		rc_bit(&e->rc, &e->p.len_choice, 1);
		rc_bit(&e->rc, &e->p.len_choice2, 1);
		rc_bit_tree(&e->rc, e->p.len_high, 8, v - 16);
	}
