/* ---------------- LZMA2 encoder ---------------- */

typedef struct {
	filter_spec lzma;      /* lzma options */
	uint8_t *dict;
	size_t dict_size;
	size_t buf_pos;
	uint64_t dict_pos;
	lzma_probs p;
	probability *lit;
	uint32_t lc, lp, pb;
	uint32_t pos_mask, lp_mask;
	uint32_t state;
	uint32_t reps[4];
	rc_enc rc;
} lz2_enc;

/* Compress `in` (n bytes) with LZMA2 into out.  Returns the number of bytes
 * written. */
static size_t
lzma2_encode_buf(const filter_spec *lz, const uint8_t *in, size_t n,
		uint8_t *out, size_t out_size, uint32_t dict_size)
{
	lz2_enc e;
	memset(&e, 0, sizeof(e));
	e.lc = lz->lc;
	e.lp = lz->lp;
	e.pb = lz->pb;
	e.pos_mask = (1U << e.pb) - 1;
	e.lp_mask = (1U << e.lp) - 1;
	e.state = 0;
	e.reps[0] = e.reps[1] = e.reps[2] = e.reps[3] = 0;
	e.dict_size = dict_size;
	e.dict = malloc(dict_size + 4096);
	e.buf_pos = 0;
	e.dict_pos = 0;
