/* Compression and listing */
#include "opts.h"
#include "msg.h"
#include "container.h"
#include "check.h"
#include "lzma.h"
#include "filters.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

extern uint64_t prog_in, prog_out;
extern const char *prog_name;

#define CHUNK_MAX_FIRST 2096914U
#define CHUNK_MAX_NEXT  2096913U
#define PACKED_MAX      61440U
#define UNCOMP_CHUNK_MAX 65536U

/* ------------------------------------------------------------------ */
/* LZMA1 encoder over a memory buffer                                  */
/* ------------------------------------------------------------------ */

#define MF_HASH_BITS 17
#define MF_HASH_SIZE (1 << MF_HASH_BITS)

typedef struct {
	lzma_probs p;
	probability *lit;
	uint32_t lc, lp, pb;
	uint32_t pos_mask, lp_mask;
	uint32_t state;
	uint32_t reps[4];
	rc_enc rc;
	const uint8_t *buf;
	size_t len;
	size_t pos;
	uint32_t dict_size;
	uint32_t nice_len;
	uint32_t depth;
	int mode;
	uint32_t *head;
	uint32_t *prev;
} lz1e;

static void
lz1e_init(lz1e *e, const uint8_t *buf, size_t len, const filter_spec *lz)
{
	memset(e, 0, sizeof(*e));
	e->buf = buf;
	e->len = len;
	e->pos = 0;
	e->lc = lz->lc;
	e->lp = lz->lp;
	e->pb = lz->pb;
	e->pos_mask = (1U << e->pb) - 1;
	e->lp_mask = (1U << e->lp) - 1;
	e->state = 0;
	e->reps[0] = e->reps[1] = e->reps[2] = e->reps[3] = 0;
	e->dict_size = lz->dict;
	e->nice_len = lz->nice;
	e->depth = lz->depth;
	e->mode = lz->mode;
	lzma_probs_init(&e->p);
	const size_t nl = lzma_literal_probs_size(e->lc, e->lp);
	e->lit = malloc(nl * sizeof(probability));
	for (size_t i = 0; i < nl; ++i)
		e->lit[i] = LZMA_PROB_TOTAL / 2;
	e->head = malloc(MF_HASH_SIZE * sizeof(uint32_t));
	e->prev = malloc((len + 4) * sizeof(uint32_t));
	memset(e->head, 0xFF, MF_HASH_SIZE * sizeof(uint32_t));
	memset(e->prev, 0xFF, (len + 4) * sizeof(uint32_t));
}

static void
lz1e_free(lz1e *e)
{
	free(e->lit);
	free(e->head);
	free(e->prev);
	e->lit = NULL;
	e->head = NULL;
	e->prev = NULL;
}

static inline uint32_t
mf_hash(const uint8_t *p)
{
	uint32_t v = (uint32_t)p[0] | ((uint32_t)p[1] << 8)
			| ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
	return (v * 2654435761U) >> (32 - MF_HASH_BITS);
}

static void
mf_insert(lz1e *e, size_t pos)
{
	if (pos + 3 >= e->len)
		return;
	const uint32_t h = mf_hash(e->buf + pos);
	e->prev[pos] = e->head[h];
	e->head[h] = (uint32_t)pos;
}

/* Find the longest match at pos; dist = actual offset - 1 */
static uint32_t
mf_find(lz1e *e, uint32_t *dist, size_t pos, uint32_t nice, uint32_t depth)
{
	if (pos + 3 >= e->len)
		return 0;
	const uint8_t *buf = e->buf;
	const uint32_t h = mf_hash(buf + pos);
	uint32_t best_len = 1;
	uint32_t best_dist = 0;
	uint32_t cur = e->head[h];
	uint32_t tries = depth ? depth : 4096;
	const size_t min_pos = pos > e->dict_size ? pos - e->dict_size : 0;
	const size_t lim = e->len - pos;
	const uint32_t cap = nice < lim ? nice : (uint32_t)lim;
	if (cap < 2)
		return 0;
	while (cur != 0xFFFFFFFFU && cur >= min_pos && tries--) {
		const uint8_t *a = buf + pos;
		const uint8_t *b = buf + cur;
		if (a[0] == b[0] && a[1] == b[1] && a[2] == b[2]) {
			uint32_t len = 3;
			while (len < cap && a[len] == b[len])
				++len;
			if (len > best_len) {
				best_len = len;
				best_dist = (uint32_t)(pos - cur);
				if (len >= cap)
					break;
			}
		}
		cur = e->prev[cur];
	}
	if (best_len < 2)
		return 0;
	*dist = best_dist - 1;
	return best_len;
}

static void
enc_len(lz1e *e, uint32_t len, uint32_t pos_state)
{
	uint32_t v = len - LZMA_MATCH_MIN_LEN;
	if (v < 8) {
		rc_bit(&e->rc, &e->p.len_choice, 0);
		rc_bit_tree(&e->rc, e->p.len_low[pos_state], 3, v);
	} else if (v < 16) {
		rc_bit(&e->rc, &e->p.len_choice, 1);
		rc_bit(&e->rc, &e->p.len_choice2, 0);
		rc_bit_tree(&e->rc, e->p.len_mid[pos_state], 3, v - 8);
	} else {
		rc_bit(&e->rc, &e->p.len_choice, 1);
		rc_bit(&e->rc, &e->p.len_choice2, 1);
		rc_bit_tree(&e->rc, e->p.len_high, 8, v - 16);
	}
}

static void
enc_distance(lz1e *e, uint32_t dist)
{
	uint32_t pos_slot;
	if (dist < 4)
		pos_slot = dist;
	else {
		uint32_t d = dist;
		uint32_t bits = 0;
		while (d >>= 1)
			++bits;
		pos_slot = 2 * bits + ((dist >> (bits - 1)) & 1);
	}
	rc_bit_tree(&e->rc, e->p.pos_slot, 6, pos_slot);
	if (pos_slot >= 4) {
		const uint32_t ndb = (pos_slot >> 1) - 1;
		const uint32_t base = (2 | (pos_slot & 1)) << ndb;
		const uint32_t rest = dist - base;
		if (pos_slot < LZMA_END_POS_MODEL_INDEX) {
			rc_bit_tree_reverse(&e->rc,
					&e->p.pos_special[dist - pos_slot], ndb,
					rest);
		} else {
			rc_direct(&e->rc, ndb - LZMA_ALIGN_BITS,
					rest >> LZMA_ALIGN_BITS);
			rc_bit_tree_reverse(&e->rc, e->p.pos_align,
					LZMA_ALIGN_BITS,
					rest & ((1U << LZMA_ALIGN_BITS) - 1));
		}
	}
}

static void
enc_literal(lz1e *e, uint8_t byte)
{
	const uint32_t pos_state = (uint32_t)e->pos & e->pos_mask;
	rc_bit(&e->rc, &e->p.is_match[(e->state << LZMA_POS_STATES_MAX)
			+ pos_state], 0);
	const uint8_t prev_byte = e->pos > 0 ? e->buf[e->pos - 1] : 0;
	const uint32_t lit_state = ((uint32_t)(e->pos & e->lp_mask) << e->lc)
			+ (prev_byte >> (8 - e->lc));
	probability *lprobs = e->lit + ((size_t)lit_state << 8) + lit_state;
	uint32_t symbol = 1;
	if (e->state >= LZMA_LIT_STATES) {
		const uint32_t r0 = e->reps[0];
		uint32_t match_byte = 0;
		if (e->pos > r0)
			match_byte = e->buf[e->pos - 1 - r0];
		for (int i = 7; i >= 0; --i) {
			const uint32_t mb = (match_byte >> 7) & 1;
			match_byte <<= 1;
			const uint32_t bit = (byte >> i) & 1;
			rc_bit(&e->rc, &lprobs[0x100 + (mb << 8) + symbol], bit);
			symbol = (symbol << 1) | bit;
			if (mb != bit) {
				for (--i; i >= 0; --i) {
					const uint32_t b2 = (byte >> i) & 1;
					rc_bit(&e->rc, &lprobs[symbol], b2);
					symbol = (symbol << 1) | b2;
				}
				break;
			}
		}
	} else {
		for (int i = 7; i >= 0; --i) {
			const uint32_t bit = (byte >> i) & 1;
			rc_bit(&e->rc, &lprobs[symbol], bit);
			symbol = (symbol << 1) | bit;
		}
	}
	e->state = e->state < 4 ? 0 : (e->state < 10 ? e->state - 3
			: e->state - 6);
	++e->pos;
}

/* Encode symbols from the current position up to `end` (exclusive). */
static void
enc_run(lz1e *e, size_t end)
{
	while (e->pos < end) {
		const size_t pos = e->pos;
		uint32_t dist = 0;
		uint32_t len = mf_find(e, &dist, pos, e->nice_len, e->depth);
		if (len == 0) {
			enc_literal(e, e->buf[pos]);
			mf_insert(e, pos);
			continue;
		}
		const uint32_t pos_state = (uint32_t)pos & e->pos_mask;
		rc_bit(&e->rc, &e->p.is_match[(e->state << LZMA_POS_STATES_MAX)
				+ pos_state], 1);
		/* prefer rep0 when it gives the same length */
		int is_rep = 0;
		uint32_t rdist = 0;
		if (e->reps[0] < e->dict_size && pos > e->reps[0]
				&& e->reps[0] < pos) {
			const uint32_t r = e->reps[0] + 1;
			uint32_t l = 0;
			while (l < len && pos + l < e->len
					&& e->buf[pos + l] == e->buf[pos - r + l])
				++l;
			if (l == len)
				is_rep = 1;
		}
		if (is_rep) {
			rc_bit(&e->rc, &e->p.is_rep[e->state], 1);
			rc_bit(&e->rc, &e->p.is_rep0[(e->state
					<< LZMA_POS_STATES_MAX) + pos_state], 0);
			rc_bit(&e->rc, &e->p.is_rep0_long[(e->state
					<< LZMA_POS_STATES_MAX) + pos_state], 1);
			e->state = e->state < 7 ? 8 : 11;
			enc_len(e, len, pos_state);
			rdist = e->reps[0] + 1;
		} else {
			rc_bit(&e->rc, &e->p.is_rep[e->state], 0);
			e->state = e->state < 7 ? 7 : 10;
			enc_len(e, len, pos_state);
			enc_distance(e, dist);
			e->reps[3] = e->reps[2];
			e->reps[2] = e->reps[1];
			e->reps[1] = e->reps[0];
			e->reps[0] = dist;
			rdist = dist + 1;
		}
		for (uint32_t i = 0; i < len; ++i) {
			if (pos + i < e->len)
				mf_insert(e, pos + i);
		}
		e->pos += len;
	}
	(void)rdist;
}

/* ------------------------------------------------------------------ */
/* LZMA2 encoding                                                      */
/* ------------------------------------------------------------------ */

/* Compress `in[0..n)` with LZMA2 into `out`.  Returns the number of bytes
 * written (out must be large enough). */
static size_t
lzma2_encode(const uint8_t *in, size_t n, uint8_t *out, size_t out_size,
		const filter_spec *lz)
{
	lz1e e;
	lz1e_init(&e, in, n, lz);
	rc_init(&e.rc, out, out_size);
	size_t out_pos = 0;
	size_t pos = 0;
	int first = 1;
	while (pos < n) {
		uint32_t chunk_max = first ? CHUNK_MAX_FIRST : CHUNK_MAX_NEXT;
		size_t remaining = n - pos;
		size_t chunk = remaining < chunk_max ? remaining
				: chunk_max;
		/* Encode the chunk, limiting the packed size */
		const size_t start_pos = e.pos;
		const size_t rc_start = e.rc.out_pos;
		const size_t limit = pos + chunk;
		enc_run(&e, limit);
		rc_flush(&e.rc);
		const size_t packed = e.rc.out_pos - rc_start;
		const size_t uncomp = limit - start_pos;
		if (packed >= uncomp || packed > PACKED_MAX) {
			/* store as uncompressed chunks */
			e.rc.out_pos = rc_start;
			/* rewind the encoder state: re-encode is not needed
			 * because we discard the output and reset the range
			 * encoder, but the probability state has changed.  To
			 * stay consistent we re-create the encoder. */
			size_t p2 = start_pos;
			while (p2 < limit) {
				size_t k = limit - p2;
				if (k > UNCOMP_CHUNK_MAX)
					k = UNCOMP_CHUNK_MAX;
				out[out_pos++] = (uint8_t)(first ? 0x01 : 0x02);
				out[out_pos++] = (uint8_t)((k - 1) >> 8);
				out[out_pos++] = (uint8_t)(k - 1);
				memcpy(out + out_pos, in + p2, k);
				out_pos += k;
				p2 += k;
				first = 0;
			}
			pos = limit;
			continue;
		}
		/* write the chunk header */
		const uint32_t hi = (uint32_t)((uncomp - 1) >> 16);
		out[out_pos++] = (uint8_t)(0x80 | (first ? 0x40 : 0x00)
				| (first ? 0x20 : 0x00) | hi);
		out[out_pos++] = (uint8_t)((uncomp - 1) >> 8);
		out[out_pos++] = (uint8_t)(uncomp - 1);
		out[out_pos++] = (uint8_t)((packed - 1) >> 8);
		out[out_pos++] = (uint8_t)(packed - 1);
		if (first) {
			uint32_t props = 0;
			uint32_t b = 0;
			while ((1U << (b + 11)) < lz->dict && b < 30)
				++b;
			/* encode the dict size as in LZMA2 */
			props = 0;
			uint32_t ds = lz->dict;
			int bits = 0;
			while ((1U << (bits + 11)) < ds)
				++bits;
			/* find the props value: (2|(p&1)) << (p/2+11) == ds */
			int found = -1;
			for (int p = 0; p <= 40; ++p) {
				uint32_t v = (2 | (p & 1)) << (p / 2 + 11);
				if (v == ds) {
					found = p;
					break;
				}
			}
			props = found >= 0 ? (uint32_t)found : 40;
			out[out_pos++] = (uint8_t)props;
			first = 0;
		}
		memmove(out + out_pos, out + rc_start, packed);
		out_pos += packed;
		pos = limit;
	}
	out[out_pos++] = 0x00;   /* end marker */
	lz1e_free(&e);
	return out_pos;
}

/* ------------------------------------------------------------------ */
/* xz stream encoder                                                   */
/* ------------------------------------------------------------------ */

static void
write_u32le(uint8_t *p, uint32_t v)
{
	p[0] = (uint8_t)v;
	p[1] = (uint8_t)(v >> 8);
	p[2] = (uint8_t)(v >> 16);
	p[3] = (uint8_t)(v >> 24);
}

static void
write_u64le(uint8_t *p, uint64_t v)
{
	for (int i = 0; i < 8; ++i)
		p[i] = (uint8_t)(v >> (8 * i));
}

/* Compress one block: filter the data, LZMA2-encode it, and produce the
 * block bytes (header + data + padding + check).  Returns the total size. */
static size_t
encode_block(const uint8_t *in, size_t n, const filter_chain *fc,
		uint32_t check, uint8_t *out, size_t out_size,
		uint64_t *unpadded_out, uint64_t *uncomp_out, int with_sizes)
{
	uint8_t *fdata = malloc(n + 64);
	memcpy(fdata, in, n);
	/* apply the filters in order (all but the last) */
	uint8_t delta_hist[256];
	uint32_t delta_pos = 0;
	uint32_t x86_mask = 0, x86_pos = 0;
	for (int i = 0; i < fc->n - 1; ++i) {
		const filter_spec *f = &fc->f[i];
		if (f->id == FILTER_ID_DELTA)
			delta_coder(fdata, n, f->dist, 1, &delta_pos, delta_hist);
		else
			bcj_coder(&(filter_opt){ .id = (uint32_t)f->id,
					.start = f->start }, fdata, n, 0, 1,
					&x86_mask, &x86_pos, 0);
	}
	/* LZMA2 encode */
	uint8_t *comp = malloc(n + n / 8 + 65536);
	const filter_spec *lz = &fc->f[fc->n - 1];
	const size_t csize = lzma2_encode(fdata, n, comp, n + n / 8 + 65536, lz);
	free(fdata);

	/* build the block header */
	uint8_t hdr[1024];
	size_t hp = 0;
	hdr[hp++] = 0;      /* placeholder for the size */
	uint8_t flags = 0;
	uint8_t varb[10];
	if (with_sizes) {
		flags |= 0x40 | 0x80;
		hp += varint_encode(csize, hdr + hp);
		hp += varint_encode(n, hdr + hp);
	}
	hdr[hp++] = flags;
	/* filter flags */
	for (int i = 0; i < fc->n; ++i) {
		const filter_spec *f = &fc->f[i];
		if (f->id == FID_LZMA2) {
			hp += varint_encode(0x21, hdr + hp);
			uint32_t props = 40;
			for (int p = 0; p <= 40; ++p) {
				const uint32_t v = (2 | (p & 1)) << (p / 2 + 11);
				if (v == f->dict) {
					props = (uint32_t)p;
					break;
				}
			}
			hp += varint_encode(1, hdr + hp);
			hdr[hp++] = (uint8_t)props;
		} else if (f->id == FID_LZMA1) {
			hp += varint_encode(0x4000000000000001ULL, hdr + hp);
			hp += varint_encode(0, hdr + hp);
		} else if (f->id == FILTER_ID_DELTA) {
			hp += varint_encode(FILTER_ID_DELTA, hdr + hp);
			hp += varint_encode(1, hdr + hp);
			hdr[hp++] = (uint8_t)(f->dist - 1);
		} else {
			hp += varint_encode(f->id, hdr + hp);
			hp += varint_encode(4, hdr + hp);
			hdr[hp++] = (uint8_t)f->start;
			hdr[hp++] = (uint8_t)(f->start >> 8);
			hdr[hp++] = (uint8_t)(f->start >> 16);
			hdr[hp++] = (uint8_t)(f->start >> 24);
		}
	}
	while (hp % 4)
		hdr[hp++] = 0;
	const size_t hsize = hp + 4;
	hdr[0] = (uint8_t)((hsize / 4) - 1);
	write_u32le(hdr + hp, crc32_buf(hdr, hp));
	/* assemble the block */
	size_t total = 0;
	memcpy(out + total, hdr, hsize);
	total += hsize;
	memcpy(out + total, comp, csize);
	total += csize;
	const size_t npad = (4 - (csize % 4)) % 4;
	memset(out + total, 0, npad);
	total += npad;
	uint8_t chk[64];
	check_state cs;
	check_init_state(&cs, check);
	check_upd(&cs, in, n);
	check_fin(&cs, chk);
	memcpy(out + total, chk, check_table[check].size);
	total += check_table[check].size;
	*unpadded_out = hsize + csize + check_table[check].size;
	*uncomp_out = n;
	free(comp);
	return total;
}

/* Compress the input into an .xz stream */
static int
xz_compress(file_r *fr, sink *s)
{
	const filter_chain *fc = &o.chains[0];
	const uint32_t dict = fc->f[fc->n - 1].dict;
	uint32_t check = o.check;
	/* stream header */
	uint8_t hdr[12];
	hdr[0] = 0xFD; hdr[1] = 0x37; hdr[2] = 0x7A; hdr[3] = 0x58;
	hdr[4] = 0x5A; hdr[5] = 0x00;
	hdr[6] = 0x00;
	hdr[7] = (uint8_t)check;
	write_u32le(hdr + 8, crc32_buf(hdr + 6, 2));
	if (s->write(s->ctx, hdr, 12))
		return E_MEM;

	uint64_t n_blocks = 0;
	uint64_t total_uncomp = 0;
	size_t buf_cap = 0;
	uint8_t *inbuf = NULL;
	uint8_t *outbuf = NULL;
	uint64_t block_size = o.block_size;
	if (block_size == 0)
		block_size = (uint64_t)dict * 3;

	size_t have = 0;
	int eof = 0;
	while (!eof || have > 0) {
		/* fill the block buffer */
		while (!eof && have < block_size) {
			if (buf_cap < have + 65536) {
				buf_cap = have + 65536 + 65536;
				inbuf = realloc(inbuf, buf_cap);
				outbuf = realloc(outbuf, buf_cap * 2 + 65536);
			}
			const size_t got = fr_read(fr, inbuf + have,
					block_size - have);
			have += got;
			prog_in += got;
			if (got == 0) {
				eof = 1;
				break;
			}
		}
		if (have == 0 && eof)
			break;
		/* encode the block */
		uint64_t unpadded = 0, uncomp = 0;
		const size_t total = encode_block(inbuf, have, fc, check,
				outbuf, buf_cap * 2 + 65536, &unpadded,
				&uncomp, o.threads != 1);
		if (s->write(s->ctx, outbuf, total))
			return E_MEM;
		prog_out += total;
		++n_blocks;
		total_uncomp += uncomp;
		/* index record */
		index_record(unpadded, uncomp);
		have = 0;
		if (eof)
			break;
	}
	/* index + footer */
	return finish_stream(s, n_blocks);
}

int
compress_stream(file_r *fr, sink *s, const char *name)
{
	(void)name;
	if (o.format == FORMAT_LZIP) {
		msg_error("Compression of lzip files (.lz) is not supported");
		return E_OPTIONS;
	}
	if (o.format == FORMAT_XZ)
		return xz_compress(fr, s);
	return E_OK;
}
