/* ------------------------------------------------------------------ */
/* index and stream footer                                             */
/* ------------------------------------------------------------------ */

typedef struct {
	uint64_t unpadded;
	uint64_t uncomp;
} idx_rec;

static idx_rec *idx_recs;
static size_t n_idx_recs, idx_cap;

static void
index_record(uint64_t unpadded, uint64_t uncomp)
{
	if (n_idx_recs == idx_cap) {
		idx_cap = idx_cap ? idx_cap * 2 : 64;
		idx_recs = realloc(idx_recs, idx_cap * sizeof(idx_rec));
	}
	idx_recs[n_idx_recs].unpadded = unpadded;
	idx_recs[n_idx_recs].uncomp = uncomp;
	++n_idx_recs;
}

static int
finish_stream(sink *s, uint32_t check)
{
	/* index */
	uint8_t *idx = malloc(16 + n_idx_recs * 20);
	size_t p = 0;
	idx[p++] = 0x00;
	p += varint_encode(n_idx_recs, idx + p);
	for (size_t i = 0; i < n_idx_recs; ++i) {
		p += varint_encode(idx_recs[i].unpadded, idx + p);
		p += varint_encode(idx_recs[i].uncomp, idx + p);
	}
	while (p % 4)
		idx[p++] = 0;
	write_u32le(idx + p, crc32_buf(idx, p));
	p += 4;
	if (s->write(s->ctx, idx, p))
		return E_MEM;
	prog_out += p;
	/* footer */
	uint8_t ft[12];
