import sys; sys.path.insert(0,'/tmp/t')
import lzdec
from lzdec import RD
d=open('h.lzma','rb').read()[13:]
lc,lp,pb=3,0,2
for brk in [0,1]:
  rd=RD(d)
  probs=[1024]*(17565+(0x300<<(lc+lp)))
  pos_mask=(1<<pb)-1; lp_mask=(1<<lp)-1
  state=0; reps=[0,0,0,0]
  out=bytearray()
  ok=True
  try:
    for i in range(20):
        pos=len(out); ps=pos&pos_mask; mi=(state<<4)+ps
        if rd.bit(probs,lzdec.OFF_IS_MATCH+mi)==0:
            prev=out[pos-1] if pos>0 else 0
            lit_state=((pos&lp_mask)<<lc)+(prev>>(8-lc))
            base=17565+lit_state*0x300
            sym=1
            if state>=7:
                mb=out[pos-1-reps[0]]
                for k in range(8):
                    mb_bit=(mb>>7)&1; mb=(mb<<1)&0xFF
                    b=rd.bit(probs,base+0x100+(mb_bit<<8)+sym)
                    sym=(sym<<1)|b
                    if brk and mb_bit!=b: break
                while sym<0x100:
                    b=rd.bit(probs,base+sym)
                    sym=(sym<<1)|b
            else:
                for k in range(8):
                    sym=(sym<<1)|rd.bit(probs,base+sym)
            state=[0,0,0,0,1,2,3,4,5,6,4,5][state]
            out.append(sym&0xFF)
        else:
            rep=rd.bit(probs,lzdec.OFF_IS_REP+state)
            if rep:
                r0=rd.bit(probs,lzdec.OFF_IS_REP0+mi)
                if r0==0:
                    if rd.bit(probs,lzdec.OFF_IS_REP0_LONG+mi)==0:
                        state=9 if state<7 else 11
                        out.append(out[pos-1-reps[0]])
                    else:
                        state=8 if state<7 else 11
                        ln=lzdec.decode_len(rd,probs,ps)
                        for _ in range(ln): out.append(out[len(out)-1-reps[0]])
                else:
                    if rd.bit(probs,lzdec.OFF_IS_REP1+state)==0: dist=reps[1]
                    else:
                        if rd.bit(probs,lzdec.OFF_IS_REP2+state)==0: dist=reps[2]
                        else: dist=reps[3]; reps[3]=reps[2]
                        reps[2]=reps[1]
                    reps[1]=reps[0]; reps[0]=dist
                    state=8 if state<7 else 11
                    ln=lzdec.decode_len(rd,probs,ps)
                    for _ in range(ln): out.append(out[len(out)-1-dist])
            else:
                ln=lzdec.decode_len(rd,probs,ps)
                state=7 if state<7 else 10
                slot=rd.tree(probs,lzdec.OFF_POS_SLOT,6)
                dist=slot if slot<4 else 0
                if slot>=4:
                    ndb=(slot>>1)-1
                    dist=(2|(slot&1))<<ndb
                    if slot<14: dist+=rd.tree_rev(probs,lzdec.OFF_POS_SPECIAL+dist-slot,ndb)
                    else:
                        dist+=rd.direct(ndb-4)<<4
                        dist+=rd.tree_rev(probs,lzdec.OFF_POS_ALIGN,4)
                if dist==0xFFFFFFFF: break
                reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
                for _ in range(ln): out.append(out[len(out)-1-dist])
    except Exception as e:
        ok=False
        print('brk=%d EXC %s'%(brk,e))
    print('brk=%d out=%r match=%s'%(brk,bytes(out),bytes(out)==b'hello world\n'))
