import sys; sys.path.insert(0,'/tmp/t')
import lzdec
from lzdec import RD
data=open('d2.bin','rb').read()
d=open('d2.lzma','rb').read()[13:]
lc,lp,pb=3,0,2
for align_size in [4,16]:
    LIT = 17051 + align_size + 514
    print('align_size=%d -> LIT=%d'%(align_size,LIT))
    for lit_off in [LIT, LIT-12, LIT+12]:
        rd=RD(d)
        probs=[1024]*(lit_off+(0x300<<(lc+lp)))
        PA=17051-align_size if False else 676+16371
        ALIGN=PA
        LCHOICE=PA+align_size
        LLOW=LCHOICE+1
        LCHOICE2=LLOW+128
        LMID=LCHOICE2+1
        LHIGH=LMID+128
        pos_mask=(1<<pb)-1; lp_mask=(1<<lp)-1
        state=0; reps=[0,0,0,0]
        out=bytearray()
        try:
            while len(out)<len(data):
                pos=len(out); ps=pos&pos_mask; mi=(state<<4)+ps
                if rd.bit(probs,mi)==0:
                    prev=out[pos-1] if pos>0 else 0
                    lit_state=((pos&lp_mask)<<lc)+(prev>>(8-lc))
                    base=lit_off+lit_state*0x300
                    sym=1
                    if state>=7:
                        mb=out[pos-1-reps[0]]
                        for k in range(8):
                            mb_bit=(mb>>7)&1; mb=(mb<<1)&0xFF
                            b=rd.bit(probs,base+0x100+(mb_bit<<8)+sym)
                            sym=(sym<<1)|b
                            if mb_bit!=b: break
                        while sym<0x100:
                            sym=(sym<<1)|rd.bit(probs,base+sym)
                    else:
                        for k in range(8):
                            sym=(sym<<1)|rd.bit(probs,base+sym)
                    state=[0,0,0,0,1,2,3,4,5,6,4,5][state]
                    out.append(sym&0xFF)
                else:
                    rep=rd.bit(probs,192+state)
                    if rep:
                        r0=rd.bit(probs,204+mi)
                        if r0==0:
                            if rd.bit(probs,420+mi)==0:
                                state=9 if state<7 else 11
                                out.append(out[pos-1-reps[0]])
                            else:
                                state=8 if state<7 else 11
                                ln=lzdec.decode_len(rd,probs,ps) if False else decode_len2(rd,probs,ps,LCHOICE,LLOW,LCHOICE2,LMID,LHIGH)
                                for _ in range(ln): out.append(out[len(out)-1-reps[0]])
                        else:
                            if rd.bit(probs,396+state)==0: dist=reps[1]
                            else:
                                if rd.bit(probs,408+state)==0: dist=reps[2]
                                else: dist=reps[3]; reps[3]=reps[2]
                                reps[2]=reps[1]
                            reps[1]=reps[0]; reps[0]=dist
                            state=8 if state<7 else 11
                            ln=decode_len2(rd,probs,ps,LCHOICE,LLOW,LCHOICE2,LMID,LHIGH)
                            for _ in range(ln): out.append(out[len(out)-1-dist])
                    else:
                        ln=decode_len2(rd,probs,ps,LCHOICE,LLOW,LCHOICE2,LMID,LHIGH)
                        state=7 if state<7 else 10
                        slot=rd.tree(probs,612,6)
                        dist=slot if slot<4 else 0
                        if slot>=4:
                            ndb=(slot>>1)-1
                            dist=(2|(slot&1))<<ndb
                            if slot<14: dist+=rd.tree_rev(probs,676+dist-slot,ndb)
                            else:
                                dist+=rd.direct(ndb-4)<<4
                                dist+=rd.tree_rev(probs,ALIGN,4)
                        if dist==0xFFFFFFFF: break
                        reps[3]=reps[2]; reps[2]=reps[1]; reps[1]=reps[0]; reps[0]=dist
                        for _ in range(ln): out.append(out[len(out)-1-dist])
            print('   lit_off=%d match=%s outlen=%d'%(lit_off,bytes(out)==data,len(out)))
