			const uint32_t cap = 273 < lim ? 273 : (uint32_t)lim;
			while (l < cap && e->buf[pos + l] == e->buf[pos - r + l])
				++l;
			if (l >= 2 && l >= len) {
				is_rep = 1;
				len = l;
			}
		}
		rc_bit(&e->rc, &e->p.is_match[(e->state << LZMA_POS_STATES_MAX)
