./compile.sh >/dev/null 2>&1; cd /tmp/t && /workspace/executable -T1 -c zeros.bin > myz.xz && ls -l myz.xz zeros.bin.xz; python3 -c "
import struct
for f in ['myz.xz','zeros.bin.xz']:
    d=open(f,'rb').read()
    hdrsz=(d[12]+1)*4
    bs=struct.unpack('<I',d[-8:-4])[0]; isize=(bs+1)*4; istart=len(d)-12-isize
    def vi(b,p):
        v=0;sh=0
        while True:
            c=b[p];p+=1; v|=(c&0x7f)<<sh
            if not c&0x80: return v,p
            sh+=7
    p=istart+1
    n,p=vi(d,p); recs=[]
    for _ in range(n):
        u,p=vi(d,p); c,p=vi(d,p); recs.append((u,c))
    u,c=recs[0]; compsz=u-hdrsz-8
    comp=d[12+hdrsz:12+hdrsz+compsz]
    print(f,'comp:',comp[:24].hex())
""}

