/* ------------------------------------------------------------------ */
/* list mode                                                           */
/* ------------------------------------------------------------------ */

static const char *check_name(uint32_t t)
{
	return check_table[t].name;
}

static void
human_size(char *buf, size_t n, uint64_t v)
{
	if (v >= 10240ULL * 1024)
		snprintf(buf, n, "%.1f MiB", (double)v / (1024.0 * 1024));
	else if (v >= 10240)
		snprintf(buf, n, "%.1f KiB", (double)v / 1024.0);
	else
		snprintf(buf, n, "%llu B", (unsigned long long)v);
}

/* Walk the .xz stream headers without decoding the blocks. */
int
list_file(file_r *fr, const char *name)
{
	if (o.format != FORMAT_AUTO && o.format != FORMAT_XZ) {
		msg_error("%s: %s: File format not recognized", msg_progname(),
				name);
		return E_FORMAT;
	}
	uint8_t hdr[12];
	int ret = fr_read_exact(fr, hdr, 12);
	if (ret)
		return E_BUF;
	if (memcmp(hdr, "\xFD\x37\x7A\x58\x5A\x00", 6))
		return E_FORMAT;
	const uint32_t check = hdr[7];
	uint64_t total_comp = 0, total_uncomp = 0, padding = 0;
	uint64_t n_streams = 0, n_blocks = 0;
	for (;;) {
		/* this is a stream */
		++n_streams;
		uint64_t s_comp = 0, s_uncomp = 0, s_pad = 0, s_blocks = 0;
		/* walk the blocks */
		for (;;) {
			uint8_t b;
			if (fr_read_exact(fr, &b, 1))
				return E_BUF;
			if (b == 0)
				break;   /* index */
			const uint32_t hsize = ((uint32_t)b + 1) * 4;
			uint8_t hbuf[1024];
			hbuf[0] = b;
			if (fr_read_exact(fr, hbuf + 1, hsize - 1))
				return E_BUF;
			size_t p = 2;
			if (hbuf[1] & 0x40) {
				uint64_t v;
				if (fr_varint(fr, &v) == 0) {
					/* not reached: parse from hbuf */
				}
			}
			(void)p;
			/* skip to the check field: parse the header fields */
			size_t q = 2;
			uint64_t comp_size = 0, uncomp_size = 0;
			if (hbuf[1] & 0x40) {
				uint64_t v = 0;
				int sh = 0;
				for (;;) {
					if (q >= hsize)
						return E_DATA;
					const uint8_t c = hbuf[q++];
					v |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
				}
				comp_size = v;
			}
			if (hbuf[1] & 0x80) {
				uint64_t v = 0;
				int sh = 0;
				for (;;) {
					if (q >= hsize)
						return E_DATA;
					const uint8_t c = hbuf[q++];
					v |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
				}
				uncomp_size = v;
			}
			/* the number of filters */
			const uint32_t nf = (hbuf[1] & 3) + 1;
			for (uint32_t i = 0; i < nf; ++i) {
				uint64_t fid = 0, psz = 0;
				int sh = 0;
				for (;;) {
					if (q >= hsize)
						return E_DATA;
					const uint8_t c = hbuf[q++];
					fid |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
				}
				sh = 0;
				for (;;) {
					if (q >= hsize)
						return E_DATA;
					const uint8_t c = hbuf[q++];
					psz |= (uint64_t)(c & 0x7F) << sh;
					if (!(c & 0x80))
						break;
					sh += 7;
				}
				q += psz;
			}
			const uint64_t cs = comp_size ? comp_size
					: (uint64_t)(hsize);
			const uint64_t npad = (4 - (cs % 4)) % 4;
			s_comp += hsize + cs + npad + check_table[check].size;
			s_uncomp += uncomp_size;
			++s_blocks;
			/* skip the compressed data, padding and check */
			off_t skip = (off_t)cs + (off_t)npad
					+ (off_t)check_table[check].size;
			if (fseek(fr->f, skip, SEEK_CUR))
