	rc_init(&e.rc, out, out_size);
	enc_run(&e, n);
	if (eopm) {
		/* end of payload marker: dist = 0xFFFFFFFF */
		const uint32_t pos_state = (uint32_t)e.pos & e.pos_mask;
		rc_bit(&e.rc, &e.p.is_match[(e.state << LZMA_POS_STATES_MAX)
				+ pos_state], 1);
