		e.state = e.state < 7 ? 7 : 10;
		enc_len(&e, 2, pos_state);
		rc_bit_tree(&e.rc, e.p.pos_slot, 6, 63);
		rc_direct(&e.rc, 26, 0x3FFFFFF);
		rc_bit_tree_reverse(&e.rc, e.p.pos_align, 4, 15);
	}
	rc_flush(&e.rc);
	const size_t r = e.rc.out_pos;
	lz1e_free(&e);
	return r;
}

/* Compress the whole input with LZMA1 (for .lzma / raw) */
static int
lzma1_compress(file_r *fr, sink *s, int raw)
{
	const filter_chain *fc = &o.chains[0];
	const filter_spec *lz = &fc->f[fc->n - 1];
	if (!raw) {
		/* .lzma header */
		uint8_t hdr[13];
		uint32_t props = (lz->pb * 5 + lz->lp) * 9 + lz->lc;
		uint32_t dict = lz->dict;
		if (o.format == FORMAT_LZMA && !o.lzma_explicit) {
			/* round up to a valid LZMA1 dictionary size */
			uint32_t v = 1;
			while (v < dict && v < 0x80000000U)
				v <<= 1;
			dict = v;
		}
		hdr[0] = (uint8_t)props;
		hdr[1] = (uint8_t)dict;
		hdr[2] = (uint8_t)(dict >> 8);
		hdr[3] = (uint8_t)(dict >> 16);
		hdr[4] = (uint8_t)(dict >> 24);
		for (int i = 0; i < 8; ++i)
			hdr[5 + i] = 0xFF;   /* size unknown */
		if (s->write(s->ctx, hdr, 13))
			return E_MEM;
		prog_out += 13;
	}
	/* read the input and encode */
	size_t cap = 1 << 16;
	uint8_t *inbuf = malloc(cap);
	size_t have = 0;
	uint8_t tmp[65536];
	for (;;) {
		const size_t got = fr_read(fr, tmp, sizeof(tmp));
		prog_in += got;
		if (got == 0)
			break;
		if (have + got > cap) {
			while (have + got > cap)
				cap *= 2;
			inbuf = realloc(inbuf, cap);
		}
		memcpy(inbuf + have, tmp, got);
		have += got;
	}
	/* apply the filters */
	uint8_t delta_hist[256];
	uint32_t delta_pos = 0;
	uint32_t x86_mask = 0, x86_pos = 0;
	for (int i = fc->n - 2; i >= 0; --i) {
		const filter_spec *f = &fc->f[i];
		if (f->id == FILTER_ID_DELTA)
			delta_coder(inbuf, have, f->dist, 1, &delta_pos,
					delta_hist);
		else
