					.start = f->start }, inbuf, have, 0, 1,
					&x86_mask, &x86_pos, 0);
	}
	uint8_t *outbuf = malloc(have + 4096);
	const size_t osz = lzma1_encode(inbuf, have, outbuf, have + 4096, lz,
			o.format == FORMAT_LZMA || !raw);
	if (s->write(s->ctx, outbuf, osz))
		return E_MEM;
	prog_out += osz;
	free(inbuf);
	free(outbuf);
	return E_OK;
}

