	if (o.format == FORMAT_XZ || o.format == FORMAT_AUTO)
		return xz_compress(fr, s);
	if (o.format == FORMAT_LZMA)
		return lzma1_compress(fr, s, 0);
	if (o.format == FORMAT_RAW)
		return lzma1_compress(fr, s, 1);
