int
raw_decode(file_r *fr, sink *out)
{
	const filter_chain *fc = &o.chains[0];
	const filter_spec *lz = &fc->f[fc->n - 1];
	block_out bo;
	memset(&bo, 0, sizeof(bo));
	bo.out = out;
	for (uint32_t i = 0; i < (uint32_t)fc->n; ++i) {
		filter_opt fo;
		memset(&fo, 0, sizeof(fo));
		fo.id = (uint32_t)fc->f[i].id;
		fo.dist = fc->f[i].dist;
		fo.start = fc->f[i].start;
		if (fc->f[i].id == FILTER_ID_DELTA) {
			fo.props[0] = (uint8_t)(fc->f[i].dist - 1);
			fo.props_size = 1;
		} else if (fo.id != (uint32_t)FID_LZMA2
				&& fo.id != (uint32_t)FID_LZMA1) {
			fo.props_size = 4;
			fo.props[0] = (uint8_t)fc->f[i].start;
			fo.props[1] = (uint8_t)(fc->f[i].start >> 8);
			fo.props[2] = (uint8_t)(fc->f[i].start >> 16);
			fo.props[3] = (uint8_t)(fc->f[i].start >> 24);
		}
		bo.filters[i] = fo;
	}
	bo.n_filters = (uint32_t)fc->n;

	int ret;
	if (lz->id == FID_LZMA2) {
		lzma2_dec lz;
		lzma2_dec_init(&lz, &bo, block_put);
		if (lzma_dec_alloc_dict(&lz.d, lz->dict))
			return E_MEM;
		if (lzma_dec_alloc_probs(&lz.d))
			return E_MEM;
		lz1_ctx ctx;
		ctx.fr = fr;
		rd_init(&lz.d.src, lz1_fill, &ctx);
		ret = lzma2_dec_run(&lz);
		lzma_dec_flush_out(&lz.d);
		lzma_dec_free_dict(&lz.d);
	} else {
		ret = lzma1_stream_decode(fr, out, lz->lc, lz->lp, lz->pb,
				lz->dict, UINT64_MAX, 0);
		return ret;
	}
	if (block_flush(&bo))
		return E_MEM;
	if (ret != E_STREAM_END)
		return ret == E_OK ? E_DATA : ret;
	return E_OK;
}
